window.GAME = {"cards":[{"id":"G1","nhom":"G","nhomTen":"GÓC","ten":"Góc nội tiếp","khi":"Hai góc có đỉnh trên đường tròn cùng chắn một cung; góc ở tâm và góc nội tiếp cùng chắn một cung.","ra":"Hai góc nội tiếp cùng chắn một cung thì bằng nhau; góc nội tiếp bằng nửa góc ở tâm cùng chắn cung đó.","mau":"#C62828","rar":1,"doc":false},{"id":"G2","nhom":"G","nhomTen":"GÓC","ten":"Góc chắn nửa đường tròn","khi":"Điểm nằm trên đường tròn có đường kính đã biết.","ra":"Góc nhìn đường kính bằng 90°.","mau":"#C62828","rar":1,"doc":false},{"id":"G3","nhom":"G","nhomTen":"GÓC","ten":"Góc tạo bởi tiếp tuyến và dây","khi":"Tiếp tuyến tại một điểm và một dây đi qua điểm đó.","ra":"Bằng góc nội tiếp cùng chắn cung nằm trong góc.","mau":"#C62828","rar":1,"doc":false},{"id":"G4","nhom":"G","nhomTen":"GÓC","ten":"Cùng phụ – cùng bù","khi":"Hai góc cùng cộng với một góc bằng 90° (hoặc 180°).","ra":"Hai góc đó bằng nhau.","mau":"#C62828","rar":1,"doc":false},{"id":"G5","nhom":"G","nhomTen":"GÓC","ten":"Góc và song song","khi":"Hai đường thẳng song song bị một đường thẳng cắt.","ra":"Các góc so le trong, đồng vị bằng nhau (và ngược lại).","mau":"#C62828","rar":1,"doc":false},{"id":"G6","nhom":"G","nhomTen":"GÓC","ten":"Tam giác cân","khi":"Hai cạnh bằng nhau, hai góc bằng nhau; phân giác đồng thời là đường cao.","ra":"Hai góc đáy bằng nhau; đường cao, trung tuyến, phân giác, trung trực từ đỉnh trùng nhau.","mau":"#C62828","rar":1,"doc":false},{"id":"G7","nhom":"G","nhomTen":"GÓC","ten":"Tổng ba góc","khi":"Tam giác vuông, hoặc biết hai góc của tam giác.","ra":"Tổng ba góc bằng 180°; hai góc nhọn của tam giác vuông phụ nhau.","mau":"#C62828","rar":1,"doc":false},{"id":"G8","nhom":"G","nhomTen":"GÓC","ten":"Tia phân giác","khi":"Tia phân giác của một góc.","ra":"Chia góc thành hai góc bằng nhau; điểm trên tia phân giác cách đều hai cạnh của góc.","mau":"#C62828","rar":1,"doc":false},{"id":"V1","nhom":"V","nhomTen":"TAM GIÁC VUÔNG","ten":"Hệ thức lượng","khi":"Tam giác vuông có đường cao ứng với cạnh huyền.","ra":"AB² = BH.BC; AH² = HB.HC; AH.BC = AB.AC.","mau":"#0F766E","rar":1,"doc":false},{"id":"V2","nhom":"V","nhomTen":"TAM GIÁC VUÔNG","ten":"Trung tuyến ứng với cạnh huyền","khi":"Tam giác vuông có trung điểm của cạnh huyền.","ra":"Trung tuyến bằng nửa cạnh huyền ⇒ có hai tam giác cân.","mau":"#0F766E","rar":1,"doc":false},{"id":"V3","nhom":"V","nhomTen":"TAM GIÁC VUÔNG","ten":"Tỉ số lượng giác","khi":"Cần tính cạnh qua góc, hoặc đề có sin, cos, tan.","ra":"sin = đối/huyền, cos = kề/huyền, tan = đối/kề; hai góc phụ nhau thì sin góc này bằng cos góc kia.","mau":"#0F766E","rar":1,"doc":false},{"id":"V4","nhom":"V","nhomTen":"TAM GIÁC VUÔNG","ten":"Định lí Pythagore","khi":"Biết hai cạnh của tam giác vuông, hoặc cần so sánh bình phương.","ra":"Bình phương cạnh huyền bằng tổng bình phương hai cạnh góc vuông.","mau":"#0F766E","rar":1,"doc":false},{"id":"V5","nhom":"V","nhomTen":"TAM GIÁC VUÔNG","ten":"Hình chữ nhật","khi":"Tứ giác có ba góc vuông.","ra":"Hai đường chéo bằng nhau và cắt nhau tại trung điểm mỗi đường.","mau":"#0F766E","rar":1,"doc":false},{"id":"N1","nhom":"N","nhomTen":"ĐƯỜNG TRÒN – NỘI TIẾP","ten":"Cùng nhìn dưới góc vuông","khi":"Hai điểm cùng nhìn một đoạn thẳng dưới góc 90°.","ra":"Hai điểm đó và hai đầu đoạn thẳng cùng thuộc đường tròn đường kính đoạn đó.","mau":"#1565C0","rar":3,"doc":false},{"id":"N2","nhom":"N","nhomTen":"ĐƯỜNG TRÒN – NỘI TIẾP","ten":"Dấu hiệu tứ giác nội tiếp (đọc thêm)","khi":"Tổng hai góc đối bằng 180°; hoặc hai đỉnh kề cùng nhìn một cạnh dưới hai góc bằng nhau.","ra":"Tứ giác nội tiếp. Chỉ là kiến thức giới thiệu thêm: không được dùng trực tiếp, khi dùng phải chứng minh lại (xem khung Lưu ý ngay dưới). Nên đưa về nếu được.","mau":"#1565C0","rar":3,"doc":true},{"id":"N3","nhom":"N","nhomTen":"ĐƯỜNG TRÒN – NỘI TIẾP","ten":"Tính chất tứ giác nội tiếp","khi":"Tứ giác đã nội tiếp.","ra":"Hai góc đối bù nhau; góc ngoài bằng góc trong ở đỉnh đối; hai góc cùng nhìn một cạnh bằng nhau.","mau":"#1565C0","rar":3,"doc":false},{"id":"N4","nhom":"N","nhomTen":"ĐƯỜNG TRÒN – NỘI TIẾP","ten":"Đường kính và dây","khi":"Đường thẳng qua tâm với một dây; hai đường tròn cắt nhau.","ra":"Đường kính ⊥ dây ⇔ đi qua trung điểm của dây; dây chung ⊥ đường nối tâm.","mau":"#1565C0","rar":3,"doc":false},{"id":"N5","nhom":"N","nhomTen":"ĐƯỜNG TRÒN – NỘI TIẾP","ten":"Đường trung trực","khi":"Một điểm cách đều hai đầu đoạn thẳng (bán kính, hai tiếp tuyến…).","ra":"Điểm đó nằm trên trung trực; hai điểm như vậy xác định trung trực.","mau":"#1565C0","rar":3,"doc":false},{"id":"T1","nhom":"T","nhomTen":"TIẾP TUYẾN","ten":"Tiếp tuyến và bán kính","khi":"Đường thẳng tiếp xúc với đường tròn tại một điểm.","ra":"Tiếp tuyến vuông góc với bán kính tại tiếp điểm.","mau":"#6A1B9A","rar":3,"doc":false},{"id":"T2","nhom":"T","nhomTen":"TIẾP TUYẾN","ten":"Hai tiếp tuyến cắt nhau","khi":"Từ một điểm A kẻ hai tiếp tuyến AB, AC.","ra":"AB = AC; AO là phân giác của ∠BAC, ∠BOC; AO là trung trực của BC.","mau":"#6A1B9A","rar":3,"doc":false},{"id":"T3","nhom":"T","nhomTen":"TIẾP TUYẾN","ten":"Tiếp tuyến tại hai đầu đường kính","khi":"Tiếp tuyến tại A và tại B, với AB là đường kính.","ra":"Hai tiếp tuyến song song (cùng vuông góc với AB).","mau":"#6A1B9A","rar":3,"doc":false},{"id":"S1","nhom":"S","nhomTen":"ĐỒNG DẠNG – BẰNG NHAU","ten":"Tam giác đồng dạng","khi":"Hai góc bằng nhau (g.g); một góc bằng nhau xen giữa hai cạnh tỉ lệ (c.g.c).","ra":"Các góc tương ứng bằng nhau; các cạnh tương ứng tỉ lệ.","mau":"#B8860B","rar":3,"doc":false},{"id":"S2","nhom":"S","nhomTen":"ĐỒNG DẠNG – BẰNG NHAU","ten":"Đẳng thức tích","khi":"Kết luận hoặc ý trước có dạng a.b = c.d.","ra":"Đổi thành tỉ lệ thức, đọc tên cặp tam giác đồng dạng.","mau":"#B8860B","rar":3,"doc":false},{"id":"S3","nhom":"S","nhomTen":"ĐỒNG DẠNG – BẰNG NHAU","ten":"Tam giác vuông đồng dạng","khi":"Hai tam giác vuông có chung (hoặc bằng) một góc nhọn.","ra":"Hai tam giác đồng dạng (g.g).","mau":"#B8860B","rar":3,"doc":false},{"id":"S4","nhom":"S","nhomTen":"ĐỒNG DẠNG – BẰNG NHAU","ten":"Tam giác bằng nhau","khi":"Hai tam giác có ba yếu tố bằng nhau (c.g.c, c.c.c, g.c.g).","ra":"Các cạnh, các góc tương ứng bằng nhau.","mau":"#B8860B","rar":3,"doc":false},{"id":"P1","nhom":"P","nhomTen":"SONG SONG – THALES","ten":"Định lí Thales","khi":"Một đường thẳng song song với một cạnh của tam giác.","ra":"Các đoạn thẳng tương ứng tỉ lệ (định lí Thales và hệ quả).","mau":"#2E7D32","rar":2,"doc":false},{"id":"P2","nhom":"P","nhomTen":"SONG SONG – THALES","ten":"Đường trung bình","khi":"Hai trung điểm của hai cạnh tam giác (hình thang).","ra":"Đường trung bình song song với cạnh thứ ba và bằng nửa cạnh đó.","mau":"#2E7D32","rar":2,"doc":false},{"id":"P3","nhom":"P","nhomTen":"SONG SONG – THALES","ten":"Cùng vuông góc","khi":"Hai đường thẳng cùng vuông góc với một đường thẳng.","ra":"Hai đường thẳng đó song song.","mau":"#2E7D32","rar":2,"doc":false},{"id":"P4","nhom":"P","nhomTen":"SONG SONG – THALES","ten":"Hình bình hành","khi":"Tứ giác có một cặp cạnh đối song song và bằng nhau.","ra":"Hai đường chéo cắt nhau tại trung điểm mỗi đường.","mau":"#2E7D32","rar":2,"doc":false},{"id":"P5","nhom":"P","nhomTen":"SONG SONG – THALES","ten":"Đường phân giác","khi":"Tia phân giác của một góc trong tam giác.","ra":"Chia cạnh đối diện thành hai đoạn tỉ lệ với hai cạnh kề.","mau":"#2E7D32","rar":2,"doc":false},{"id":"Q1","nhom":"Q","nhomTen":"ĐỒNG QUY","ten":"Trực tâm","khi":"Hai đường cao của một tam giác cắt nhau.","ra":"Giao điểm là trực tâm: đường thẳng nối đỉnh còn lại với nó vuông góc với cạnh đối.","mau":"#00838F","rar":3,"doc":false},{"id":"Q2","nhom":"Q","nhomTen":"ĐỒNG QUY","ten":"Tâm đường tròn ngoại tiếp","khi":"Tam giác nội tiếp đường tròn (O).","ra":"OA = OB = OC; O nằm trên trung trực của mỗi cạnh.","mau":"#00838F","rar":3,"doc":false},{"id":"K1","nhom":"K","nhomTen":"ĐỔI KẾT LUẬN","ten":"Thẳng hàng","khi":"Kết luận “ba điểm thẳng hàng”.","ra":"Đổi thành: góc bẹt; hai tia trùng nhau; điểm trùng; hai đường thẳng qua một điểm cùng vuông góc (song song) với một đường.","mau":"#37474F","rar":2,"doc":false},{"id":"K2","nhom":"K","nhomTen":"ĐỔI KẾT LUẬN","ten":"Trung điểm","khi":"Kết luận “là trung điểm”.","ra":"Đổi thành: hai đoạn bằng nhau (qua hai tam giác cân); đường trung bình; tỉ số Thales bằng nhau; điểm trùng.","mau":"#37474F","rar":2,"doc":false},{"id":"K3","nhom":"K","nhomTen":"ĐỔI KẾT LUẬN","ten":"Vuông góc","khi":"Kết luận “vuông góc”.","ra":"Đổi thành: tổng hai góc nhọn bằng 90°; trực tâm; song song với một đường vuông góc; trung trực.","mau":"#37474F","rar":2,"doc":false},{"id":"K4","nhom":"K","nhomTen":"ĐỔI KẾT LUẬN","ten":"Song song","khi":"Kết luận “song song”.","ra":"Đổi thành: góc so le, đồng vị bằng nhau; cùng vuông góc với một đường; Thales đảo.","mau":"#37474F","rar":2,"doc":false},{"id":"K5","nhom":"K","nhomTen":"ĐỔI KẾT LUẬN","ten":"Đồng quy","khi":"Kết luận “ba đường thẳng cùng đi qua một điểm”.","ra":"Gọi giao điểm của hai đường, chứng minh đường thứ ba đi qua (đổi về thẳng hàng).","mau":"#37474F","rar":2,"doc":false},{"id":"K6","nhom":"K","nhomTen":"ĐỔI KẾT LUẬN","ten":"Hệ thức, tam giác cân","khi":"Kết luận là đẳng thức hoặc “tam giác cân”.","ra":"Đổi về tỉ lệ thức, hệ thức lượng; hai cạnh hoặc hai góc bằng nhau.","mau":"#37474F","rar":2,"doc":false},{"id":"B1","nhom":"B","nhomTen":"BÀI TOÁN PHỤ","ten":"Bổ đề hình thang","khi":"Hình thang có hai cạnh bên (hai đường chéo) cắt nhau; cần thẳng hàng, đồng quy.","ra":"Đường thẳng qua giao điểm hai cạnh bên và giao điểm hai đường chéo đi qua trung điểm hai đáy.","mau":"#134E4A","rar":4},{"id":"B2","nhom":"B","nhomTen":"BÀI TOÁN PHỤ","ten":"Trung tuyến chia đôi đoạn song song","khi":"Một đoạn song song với cạnh BC, và có trung tuyến từ đỉnh đối diện.","ra":"Trung tuyến đi qua trung điểm của đoạn song song đó.","mau":"#134E4A","rar":4},{"id":"B3","nhom":"B","nhomTen":"BÀI TOÁN PHỤ","ten":"Đoạn qua giao điểm hai đường chéo","khi":"Hình thang, đoạn qua giao điểm hai đường chéo song song với hai đáy.","ra":"Giao điểm hai đường chéo là trung điểm của đoạn đó.","mau":"#134E4A","rar":4},{"id":"B4","nhom":"B","nhomTen":"BÀI TOÁN PHỤ","ten":"Ba tiếp tuyến","khi":"Đường kính AB, tiếp tuyến tại A, B, M; MH ⊥ AB.","ra":"C là trung điểm AE; BC, AD đi qua trung điểm của MH.","mau":"#134E4A","rar":4},{"id":"B5","nhom":"B","nhomTen":"BÀI TOÁN PHỤ","ten":"Hai tiếp tuyến và đường kính","khi":"Hai tiếp tuyến AB, AC và đường kính BD.","ra":"DC cắt BA tại P thì A là trung điểm của BP.","mau":"#134E4A","rar":4},{"id":"B6","nhom":"B","nhomTen":"BÀI TOÁN PHỤ","ten":"Hai trung tuyến tương ứng","khi":"Cặp tam giác đồng dạng có trung điểm trên một cạnh.","ra":"Hai trung tuyến tương ứng tạo ra cặp tam giác đồng dạng mới (và chiều đảo; nhân đôi – chia đôi).","mau":"#134E4A","rar":4},{"id":"B7","nhom":"B","nhomTen":"BÀI TOÁN PHỤ","ten":"Hai tam giác đồng dạng chung đỉnh","khi":"Hai tam giác đồng dạng có chung một đỉnh.","ra":"Ghép “theo cột” được cặp tam giác đồng dạng mới.","mau":"#134E4A","rar":4}],"missions":[{"boost":[],"id":"2.4","ch":2,"truong":"Bát Tràng","ky":"giữa HKI","de":["Cho tam giác ABC vuông tại A (AB < AC).","a) Khi AB = 6 cm, ∠ABC = 53°. Giải tam giác vuông ABC (làm tròn kết quả độ dài đến chữ số thập phân thứ hai; số đo góc làm tròn đến độ).","b) Kẻ đường cao AH (H ∈ BC) của tam giác ABC. Chứng minh: BC = AB.cos∠ABC + AC.cos∠ACB.","c) Kẻ phân giác BD của ∠ABC (D ∈ AC). Gọi K là giao điểm của BD và AH. Chứng minh: KH = AK.sin∠ACB.","d) Gọi M là hình chiếu của C trên đường thẳng BD. Qua M kẻ đường thẳng vuông góc với AC, đường thẳng này cắt BC tại I. Chứng minh: I là trung điểm của BC."],"yl":"d","yc":"Gọi M là hình chiếu của C trên đường thẳng BD. Qua M kẻ đường thẳng vuông góc với AC, đường thẳng này cắt BC tại I. Chứng minh: I là trung điểm của BC.","kl":"I là trung điểm BC","hinh":"img/b2.4.png","huong":"IB = IM và IM = IC.","giu":"Ý b, c không cần dùng; giữ lại giả thiết BD là tia phân giác và AB ⊥ AC.","noi":"∆IBM cân tại I (∠IMB = ∠ABM = ∠IBM) và ∆IMC cân tại I (∠IMC = ∠ICM).","nhin":"Nếu BD không phải tia phân giác thì I còn là trung điểm của BC không? Giả thiết đó dùng ở bước nào?","nhinDap":"Không: cần ∠IMB = ∠IBM, có được nhờ BD là tia phân giác (cùng với góc so le trong khi MI // AB).","deep":{"huong":[{"ten":"Hai tam giác cân","kq":"duoc","y":["MI // AB ⇒ ∠IMB = ∠ABM = ∠IBM ⇒ IB = IM.","∆BMC vuông tại M ⇒ ∠IMC = ∠ICM ⇒ IM = IC."]},{"ten":"Điểm trùng","kq":"duoc","y":["Gọi I' là trung điểm BC ⇒ I'M = I'B ⇒ ∠I'MB = ∠I'BM = ∠ABM ⇒ MI' // AB ⇒ MI' ⊥ AC ⇒ I' trùng I."]},{"ten":"Kéo dài CM, đường trung bình","kq":"duoc","y":["Kéo dài CM cắt BA tại P. BM vừa là phân giác vừa là đường cao của ∆BCP ⇒ ∆BCP cân tại B ⇒ M là trung điểm CP.","MI // PB (cùng vuông góc với AC) ⇒ I là trung điểm BC."]}],"binh":["Cả ba hướng đều ngắn. Hướng 3 rèn một phản xạ quan trọng: thấy “phân giác + vuông góc với phân giác” thì kéo dài để có tam giác cân."]},"loai":"train","gt":["∆ABC vuông tại A","BD là tia phân giác của ∠ABC (D ∈ AC)","CM ⊥ BD tại M","MI ⊥ AC (I ∈ BC)"],"inputs":[{"code":"P3","text":"MI ⊥ AC và AB ⊥ AC → MI // AB","keep":1},{"code":"G5","text":"MI // AB → ∠IMB = ∠ABM (so le trong)","keep":1},{"code":"G8","text":"BD là tia phân giác → ∠ABM = ∠MBI","keep":1},{"code":"P5","text":"BD là phân giác, K = BD ∩ AH → KH/KA = BH/BA","keep":0,"why":"Đó là ý c; ý d không có điểm K."},{"code":"G7","text":"∆BMC vuông tại M → ∠IMB + ∠IMC = 90°, ∠IBM + ∠ICM = 90°","keep":1},{"code":"V2","text":"∆BMC vuông, I ∈ BC → nếu I là trung điểm thì IM = IB = IC","keep":0,"why":"Dùng chính điều phải chứng minh."},{"code":"","text":"Ý b: BC = AB.cos∠ABC + AC.cos∠ACB","keep":0,"why":"Không nói gì về điểm I."},{"code":"K2","text":"Kết luận “I là trung điểm BC” → đổi thành IB = IM và IM = IC","keep":1}],"steps":[{"cm":"MI // AB","ld":"MI ⊥ AC, AB ⊥ AC","codes":["P3"]},{"cm":"∠IMB = ∠ABM","ld":"So le trong, MI // AB","codes":["G5"]},{"cm":"∠ABM = ∠IBM","ld":"BD là tia phân giác của ∠ABC","codes":["G8"]},{"cm":"∠IMB = ∠IBM ⇒ ∆IBM cân tại I ⇒ IB = IM","ld":"Từ 2 và 3; tam giác có hai góc bằng nhau","codes":["G6"]},{"cm":"∠IMC = 90° − ∠IMB; ∠ICM = 90° − ∠IBM","ld":"∆BMC vuông tại M (CM ⊥ BD)","codes":["G7"]},{"cm":"∠IMC = ∠ICM ⇒ ∆IMC cân tại I ⇒ IM = IC","ld":"Từ 4 và 5: phụ với hai góc bằng nhau","codes":["G4","G6"]},{"cm":"IB = IC, mà I ∈ BC ⇒ I là trung điểm của BC","ld":"Từ 4 và 6","codes":["K2"]}]},{"boost":["B1"],"id":"4.9","ch":4,"truong":"Xuân Đỉnh","ky":"cuối HKII","de":["Cho đường tròn (O; R) và một điểm A nằm ngoài đường tròn (O; R) và OA > 2R. Từ A vẽ hai tiếp tuyến AB và AC của đường tròn (O; R) với (B, C là tiếp điểm). Gọi H là giao điểm của OA và BC. Tia AO cắt đường tròn (O; R) tại M và N (M nằm giữa A và N).","a) Chứng minh tứ giác ABOC nội tiếp.","b) Chứng minh AO vuông góc với BC và AM.AN = AB².","c) Kẻ đường kính BD. Đường thẳng qua C và vuông góc với BD cắt tia AO tại K. Gọi T là giao điểm của AC và KD. Chứng minh HT song song với BD."],"yl":"c","yc":"Kẻ đường kính BD. Đường thẳng qua C và vuông góc với BD cắt tia AO tại K. Gọi T là giao điểm của AC và KD. Chứng minh HT song song với BD.","kl":"HT // BD","hinh":"img/b4.9.png","huong":"TH đi qua trung điểm P của CD, và HP là đường trung bình của ∆BCD.","giu":"AO ⊥ BC tại trung điểm H của BC.","noi":"ABKC là hình thoi (CK // AB, CK = CA = AB) nên H là trung điểm AK. T là giao điểm hai cạnh bên của hình thang ACDK.","nhin":"Viết lại phát biểu bổ đề hình thang với tên điểm của bài này.","nhinDap":"“Hình thang ACDK (AK // CD) có hai cạnh bên AC, KD cắt nhau tại T thì T, trung điểm H của AK và trung điểm P của CD thẳng hàng.”","deep":{"huong":[{"ten":"Góc so le","kq":"tac","y":["Cần ∠THC = ∠DBC; T chỉ là giao điểm, không có góc nào tại T."]},{"ten":"Hệ quả bổ đề hình thang","kq":"duoc","y":["ABKC là hình thoi ⇒ H là trung điểm AK.","Hình thang ACDK (AK // CD), T = AC ∩ KD ⇒ T, H, P thẳng hàng (P trung điểm CD) ⇒ HT // BD."]}],"binh":["Song song được đổi thành “đường trung bình”, rồi thành “thẳng hàng với trung điểm”, rồi nhận ra hình thang ẩn ACDK. Bổ đề hình thang là công cụ duy nhất nối giao điểm hai cạnh bên với trung điểm hai đáy."]},"loai":"lab","so":1,"gt":["(O; R), A nằm ngoài (O), OA > 2R","AB, AC là tiếp tuyến; H = OA ∩ BC","Tia AO cắt (O) tại M, N","BD là đường kính; CK ⊥ BD, K ∈ tia AO","T = AC ∩ KD"],"dg":"chứng minh đường thẳng HT song song với BD.","inputs":[{"code":"T2","text":"AB, AC là tiếp tuyến → AB = AC; AO là tia phân giác của ∠BAC; AO ⊥ BC tại trung điểm H của BC","keep":1,"why":""},{"code":"T1, P3","text":"AB ⊥ BD (tiếp tuyến), CK ⊥ BD → CK // AB","keep":1,"why":""},{"code":"G5, G6","text":"CK // AB, AO là phân giác → ∠CKA = ∠KAB = ∠KAC ⇒ ∆ACK cân tại C ⇒ CK = CA = AB","keep":1,"why":""},{"code":"P4","text":"CK // AB, CK = AB, AB = AC → ABKC là hình thoi ⇒ H là trung điểm của AK","keep":1,"why":""},{"code":"G2","text":"BD là đường kính → ∠BCD = 90° ⇒ CD ⊥ BC ⇒ CD // AK","keep":1,"why":""},{"code":"P2","text":"H, P là trung điểm của BC, CD → HP // BD","keep":1,"why":""},{"code":"S2","text":"Ý b: AM.AN = AB² → một hệ thức độ dài trên AO","keep":0,"why":"không cho góc hay trung điểm nào trên KD."},{"code":"N3","text":"Ý a: ABOC nội tiếp → các cặp góc nội tiếp đường tròn đường kính AO","keep":0,"why":"đường tròn này không chứa T, D."},{"code":"K4","text":"Kết luận HT // BD → Đổi thành: T, H, P thẳng hàng (vì HP // BD)","keep":1,"why":""}],"hoi":[{"lab":"HƯỚNG TỚI","q":"Có sẵn đường nào qua H song song với BD không?","a":"H là trung điểm BC; lấy P là trung điểm CD thì HP // BD (đường trung bình). Chỉ cần T, H, P thẳng hàng."},{"lab":"GIỮ LẠI","q":"T là giao điểm của AC và KD. Hai đường này là gì của một hình quen?","a":"CD // AK (cùng vuông góc với BC): ACDK là hình thang, AC và KD là hai cạnh bên. Ý a, b không cần: bỏ."},{"lab":"CẦU NỐI","q":"Đường thẳng qua giao điểm hai cạnh bên của hình thang có tính chất gì?","a":"Nó đi qua trung điểm của hai đáy. P là trung điểm CD; còn cần H là trung điểm AK: chứng minh ABKC là hình thoi."}],"steps":[{"cm":"CK // AB","ld":"AB ⊥ BD (tiếp tuyến), CK ⊥ BD","codes":["T1","P3"]},{"cm":"∠CKA = ∠KAB = ∠KAC","ld":"So le trong (CK // AB); AO là tia phân giác của ∠BAC","codes":["G5","T2"]},{"cm":"∆ACK cân tại C ⇒ CK = CA = AB","ld":"Từ 2; AB = AC","codes":["G6","T2"]},{"cm":"ABKC là hình thoi ⇒ H là trung điểm của AK","ld":"CK // AB, CK = AB, AB = AC; hai đường chéo cắt nhau tại trung điểm mỗi đường","codes":["P4"]},{"cm":"CD ⊥ BC ⇒ CD // AK","ld":"∠BCD = 90° (chắn nửa đường tròn); AK ⊥ BC","codes":["G2","P3"]},{"cm":"Gọi P là trung điểm CD. Ba điểm T, H, P thẳng hàng","ld":"Hình thang ACDK có hai cạnh bên cắt nhau tại T; H, P là trung điểm hai đáy (chứng minh ở mục Rút ra)","codes":[]},{"cm":"HP // BD","ld":"H, P là trung điểm của BC, CD","codes":["P2"]},{"cm":"HT // BD","ld":"Từ 6 và 7","codes":["K4"]}],"btp":[1],"layer":{"fig":"img/L49.png","cap":"Che đường tròn và các tiếp tuyến, chỉ giữ hình thang ACDK và giao điểm T của hai cạnh bên.","rut":"Lớp tách ra là một hình thang có hai cạnh bên cắt nhau. Đường thẳng nối giao điểm đó với trung điểm một đáy đi qua trung điểm đáy kia. Ghi thành bài toán phụ 1."}},{"boost":["B6","B1","B2"],"id":"1.2","ch":1,"truong":"Văn Yên","ky":"giữa HKI","de":["Cho tam giác ABC vuông tại A, đường cao AH (H thuộc BC).","a) Giả sử AB = 9 cm, tan C = 3/4. Giải tam giác ABC (số đo góc làm tròn đến độ).","b) Gọi M và N lần lượt là chân các đường vuông góc kẻ từ điểm H đến các đường thẳng AB và AC. Chứng minh rằng HN.AC = HA.HC và HN = AB.sin²B.","c) Đường thẳng đi qua điểm A và song song với đường thẳng MN cắt đường thẳng đi qua điểm C và song song với đường thẳng AH tại điểm K. Gọi I là giao điểm của AH và BK. Chứng minh ba điểm M, I, N thẳng hàng."],"yl":"c","yc":"Đường thẳng đi qua điểm A và song song với đường thẳng MN cắt đường thẳng đi qua điểm C và song song với đường thẳng AH tại điểm K. Gọi I là giao điểm của AH và BK. Chứng minh ba điểm M, I, N thẳng hàng.","kl":"M, I, N thẳng hàng","hinh":"img/b1.2.png","huong":"I là trung điểm của AH.","giu":"Từ các hệ thức ở ý b: AM.AB = AN.AC = AH², nên ∆ANM ∽ ∆ABC và ∠ANM = ∠ABC.","noi":"MN đi qua trung điểm của AH (hai đường chéo của hình chữ nhật AMHN). Đổi kết luận thành: I là trung điểm của AH.","nhin":"So sánh với Bài 1: điểm I ở đây và điểm O ở Bài 1 có gì giống nhau?","nhinDap":"Ở cả hai bài, điểm cần tìm là giao điểm của AH với BK và chính là trung điểm của AH, nằm trên MN – cùng một ý “điểm trùng”.","deep":{"huong":[{"ten":"Góc bẹt tại I","kq":"tac","y":["Thử chứng minh ∠MIA + ∠AIN = 180°. Góc tại I phụ thuộc đường BK, mà về BK ta chưa biết góc nào."]},{"ten":"Đổi sang trung điểm, dùng bài toán phụ 2","kq":"duoc","y":["MN đi qua trung điểm AH ⇒ chỉ cần I là trung điểm AH.","∠KAC = ∠ANM = ∠ABC = ∠KCA ⇒ KA = KC; ∆APC vuông tại A ⇒ KA = KP ⇒ K là trung điểm PC.","Trong ∆BPC, BK là trung tuyến, AH // PC ⇒ I là trung điểm AH (bài toán phụ 2)."]}],"binh":["“MN đi qua trung điểm của AH” là bước đổi kết luận từ thẳng hàng sang trung điểm (Chương 0, §6). Sau bước đổi đó, bài toán phụ 2 chỉ đường cho bước tiếp theo: phải dựng P để có tam giác BPC nhận BK làm trung tuyến.","Nếu không biết bài toán phụ 2, học sinh vẫn có thể dùng hai lần hệ quả Thales, nhưng sẽ khó nghĩ ra việc dựng P."]},"loai":"lab","so":2,"gt":["∆ABC vuông tại A, đường cao AH","HM ⊥ AB, HN ⊥ AC","AK // MN, CK // AH","I = AH ∩ BK"],"dg":"chứng minh BK đi qua trung điểm của AH.","inputs":[{"code":"V5","text":"HM ⊥ AB, HN ⊥ AC, ∠BAC = 90° → AMHN là hình chữ nhật ⇒ MN đi qua trung điểm của AH","keep":1,"why":""},{"code":"V1","text":"∆AHB, ∆AHC vuông có đường cao HM, HN → AM.AB = AH² = AN.AC","keep":1,"why":""},{"code":"S2, S1","text":"AM.AB = AN.AC → ∆ANM ∽ ∆ABC ⇒ ∠ANM = ∠ABC","keep":1,"why":""},{"code":"G5","text":"AK // MN → ∠KAC = ∠ANM (so le trong)","keep":1,"why":""},{"code":"P3, G7","text":"CK // AH, AH ⊥ BC → CK ⊥ BC ⇒ ∠KCA = 90° − ∠ACB = ∠ABC","keep":1,"why":""},{"code":"G6","text":"∠KAC = ∠KCA → ∆KAC cân tại K ⇒ KA = KC","keep":1,"why":""},{"code":"G7, G6","text":"P = BA ∩ CK; ∆APC vuông tại A → ∠KAP = ∠KPA ⇒ KA = KP ⇒ K là trung điểm PC","keep":1,"why":""},{"code":"P1","text":"AH // PC → AI/PK = BI/BK = IH/KC","keep":1,"why":""},{"code":"V3","text":"Ý b: HN = AB.sin²B → một độ dài","keep":0,"why":"cần góc, không cần độ dài."},{"code":"K1","text":"Kết luận M, I, N thẳng hàng → Điểm trùng: chứng minh I là trung điểm của AH","keep":1,"why":""}],"hoi":[{"lab":"HƯỚNG TỚI","q":"MN đã đi qua điểm đặc biệt nào?","a":"Trung điểm của AH (tâm hình chữ nhật AMHN). Đổi kết luận thành: I là trung điểm của AH."},{"lab":"GIỮ LẠI","q":"Cần loại thông tin gì? Ý b cho hệ thức nào có ích?","a":"Cần một góc để dùng AK // MN. Giữ AM.AB = AN.AC ⇒ ∠ANM = ∠ABC; bỏ HN = AB.sin²B."},{"lab":"CẦU NỐI","q":"I nằm trên BK, còn AH // CK. Tam giác nào nhận BK làm trung tuyến?","a":"Kéo dài BA cắt CK tại P. Nếu K là trung điểm PC thì trung tuyến BK chia đôi đoạn AH song song với PC."}],"steps":[{"cm":"AMHN là hình chữ nhật ⇒ AH, MN cắt nhau tại trung điểm mỗi đường","ld":"Tứ giác có ba góc vuông","codes":["V5"]},{"cm":"AM.AB = AH² = AN.AC ⇒ AN/AB = AM/AC","ld":"Hệ thức lượng trong ∆AHB, ∆AHC vuông tại H","codes":["V1"]},{"cm":"∆ANM ∽ ∆ABC ⇒ ∠ANM = ∠ABC","ld":"∠BAC chung; từ 2 (c.g.c)","codes":["S1"]},{"cm":"∠KAC = ∠ANM = ∠ABC","ld":"So le trong, AK // MN; từ 3","codes":["G5"]},{"cm":"∠KCA = 90° − ∠ACB = ∠ABC","ld":"CK // AH, AH ⊥ BC ⇒ CK ⊥ BC","codes":["P3","G7"]},{"cm":"KA = KC","ld":"Từ 4 và 5: ∆KAC cân tại K","codes":["G6"]},{"cm":"Gọi P = BA ∩ CK: ∠KAP = 90° − ∠KAC = 90° − ∠KCA = ∠KPA ⇒ KA = KP","ld":"∆APC vuông tại A","codes":["G7","G6"]},{"cm":"KP = KC: K là trung điểm của PC","ld":"Từ 6 và 7","codes":[]},{"cm":"AI/PK = BI/BK = IH/KC ⇒ AI = IH","ld":"AH // PC, hệ quả định lí Thales; từ 8","codes":["P1"]},{"cm":"I là trung điểm AH nên I ∈ MN: M, I, N thẳng hàng","ld":"Từ 1 và 9","codes":["K1"]}],"btp":[2,3],"layer":{"fig":"img/L12.png","cap":"Che hình chữ nhật AMHN, chỉ giữ ∆BPC, đoạn AH song song với PC và đường BK.","rut":"Lớp tách ra: một tam giác, một đoạn song song với cạnh đáy và trung tuyến ứng với cạnh đáy. Trung tuyến chia đôi đoạn song song. Ghi thành bài toán phụ 2; hệ quả là bài toán phụ 3."}},{"boost":["B5","B2"],"id":"4.5","ch":4,"truong":"Ngọc Thụy","ky":"cuối HKI","de":["Cho đường tròn (O; R) và một điểm A nằm ngoài đường tròn (O; R). Từ A vẽ tiếp tuyến AB, tiếp tuyến AC của đường tròn (O; R) (B, C là tiếp điểm). Gọi H là giao điểm của OA và BC. Tia AO cắt đường tròn (O; R) tại M và N (M nằm giữa A và N).","a) Chứng minh rằng bốn điểm A, B, O, C cùng nằm trên một đường tròn.","b) Chứng minh: AO vuông góc với BC và AM.AN = AH.AO.","c) Kẻ đường kính BD, gọi E là chân đường vuông góc kẻ từ C đến BD, K là giao điểm của AD và CE. Chứng minh rằng: K là trung điểm của CE."],"yl":"c","yc":"Kẻ đường kính BD, gọi E là chân đường vuông góc kẻ từ C đến BD, K là giao điểm của AD và CE. Chứng minh rằng: K là trung điểm của CE.","kl":"K là trung điểm CE","hinh":"img/b4.5.png","huong":"Trung tuyến DA của ∆DBP chia đôi CE (bài toán phụ 2).","giu":"AO ⊥ BC; AB = AC.","noi":"CE // BA (cùng vuông góc với BD). Kéo dài DC cắt BA tại P thì A là trung điểm BP (bài toán phụ 5).","nhin":"Hai bài toán phụ nối tiếp nhau thế nào? Bài toán phụ nào cho kết quả để bài kia dùng?","nhinDap":"Bài toán phụ 5 cho A là trung điểm BP; bài toán phụ 2 dùng trung điểm đó để chia đôi CE.","deep":{"huong":[{"ten":"Hai tam giác bằng nhau chứa KE, KC","kq":"tac","y":["∆KED và ∆KC? – không có cặp nào có yếu tố bằng nhau."]},{"ten":"Bài toán phụ 5 rồi bài toán phụ 2","kq":"duoc","y":["P = DC ∩ BA ⇒ A là trung điểm BP (∆BCP vuông tại C, AB = AC).","CE // BP ⇒ EK/BA = DK/DA = KC/AP ⇒ EK = KC."]}],"binh":["Đây là bài có “hai bài toán phụ nối tiếp”. Không biết bài toán phụ 5, học sinh khó nghĩ ra việc kéo dài DC; không biết bài toán phụ 2, khó thấy cần một trung điểm trên BA."]},"loai":"lab","so":3,"gt":["(O; R), A nằm ngoài (O)","AB, AC là tiếp tuyến; H = OA ∩ BC","Tia AO cắt (O) tại M, N","BD là đường kính; CE ⊥ BD tại E","K = AD ∩ CE"],"dg":"chứng minh AD chia đôi đoạn CE.","inputs":[{"code":"T2","text":"AB, AC là tiếp tuyến → AB = AC ⇒ ∠ABC = ∠ACB","keep":1,"why":""},{"code":"G2","text":"BD là đường kính, C ∈ (O) → ∠BCD = 90°","keep":1,"why":""},{"code":"G7, G6","text":"P = DC ∩ BA; ∆BCP vuông tại C → ∠APC = 90° − ∠ABC = 90° − ∠ACB = ∠ACP ⇒ AP = AC = AB","keep":1,"why":""},{"code":"T1, P3","text":"CE ⊥ BD, AB ⊥ BD → CE // BP","keep":1,"why":""},{"code":"P1","text":"CE // BP → EK/BA = DK/DA = KC/AP","keep":1,"why":""},{"code":"V1","text":"Ý b: AM.AN = AH.AO → hệ thức độ dài trên AO","keep":0,"why":"K, E không nằm trên AO."},{"code":"T2","text":"Ý b: AO ⊥ BC → AO ⊥ BC tại H","keep":0,"why":"ý c không cần tới H."},{"code":"K2","text":"Kết luận K là trung điểm CE → Hai tỉ số Thales bằng nhau: EK/BA = KC/AP với BA = AP","keep":1,"why":""}],"hoi":[{"lab":"HƯỚNG TỚI","q":"CE song song với đường nào để dùng Thales?","a":"CE // AB (cùng vuông góc với BD). Thales cho EK/BA = DK/DA. Cần thêm một đoạn trên đường thẳng AB để so với KC."},{"lab":"GIỮ LẠI","q":"KC song song với AB. Đường thẳng DC cắt AB ở đâu?","a":"Gọi P = DC ∩ BA thì KC/AP = DK/DA. Chỉ cần A là trung điểm BP. Ý b không giúp: bỏ."},{"lab":"CẦU NỐI","q":"Vì sao A là trung điểm BP?","a":"∠BCP = 90° và AB = AC ⇒ ∆ACP cân tại A ⇒ AP = AC = AB."}],"steps":[{"cm":"AB = AC ⇒ ∠ABC = ∠ACB","ld":"Hai tiếp tuyến cắt nhau","codes":["T2","G6"]},{"cm":"∠BCD = 90°. Gọi P = DC ∩ BA thì ∆BCP vuông tại C","ld":"Góc nội tiếp chắn nửa đường tròn","codes":["G2"]},{"cm":"∠APC = 90° − ∠ABC = 90° − ∠ACB = ∠ACP ⇒ AP = AC","ld":"Từ 1 và 2","codes":["G7","G6"]},{"cm":"AB = AP: A là trung điểm của BP","ld":"Từ 1 và 3","codes":[]},{"cm":"CE // BP","ld":"CE ⊥ BD, AB ⊥ BD","codes":["T1","P3"]},{"cm":"EK/BA = DK/DA; KC/AP = DK/DA","ld":"Hệ quả định lí Thales trong ∆DBA, ∆DAP","codes":["P1"]},{"cm":"EK = KC: K là trung điểm của CE","ld":"Từ 4 và 6","codes":["K2"]}],"btp":[5],"layer":{"fig":"img/L45.png","cap":"Lớp 1: hai tiếp tuyến AB, AC và đường kính BD. Lớp 2: ∆DBP với đoạn CE song song với BP và trung tuyến DA.","rut":"Lớp 1 lặp lại ở rất nhiều bài: hai tiếp tuyến AB, AC và đường kính BD thì DC cắt BA tại P với A là trung điểm BP. Ghi thành bài toán phụ 5. Lớp 2 chính là bài toán phụ 2 đã có."}},{"boost":["B4","B2","B6"],"id":"5.5","ch":5,"truong":"Dịch Vọng","ky":"cuối HKI","de":["Cho nửa đường tròn (O; R), đường kính AB. Lấy điểm M bất kì thuộc nửa (O; R), tiếp tuyến tại A và M của nửa đường tròn (O; R) cắt nhau tại C (M, A là 2 tiếp điểm). Đoạn thẳng CB cắt nửa đường tròn tại K (K ≠ B).","a) Chứng minh: 4 điểm A, C, O, M cùng thuộc một đường tròn.","b) Chứng minh: ∆AKB vuông và BK.BC = 4R².","c) Gọi H là chân đường vuông góc hạ từ M xuống AB, I là trung điểm của MH. Chứng minh: ba điểm K, C, I thẳng hàng."],"yl":"c","yc":"Gọi H là chân đường vuông góc hạ từ M xuống AB, I là trung điểm của MH. Chứng minh: ba điểm K, C, I thẳng hàng.","kl":"K, C, I thẳng hàng","hinh":"img/b5.5.png","huong":"BC đi qua trung điểm I của MH.","giu":"∆AKB vuông tại K; BK.BC = 4R²; K nằm trên BC.","noi":"Kéo dài BM cắt AC tại E thì C là trung điểm của AE (bài toán phụ 4).","nhin":"So sánh với Nguyễn Bỉnh Khiêm (Bài 5.6): đâu là “tam giác có trung tuyến” trong mỗi bài?","nhinDap":"Dịch Vọng: ∆BAE với trung tuyến BC. Nguyễn Bỉnh Khiêm: ∆CBE với trung tuyến CD.","deep":{"huong":[{"ten":"Góc bẹt tại C","kq":"tac","y":["Cần ∠KCM + ∠MCI = 180°; I là trung điểm MH, không có góc nào tại C liên hệ với I."]},{"ten":"Bài toán phụ 4","kq":"duoc","y":["E = BM ∩ AC ⇒ CA = CE; MH // AE ⇒ BC đi qua trung điểm của MH ⇒ I nằm trên BC."]}],"binh":["Câu “K nằm trên BC” khiến kết luận trông như về K, nhưng thực chất là về đường BC. Đổi kết luận đúng chỗ là thấy ngay bài toán phụ."]},"loai":"lab","so":4,"gt":["Nửa (O; R), đường kính AB; M thuộc nửa đường tròn","Tiếp tuyến tại A và M cắt nhau tại C","CB cắt nửa đường tròn tại K","MH ⊥ AB; I là trung điểm MH"],"dg":"chứng minh BC đi qua trung điểm I của MH.","inputs":[{"code":"T2","text":"CA, CM là tiếp tuyến → CA = CM ⇒ ∠CAM = ∠CMA","keep":1,"why":""},{"code":"G2","text":"AB là đường kính, M ∈ (O) → ∠AMB = 90° ⇒ ∠AME = 90° (E = BM ∩ AC)","keep":1,"why":""},{"code":"G7, G6","text":"∆AME vuông tại M → ∠CEM = 90° − ∠CAM = 90° − ∠CMA = ∠CME ⇒ CE = CM","keep":1,"why":""},{"code":"T1, P3","text":"MH ⊥ AB, AE ⊥ AB → MH // AE","keep":1,"why":""},{"code":"P1","text":"MH // AE → HI'/AC = BI'/BC = I'M/CE (I' = BC ∩ MH)","keep":1,"why":""},{"code":"","text":"K ∈ CB → K, C, B thẳng hàng","keep":1,"why":""},{"code":"V1","text":"Ý b: BK.BC = 4R²; ∆AKB vuông → hệ thức độ dài","keep":0,"why":"chỉ cần biết K nằm trên BC."},{"code":"K1","text":"Kết luận K, C, I thẳng hàng → Đổi thành: I nằm trên BC (điểm trùng)","keep":1,"why":""}],"hoi":[{"lab":"HƯỚNG TỚI","q":"K, C đều nằm trên BC. Vậy kết luận nói gì về I?","a":"I nằm trên BC: BC đi qua trung điểm của MH."},{"lab":"GIỮ LẠI","q":"MH song song với đường nào đi qua C?","a":"MH // AC (cùng vuông góc với AB). Muốn đường từ B qua C chia đôi MH, cần C là trung điểm một đoạn trên AC: kéo dài BM cắt AC tại E. Ý b bỏ."},{"lab":"CẦU NỐI","q":"Vì sao C là trung điểm AE?","a":"CA = CM (tiếp tuyến) và ∆AME vuông tại M ⇒ CM = CE."}],"steps":[{"cm":"Gọi E = BM ∩ AC: ∠AME = 90°","ld":"∠AMB = 90° (góc nội tiếp chắn nửa đường tròn)","codes":["G2"]},{"cm":"CA = CM ⇒ ∠CAM = ∠CMA","ld":"Hai tiếp tuyến cắt nhau","codes":["T2","G6"]},{"cm":"∠CEM = 90° − ∠CAM = 90° − ∠CMA = ∠CME ⇒ CE = CM","ld":"∆AME vuông tại M; từ 2","codes":["G7","G6"]},{"cm":"CA = CE: C là trung điểm của AE","ld":"Từ 2 và 3","codes":[]},{"cm":"MH // AE","ld":"MH ⊥ AB, AE ⊥ AB","codes":["T1","P3"]},{"cm":"Gọi I' = BC ∩ MH: HI'/AC = BI'/BC = I'M/CE","ld":"Hệ quả định lí Thales trong ∆BAC, ∆BCE","codes":["P1"]},{"cm":"HI' = I'M ⇒ I' trùng I","ld":"Từ 4 và 6: I' là trung điểm của MH","codes":[]},{"cm":"I ∈ BC, K ∈ BC ⇒ K, C, I thẳng hàng","ld":"Từ 7","codes":["K1"]}],"btp":[4],"layer":{"fig":"img/L55.png","cap":"Lớp 1: tiếp tuyến tại A và M; BM cắt tiếp tuyến tại A ở E. Lớp 2: ∆BAE với MH song song với AE và đường BC.","rut":"Lớp 1: đường kính AB, tiếp tuyến tại A, tại M (và tại B) – gọi là “ba tiếp tuyến” – cho C là trung điểm AE; kết hợp lớp 2 (bài toán phụ 2) được BC, AD đi qua trung điểm MH. Ghi thành bài toán phụ 4."}},{"boost":["B6"],"id":"4.4","ch":4,"truong":"Ngọc Lâm","ky":"cuối HKI","de":["Cho đường tròn tâm O và điểm A nằm ngoài đường tròn, vẽ hai tiếp tuyến AB, AC (B, C là hai tiếp điểm). AO cắt BC tại H, vẽ đường kính BD.","a) Chứng minh bốn điểm A, B, O, C cùng thuộc một đường tròn.","b) Chứng minh AO vuông góc với BC tại H và CD // AO.","c) Gọi M là trung điểm của AH, BM cắt (O) tại N. Chứng minh D, H, N thẳng hàng."],"yl":"c","yc":"Gọi M là trung điểm của AH, BM cắt (O) tại N. Chứng minh D, H, N thẳng hàng.","kl":"D, H, N thẳng hàng","hinh":"img/b4.4.png","huong":"BM ⊥ DH (∠BN'D = 90° với N' = BM ∩ DH).","giu":"AO ⊥ BC tại H; CD // AO.","noi":"N là chân đường vuông góc hạ từ B xuống DH (∠BND = 90°). M, H là trung điểm của HA, CB – hai cạnh tương ứng của ∆BHA ∽ ∆DCB.","nhin":"Trong bài, điểm H có những vai nào? Kể đủ.","nhinDap":"H là giao điểm của OA và BC, trung điểm BC, chân đường cao của ∆ABO, và là đỉnh của cặp góc đối đỉnh trong lời giải.","deep":{"huong":[{"ten":"Góc bẹt tại H","kq":"tac","y":["Cần ∠DHC + ∠CHN = 180°; N là giao điểm với đường tròn, chưa có góc nào tại H liên hệ với N."]},{"ten":"Điểm trùng + bài toán phụ 6","kq":"duoc","y":["MH/HC = HB/CD (từ HB² = AH.OH) ⇒ ∆MHB ∽ ∆HCD ⇒ ∠HBM = ∠CDH ⇒ ∠BN'D = 90° ⇒ N' thuộc (O) ⇒ N' trùng N."]}],"binh":["Hai kỹ thuật kết hợp: “điểm trùng” để đổi kết luận, và bài toán phụ 6 để tìm cặp tam giác. Dấu hiệu bài toán phụ 6: M và H là trung điểm của hai cạnh HA, CB của cặp ∆BHA ∽ ∆DCB."]},"loai":"lab","so":5,"gt":["(O), A nằm ngoài (O)","AB, AC là tiếp tuyến; H = AO ∩ BC","BD là đường kính","M là trung điểm AH; BM cắt (O) tại N"],"dg":"chứng minh BM vuông góc với DH.","inputs":[{"code":"T2","text":"AB, AC là tiếp tuyến → AO ⊥ BC tại trung điểm H của BC","keep":1,"why":""},{"code":"V1","text":"∆ABO vuông tại B, đường cao BH → HB² = AH.OH","keep":1,"why":""},{"code":"G2","text":"BD là đường kính → ∠BCD = 90°; điểm nhìn BD dưới góc vuông thì nằm trên (O)","keep":1,"why":""},{"code":"P2","text":"H, O là trung điểm của BC, BD → CD // OH; CD = 2OH","keep":1,"why":""},{"code":"K6","text":"MH = AH/2, HC = HB, CD = 2OH → MH/HC = AH/(2HB) = HB/(2OH) = HB/CD","keep":1,"why":""},{"code":"S1","text":"∠MHB = ∠HCD = 90° → ∆MHB ∽ ∆HCD (c.g.c) ⇒ ∠HBM = ∠CDH","keep":1,"why":""},{"code":"N1","text":"Ý a: A, B, O, C cùng thuộc một đường tròn → đường tròn đường kính AO","keep":0,"why":"không chứa M, N, D."},{"code":"K1","text":"Kết luận D, H, N thẳng hàng → Điểm trùng: gọi N' = BM ∩ DH, chứng minh ∠BN'D = 90°","keep":1,"why":""}],"hoi":[{"lab":"HƯỚNG TỚI","q":"N nằm trên (O), BD là đường kính. Đổi “D, H, N thẳng hàng” thành gì?","a":"Gọi N' = BM ∩ DH. Nếu ∠BN'D = 90° thì N' nằm trên (O), nên N' trùng N. Cần: BM ⊥ DH."},{"lab":"GIỮ LẠI","q":"Muốn BM ⊥ DH cần góc nào? Ý b cho gì?","a":"Cần ∠HBM = ∠CDH (∠BHN' = ∠CHD đối đỉnh). Ý b cho CD // AO ⇒ CD = 2OH: giữ."},{"lab":"CẦU NỐI","q":"Hai góc ∠HBM, ∠CDH nằm trong hai tam giác nào?","a":"∆MHB và ∆HCD: vuông tại H và C; cần MH/HC = HB/CD, có từ HB² = AH.OH."}],"steps":[{"cm":"AO ⊥ BC tại H, H là trung điểm của BC","ld":"AB = AC, OB = OC: AO là trung trực của BC","codes":["T2"]},{"cm":"HB² = AH.OH","ld":"Hệ thức lượng trong ∆ABO vuông tại B, đường cao BH","codes":["V1"]},{"cm":"CD = 2OH","ld":"OH là đường trung bình của ∆BCD","codes":["P2"]},{"cm":"MH/HC = AH/(2HB) = HB/(2OH) = HB/CD","ld":"MH = AH/2, HC = HB; từ 2 và 3","codes":[]},{"cm":"∆MHB ∽ ∆HCD ⇒ ∠HBM = ∠CDH","ld":"∠MHB = ∠HCD = 90°; từ 4 (c.g.c)","codes":["G2","S1"]},{"cm":"Gọi N' = BM ∩ DH: ∠HBN' + ∠BHN' = ∠CDH + ∠CHD = 90° ⇒ ∠BN'D = 90°","ld":"∠BHN' = ∠CHD (đối đỉnh); ∆HCD vuông tại C","codes":["G7"]},{"cm":"N' thuộc (O) và N' ∈ BM nên N' trùng N. Vậy D, H, N thẳng hàng","ld":"N' nhìn đường kính BD dưới góc vuông","codes":["N1","K1"]}],"btp":[6],"layer":{"fig":"img/L44.png","cap":"Che các tiếp tuyến và đường tròn, chỉ giữ ∆BHA và ∆DCB cùng hai đường BM, DH.","rut":"Hai tam giác vuông ∆BHA ∽ ∆DCB. M, H là trung điểm của hai cạnh tương ứng HA, CB. Hai trung tuyến tương ứng BM, DH tạo ra cặp đồng dạng mới ∆BHM ∽ ∆DCH – đúng điều dòng 5 đã chứng minh bằng tỉ số. Ghi thành bài toán phụ 6."}},{"boost":["B6"],"id":"3.10","ch":3,"truong":"Vào 10 Hà Nội 2025","ky":"vào 10","de":["Cho tam giác ABC có ba góc nhọn (AB < AC), nội tiếp đường tròn (O). Đường cao AD của tam giác ABC cắt đường tròn (O) tại điểm E (E khác A). Gọi K là chân đường vuông góc kẻ từ điểm E đến đường thẳng AB.","a) Chứng minh bốn điểm E, D, B, K cùng thuộc một đường tròn.","b) Đường thẳng AO cắt đường thẳng BC tại điểm S. Chứng minh EA là tia phân giác của góc CEK và AB.AC = AE.AS.","c) Gọi H là trực tâm của tam giác ABC và I là trung điểm của đoạn thẳng AB. Chứng minh đường thẳng SI vuông góc với đường thẳng HK."],"yl":"c","yc":"Gọi H là trực tâm của tam giác ABC và I là trung điểm của đoạn thẳng AB. Chứng minh đường thẳng SI vuông góc với đường thẳng HK.","kl":"SI ⊥ HK","hinh":"img/b3.10.png","huong":"∠HKE = ∠SIB, rồi tính góc tại giao điểm của HK và SI.","giu":"EA là tia phân giác của ∠CEK; ∠EAB = ∠CAS; ∠AEK = ∠ABC.","noi":"D là trung điểm của HE. Từ ∆DKE ∽ ∆SAB, nhân đôi DE thành HE và chia đôi AB thành BI được ∆HEK ∽ ∆SBI.","nhin":"So sánh với Trưng Vương (Bài 3.9): hai bài có chung ý tưởng nào?","nhinDap":"Cùng ý “nhân đôi – chia đôi” (bài toán phụ 6) để được cặp tam giác có hai cạnh tương ứng vuông góc.","deep":{"huong":[{"ten":"Tính trực tiếp góc tại giao điểm","kq":"tac","y":["S và I nằm xa H, K; không có tứ giác nội tiếp nào chứa cả bốn điểm."]},{"ten":"Nhân đôi DE thành HE, chia đôi AB thành BI","kq":"duoc","y":["D là trung điểm HE; ∆DKE ∽ ∆SAB ⇒ HE/SB = KE/BI ⇒ ∆HEK ∽ ∆SBI ⇒ ∠HKE = ∠SIB ⇒ SI ⊥ HK."]}],"binh":["Bài vào 10 năm 2025 và Bài 3.9 (Trưng Vương) có chung ý tưởng. Việc phát hiện D là trung điểm HE (điểm nhiều vai) là chìa khóa để thấy cặp “nhân đôi – chia đôi”."]},"loai":"lab","so":6,"gt":["∆ABC nhọn (AB < AC) nội tiếp (O)","Đường cao AD cắt (O) tại E","EK ⊥ AB; S = AO ∩ BC","H là trực tâm; I là trung điểm AB"],"dg":"chứng minh góc giữa SI và HK bằng 90°.","inputs":[{"code":"Q1, G1","text":"H trực tâm; ∠BAE = ∠BCE (cùng chắn cung BE) → ∠HCD = ∠ECD ⇒ ∆CHE cân tại C ⇒ D là trung điểm HE","keep":1,"why":""},{"code":"N3","text":"Ý a: BDEK nội tiếp → ∠DKE = ∠DBE","keep":1,"why":""},{"code":"G1","text":"∠DBE = ∠CBE = ∠CAE → ∠DKE = ∠CAD = ∠SAB (vì ∠EAB = ∠CAS, ý b)","keep":1,"why":""},{"code":"","text":"Ý b: ∠AEK = ∠ABC → ∠DEK = ∠SBA","keep":1,"why":""},{"code":"S1","text":"Hai góc bằng nhau → ∆DKE ∽ ∆SAB ⇒ DE/SB = KE/AB","keep":1,"why":""},{"code":"K6","text":"HE = 2DE, AB = 2BI → HE/SB = KE/BI","keep":1,"why":""},{"code":"S2","text":"Ý b: AB.AC = AE.AS → hệ thức tích","keep":0,"why":"chỉ cần dạng góc ∠EAB = ∠CAS."},{"code":"K3","text":"Kết luận SI ⊥ HK → Đổi thành: ∠XKI + ∠XIK = 90° (X = HK ∩ SI)","keep":1,"why":""}],"hoi":[{"lab":"HƯỚNG TỚI","q":"SI và HK tạo góc với đường nào đã biết vuông góc?","a":"EK ⊥ AB. Nếu ∠HKE = ∠SIB thì tại X = HK ∩ SI có ∠XKI + ∠XIK = 90°. Cần: ∆HEK ∽ ∆SBI."},{"lab":"GIỮ LẠI","q":"Ý b cho góc nào để ghép các cạnh EK, ED với AB, SB?","a":"∠AEK = ∠ABC và ∠EAB = ∠CAS: đủ để có ∆DKE ∽ ∆SAB. Bỏ hệ thức tích."},{"lab":"CẦU NỐI","q":"Từ ∆DKE ∽ ∆SAB đến ∆HEK ∽ ∆SBI, cạnh nào thay đổi?","a":"D là trung điểm HE (nhân đôi DE); I là trung điểm AB (chia đôi AB). Đó là dạng nhân đôi – chia đôi."}],"steps":[{"cm":"∠HCD = ∠HAB = ∠BCE ⇒ ∆CHE cân tại C ⇒ D là trung điểm của HE","ld":"H là trực tâm (cùng phụ ∠ABC); cùng chắn cung BE; CD vừa là đường cao vừa là phân giác","codes":["Q1","G4","G1","G6"]},{"cm":"∠DKE = ∠DBE = ∠CAE = ∠CAD","ld":"BDEK nội tiếp (ý a); cùng chắn cung CE","codes":["N3","G1"]},{"cm":"∠SAB = ∠CAD ⇒ ∠DKE = ∠SAB","ld":"Ý b: ∠EAB = ∠CAS","codes":[]},{"cm":"∠DEK = ∠AEK = ∠ABC = ∠SBA","ld":"D nằm giữa A và E; ý b","codes":[]},{"cm":"∆DKE ∽ ∆SAB ⇒ DE/SB = KE/AB","ld":"Từ 3 và 4 (g.g)","codes":["S1"]},{"cm":"HE/SB = 2DE/SB = KE/(AB/2) = KE/BI","ld":"Từ 1 và 5; I là trung điểm AB","codes":[]},{"cm":"∆HEK ∽ ∆SBI ⇒ ∠HKE = ∠SIB","ld":"∠HEK = ∠SBI (dòng 4); từ 6 (c.g.c)","codes":["S1"]},{"cm":"Gọi X = HK ∩ SI: ∠XKI + ∠XIK = (90° − ∠HKE) + ∠SIB = 90° ⇒ SI ⊥ HK","ld":"EK ⊥ AB; từ 7","codes":["G7","K3"]}],"btp":[],"layer":{"fig":"img/L310.png","cap":"Lớp 1: cặp ∆DKE ∽ ∆SAB lấy từ ý b. Lớp 2: nhân đôi cạnh DE thành HE, chia đôi cạnh AB thành BI.","rut":"Từ một cặp tam giác đồng dạng, nhân đôi một cạnh ở tam giác này và chia đôi cạnh tương ứng kề cùng góc ở tam giác kia, được cặp đồng dạng mới. Đây là dạng “nhân đôi – chia đôi” của bài toán phụ 6."}},{"boost":["B7"],"id":"1.7","ch":1,"truong":"Vào 10 Hà Nội 2026","ky":"vào 10","de":["Cho tam giác ABC vuông tại A (AB < AC) nội tiếp đường tròn tâm O, đường kính BC. Lấy điểm H thuộc đoạn thẳng AB sao cho HB > HA (H khác A). Kẻ đường thẳng qua H vuông góc với đường thẳng BC tại điểm D và cắt đường thẳng AC tại điểm E.","a) Chứng minh bốn điểm A, H, D, C cùng thuộc một đường tròn.","b) Đường thẳng CH cắt đường tròn (O) tại điểm thứ hai F. Đường thẳng qua A vuông góc với đường thẳng ED cắt đường thẳng DF tại điểm M. Chứng minh AE.BC = EH.AB và ∠EMH = 90°.","c) Đường thẳng BM cắt đường tròn (O) tại điểm thứ hai K. Chứng minh tam giác HKM là tam giác cân."],"yl":"c","yc":"Đường thẳng BM cắt đường tròn (O) tại điểm thứ hai K. Chứng minh tam giác HKM là tam giác cân.","kl":"∆HKM cân","hinh":"img/b1.7.png","huong":"HK = HA, tức OH là đường trung trực của AK.","giu":"Ý b: HA = HM; AM ⊥ DE nên AM // BC.","noi":"Ý b cho HM = HA. Hai tam giác cân HAM (đỉnh H) và OAB (đỉnh O) đồng dạng, chung đỉnh A.","nhin":"Viết lại bài toán phụ 7 với tên điểm của bài này: cặp nào ghép “theo hàng”, cặp nào ghép “theo cột”?","nhinDap":"“Theo hàng”: ∆AHM ∽ ∆AOB. “Theo cột”: ∆AHO ∽ ∆AMB.","deep":{"huong":[{"ten":"Tính trực tiếp góc của ∆HKM","kq":"tac","y":["K là giao điểm của BM với (O). ∠HMK = ∠HMB tính được, nhưng ∠HKM phụ thuộc vị trí của H so với đường tròn, không có cung nào chắn."]},{"ten":"Bài toán phụ 7","kq":"duoc","y":["∆AHM ∽ ∆AOB (hai tam giác cân có góc đáy bằng nhau) ⇒ theo bài toán phụ 7: ∆AHO ∽ ∆AMB ⇒ ∠AOH = ∠ABM = ½∠AOK.","OH là phân giác của ∠AOK ⇒ OH là trung trực AK ⇒ HK = HA = HM."]}],"binh":["Đây là bài điển hình cho thấy cái lợi của bài toán phụ: từ một cặp tam giác cân “theo hàng” (A, H, M) – (A, O, B), bài toán phụ 7 cho ngay cặp “theo cột” (A, H, O) – (A, M, B) mà không cần tìm thêm góc nào."]},"loai":"lab","so":7,"gt":["∆ABC vuông tại A nội tiếp (O), đường kính BC","H ∈ AB, HB > HA; HD ⊥ BC, HD cắt AC tại E","CH cắt (O) tại F; AM ⊥ ED, M ∈ DF","BM cắt (O) tại K"],"dg":"chứng minh HK = HM.","inputs":[{"code":"N5","text":"Ý b: HA = HM (DE là trung trực của AM) → ∆HAM cân tại H","keep":1,"why":""},{"code":"Q2","text":"OA = OB (bán kính) → ∆OAB cân tại O","keep":1,"why":""},{"code":"P3, G5","text":"AM ⊥ DE, BC ⊥ DE → AM // BC ⇒ ∠MAB = ∠ABO = ∠OAB","keep":1,"why":""},{"code":"S1","text":"Hai tam giác cân có góc ở đáy bằng nhau → ∆AHM ∽ ∆AOB (chung đỉnh A)","keep":1,"why":""},{"code":"S1","text":"H ∈ AB nên ∠HAO = ∠BAO = ∠MAB → ∆AHO ∽ ∆AMB ⇒ ∠AOH = ∠ABM","keep":1,"why":""},{"code":"G1","text":"∠ABK là góc nội tiếp chắn cung AK → ∠AOH = ½∠AOK: OH là phân giác của ∠AOK","keep":1,"why":""},{"code":"G6","text":"∆OAK cân, OH là phân giác → OH là trung trực của AK ⇒ HK = HA","keep":1,"why":""},{"code":"S2","text":"Ý b: AE.BC = EH.AB → hệ thức độ dài","keep":0,"why":"không có điểm K."},{"code":"N3","text":"Ý a: AHDC nội tiếp → ∠HDA = ∠HCA","keep":0,"why":"đã dùng để có HA = HM ở ý b."},{"code":"K6","text":"Kết luận ∆HKM cân → HK = HM; mà HM = HA nên cần HK = HA","keep":1,"why":""}],"hoi":[{"lab":"HƯỚNG TỚI","q":"∆HKM cân tại đâu? Đổi thành hai đoạn nào bằng nhau?","a":"Ý b cho HM = HA. Cần HK = HA: H nằm trên trung trực của AK, tức OH là phân giác của ∠AOK."},{"lab":"GIỮ LẠI","q":"Ý b cho gì để có góc tại O?","a":"HA = HM: ∆HAM cân tại H. Cùng ∆OAB cân tại O và AM // BC, hai tam giác cân này đồng dạng, chung đỉnh A."},{"lab":"CẦU NỐI","q":"Hai tam giác đồng dạng chung đỉnh A cho thêm cặp nào?","a":"Ghép “theo cột”: ∆AHO ∽ ∆AMB ⇒ ∠AOH = ∠ABM = ∠ABK = ½∠AOK."}],"steps":[{"cm":"AM // BC ⇒ ∠MAB = ∠ABO","ld":"AM ⊥ DE, BC ⊥ DE; so le trong","codes":["P3","G5"]},{"cm":"∠ABO = ∠OAB ⇒ ∠MAB = ∠OAB","ld":"∆OAB cân tại O (OA = OB)","codes":["G6"]},{"cm":"∆AHM ∽ ∆AOB","ld":"∆HAM cân tại H (HA = HM, ý b) và ∆OAB cân tại O có góc ở đáy ∠HAM = ∠OAB (dòng 2)","codes":["S1"]},{"cm":"AH/AO = AM/AB và ∠HAO = ∠MAB","ld":"Từ 3; H ∈ AB nên ∠HAO = ∠BAO = ∠MAB","codes":[]},{"cm":"∆AHO ∽ ∆AMB ⇒ ∠AOH = ∠ABM","ld":"Từ 4 (c.g.c)","codes":["S1"]},{"cm":"∠ABM = ∠ABK = ½∠AOK ⇒ ∠AOH = ½∠AOK","ld":"Góc nội tiếp và góc ở tâm cùng chắn cung AK","codes":["G1"]},{"cm":"OH là trung trực của AK ⇒ HK = HA","ld":"∆OAK cân tại O có OH là phân giác","codes":["G6"]},{"cm":"HK = HM: ∆HKM cân tại H","ld":"HA = HM (ý b)","codes":["K6"]}],"btp":[7],"layer":{"fig":"img/L17.png","cap":"Lớp 1: hai tam giác cân ∆AHM, ∆AOB đồng dạng, chung đỉnh A. Lớp 2: ghép theo cột, được ∆AHO ∽ ∆AMB.","rut":"Hai tam giác đồng dạng có chung một đỉnh: ghép các đỉnh tương ứng “theo cột” luôn được một cặp đồng dạng mới. Ghi thành bài toán phụ 7."}},{"boost":["B7"],"id":"3.2","ch":3,"truong":"Lê Hồng Phong","ky":"giữa HKII","de":["Cho ∆ABC có ba góc nhọn, nội tiếp đường tròn (O), kẻ đường cao BE của ∆ABC. Gọi H và K lần lượt là chân các đường vuông góc kẻ từ E đến AB và BC.","a) Chứng minh tứ giác BHEK là tứ giác nội tiếp.","b) Chứng minh BH.BA = BE² và ∆BAC ∽ ∆BKH.","c) Kẻ đường cao CF của ∆ABC (F ∈ AB) và I là trung điểm của EF. Chứng minh ba điểm H, I, K thẳng hàng."],"yl":"c","yc":"Kẻ đường cao CF của ∆ABC (F ∈ AB) và I là trung điểm của EF. Chứng minh ba điểm H, I, K thẳng hàng.","kl":"H, I, K thẳng hàng","hinh":"img/b3.2.png","huong":"∠EHK = ∠EHI (hai tia HK, HI trùng nhau).","giu":"∆BAC ∽ ∆BKH; tứ giác BHEK nội tiếp.","noi":"Cùng vuông (∠EHF = ∠EKC = 90°) và ∠EFH = ∠ECK = ∠ACB nên đồng dạng; theo bài toán phụ 7 được ∆EHK ∽ ∆EFC.","nhin":"Đặt bài này cạnh Phúc Đồng (Bài 3.5). Hai đề khác nhau đúng một chỗ nào?","nhinDap":"Hình và ý c giống hệt Phúc Đồng (Bài 3.5); chỉ khác ý b: Lê Hồng Phong hỏi BH.BA = BE² và ∆BAC ∽ ∆BKH, Phúc Đồng hỏi BH.BA = BK.BC.","deep":{"huong":[{"ten":"Gọi I' là giao điểm của HK và EF, chứng minh I'E = I'F","kq":"tac","y":["Cần tỉ số trên EF; không có đường song song nào cắt EF."]},{"ten":"Hai tia trùng nhau, dùng ý a","kq":"duoc","y":["∠BHK = ∠BEK = ∠ACB; ∠FHI = ∠HFI = ∠ACB.","F nằm giữa H và B nên ∠BHK = ∠BHI ⇒ tia HK trùng tia HI."]},{"ten":"Bài toán phụ 7","kq":"duoc","y":["∆EHF ∽ ∆EKC (vuông, ∠EFH = ∠ECK) ⇒ theo bài toán phụ 7: ∆EHK ∽ ∆EFC ⇒ ∠EHK = ∠EFC = 90° − ∠ACB = ∠EHI."]}],"binh":["Đi ngược tới “cần một góc bằng ∠ACB” rồi mới rà kết quả. Ở bài này ý a cho góc đó nhanh hơn ý b. Bài học: đừng mặc định phải dùng kết quả cuối cùng của ý trước; hãy chọn kết quả phục vụ đúng cái cần."]},"loai":"lab","so":8,"gt":["∆ABC nhọn nội tiếp (O); BE ⊥ AC","EH ⊥ AB, EK ⊥ BC","CF ⊥ AB; I là trung điểm EF"],"dg":"chứng minh HK đi qua trung điểm của EF.","inputs":[{"code":"N1","text":"BE ⊥ AC, CF ⊥ AB → BCEF nội tiếp đường tròn đường kính BC","keep":1,"why":""},{"code":"N3","text":"BCEF nội tiếp → ∠AFE = ∠ACB ⇒ ∠EFH = ∠ACB","keep":1,"why":""},{"code":"S3","text":"∠EHF = ∠EKC = 90°, ∠EFH = ∠ECK → ∆EHF ∽ ∆EKC ⇒ ∠HEF = ∠KEC","keep":1,"why":""},{"code":"S1","text":"Hai tam giác đồng dạng chung đỉnh E → ∆EHK ∽ ∆EFC ⇒ ∠EHK = ∠EFC = 90° − ∠ACB","keep":1,"why":""},{"code":"V2","text":"∆EHF vuông tại H, I là trung điểm EF → IH = IE ⇒ ∠EHI = ∠HEF = 90° − ∠ACB","keep":1,"why":""},{"code":"N3","text":"Ý a: BHEK nội tiếp → ∠BHK = ∠BEK = ∠ACB","keep":0,"why":"cũng đi được – xem cách ngắn ở Bước 4."},{"code":"V1","text":"Ý b: BH.BA = BE² → hệ thức độ dài","keep":0,"why":"không cho góc tại H."},{"code":"K1","text":"Kết luận H, I, K thẳng hàng → Hai tia trùng nhau: ∠EHK = ∠EHI","keep":1,"why":""}],"hoi":[{"lab":"HƯỚNG TỚI","q":"Tại H có những tia nào? Đổi kết luận thành gì?","a":"Tia HE, HI, HK. Cần ∠EHK = ∠EHI (hai tia HK, HI trùng nhau)."},{"lab":"GIỮ LẠI","q":"∠EHI tính được không? ∠EHK nằm trong tam giác nào?","a":"IH = IE nên ∠EHI = ∠HEF = 90° − ∠ACB. ∠EHK nằm trong ∆EHK: cần một tam giác đồng dạng với nó."},{"lab":"CẦU NỐI","q":"Hai tam giác đồng dạng nào chung đỉnh E, chứa EH và EK?","a":"∆EHF ∽ ∆EKC (cùng vuông, ∠EFH = ∠ECK). Ghép theo cột: ∆EHK ∽ ∆EFC."}],"steps":[{"cm":"BCEF nội tiếp ⇒ ∠AFE = ∠ACB","ld":"∠BEC = ∠BFC = 90°; góc ngoài bằng góc trong ở đỉnh đối","codes":["N1","N3"]},{"cm":"∠EFH = ∠AFE = ∠ACB","ld":"H nằm giữa A và F (AH = AE.cos A < AC.cos A = AF)","codes":[]},{"cm":"∆EHF ∽ ∆EKC ⇒ ∠HEF = ∠KEC; EH/EK = EF/EC","ld":"∠EHF = ∠EKC = 90°; ∠EFH = ∠ECK (g.g)","codes":["S3"]},{"cm":"∠HEK = ∠HEF + ∠FEK = ∠KEC + ∠FEK = ∠FEC","ld":"Từ 3","codes":[]},{"cm":"∆EHK ∽ ∆EFC ⇒ ∠EHK = ∠EFC","ld":"Từ 3 và 4 (c.g.c)","codes":["S1"]},{"cm":"∠EFC = 90° − ∠AFE = 90° − ∠ACB","ld":"CF ⊥ AB; từ 1","codes":[]},{"cm":"IH = IE ⇒ ∠EHI = ∠HEF = 90° − ∠EFH = 90° − ∠ACB","ld":"Trung tuyến ứng với cạnh huyền của ∆EHF","codes":["V2","G6","G7"]},{"cm":"∠EHK = ∠EHI ⇒ tia HK trùng tia HI ⇒ H, I, K thẳng hàng","ld":"Từ 5, 6, 7; K, I cùng phía đối với HE","codes":["K1"]}],"btp":[],"layer":{"fig":"img/L32.png","cap":"Lớp 1: ∆EHF ∽ ∆EKC chung đỉnh E. Lớp 2: ghép theo cột, được ∆EHK ∽ ∆EFC.","rut":"Lại là hai tam giác đồng dạng chung một đỉnh – bài toán phụ 7 xuất hiện lần thứ hai."}},{"boost":[],"id":"1.1","ch":1,"truong":"Trưng Vương","ky":"giữa HKI","de":["Cho tam giác ABC vuông tại A (AB < AC), đường cao AH (H ∈ BC). Gọi M, N lần lượt là chân đường vuông góc hạ từ H xuống hai đường thẳng AB, AC.","1) Chứng minh 4 điểm A, M, H, N cùng thuộc một đường tròn.","2) Chứng minh tam giác AMN đồng dạng với tam giác ACB và HN = AB.sin²B.","3) Hai đường thẳng MN và BC cắt nhau tại I. Trên tia đối của tia NH lấy điểm K sao cho NK = BM. Chứng minh đường thẳng AI vuông góc với đường thẳng CK."],"yl":"3","yc":"Hai đường thẳng MN và BC cắt nhau tại I. Trên tia đối của tia NH lấy điểm K sao cho NK = BM. Chứng minh đường thẳng AI vuông góc với đường thẳng CK.","kl":"AI ⊥ CK","hinh":"img/b1.1.png","huong":"AI ⊥ OE và OE // CK (E là trung điểm BC).","giu":"∆AMN ∽ ∆ACB nên ∠AMN = ∠ACB.","noi":"HK = AB và HK // AB nên ABHK là hình bình hành; BK đi qua trung điểm O của AH, cũng là trung điểm của MN.","nhin":"Trung điểm O của AH đóng mấy vai trong lời giải? Kể ra.","nhinDap":"O là trung điểm của AH, của MN (tâm hình chữ nhật AMHN), của BK (tâm hình bình hành ABHK) và là trực tâm của ∆AIE.","deep":{"huong":[{"ten":"Tính góc trực tiếp","kq":"tac","y":["Thử chứng minh góc giữa AI và CK bằng 90° bằng cách tính các góc tại I và tại C. ∠AIB tính được qua ∠AMN = ∠ACB, nhưng ∠KCB phụ thuộc vị trí của K, mà K chỉ được cho bằng một độ dài."]},{"ten":"Giải mã K, đường trung bình, trực tâm","kq":"duoc","y":["HK = AB, HK // AB ⇒ ABHK là hình bình hành ⇒ O (trung điểm AH) là trung điểm BK và của MN.","E là trung điểm BC ⇒ OE // CK.","∠AMN = ∠ACB (ý b), ∠EAB = ∠ABC ⇒ MN ⊥ AE ⇒ O là trực tâm ∆AIE ⇒ EO ⊥ AI ⇒ AI ⊥ CK."]}],"binh":["Bài không cần bài toán phụ, nhưng cho thấy rõ cách chọn kết quả của ý b: đi ngược tới “cần MN ⊥ AE” thì mới biết phải lấy góc chứ không lấy tỉ số.","Điểm then chốt là K. Câu hỏi “HK là gì?” biến một điểm cho bằng độ dài thành một điểm có vai rõ ràng (đỉnh hình bình hành). O là điểm nhiều vai nhất: trung điểm AH, MN, BK và là trực tâm của ∆AIE."]},"loai":"sector","gt":["∆ABC vuông tại A (AB < AC), đường cao AH","HM ⊥ AB, HN ⊥ AC; I = MN ∩ BC","K thuộc tia đối của tia NH, NK = BM"],"inputs":[{"code":"V5","text":"AMHN là hình chữ nhật: HN = AM; O là trung điểm AH, MN","keep":1,"why":""},{"code":"P3, P4","text":"ABHK là hình bình hành: O là trung điểm BK","keep":1,"why":""},{"code":"P2","text":"OE // CK (E là trung điểm BC)","keep":1,"why":""},{"code":"V2, G6","text":"∠EAB = ∠ABC","keep":1,"why":""},{"code":"S1","text":"ý b: ∠AMN = ∠ACB ⇒ MN ⊥ AE","keep":1,"why":""},{"code":"Q1","text":"O là trực tâm ∆AIE","keep":1,"why":""},{"code":"V3","text":"ý b: HN = AB.sin²B","keep":0,"why":"Không phục vụ điều đang cần ở ý 3."}],"steps":[{"cm":"HK = HN + NK = AM + BM = AB","ld":"N nằm giữa H và K; HN = AM (AMHN là hình chữ nhật); NK = BM (gt)","codes":["V5"]},{"cm":"ABHK là hình bình hành","ld":"HK // AB (cùng ⊥ AC), HK = AB","codes":["P3","P4"]},{"cm":"O = AH ∩ BK là trung điểm của AH, của BK và của MN (O ∈ MN)","ld":"Đường chéo của hình bình hành ABHK và hình chữ nhật AMHN","codes":["P4","V5"]},{"cm":"Gọi E là trung điểm BC: OE // CK","ld":"OE là đường trung bình của ∆BKC","codes":["P2"]},{"cm":"∠EAB = ∠ABC","ld":"EA = EB (trung tuyến ứng với cạnh huyền)","codes":["V2","G6"]},{"cm":"Gọi J = MN ∩ AE: ∠AMJ + ∠MAJ = ∠ACB + ∠ABC = 90° ⇒ MN ⊥ AE","ld":"Ý b: ∠AMN = ∠ACB; từ 5","codes":["S1","G7"]},{"cm":"O là trực tâm của ∆AIE ⇒ EO ⊥ AI","ld":"Hai đường cao AH, IJ cắt nhau tại O","codes":["Q1"]},{"cm":"AI ⊥ CK","ld":"Từ 4 và 7","codes":["K3"]}]},{"boost":[],"id":"1.3","ch":1,"truong":"Dịch Vọng Hậu","ky":"giữa HKI","de":["Cho tam giác ABC vuông tại A có AB < AC, đường cao AH.","a) Giải tam giác ABC biết AB = 9 cm và ∠ABC = 60°.","b) Gọi E là hình chiếu của H trên AB, F là hình chiếu của H trên AC. Chứng minh AE.AB = AH². Từ đó chứng minh tam giác ABC đồng dạng với tam giác AFE.","c) Từ A kẻ đường thẳng vuông góc với EF tại I và AI kéo dài cắt BC tại K. Chứng minh K là trung điểm của BC và cos³B.sin B = IF/BC."],"yl":"c","yc":"Từ A kẻ đường thẳng vuông góc với EF tại I và AI kéo dài cắt BC tại K. Chứng minh K là trung điểm của BC và cos³B.sin B = IF/BC.","kl":"cos³B.sin B = IF/BC","hinh":"img/b1.3.png","huong":"IF = BC.cos³B.sin B: tính IF lần lượt qua AF, AH, AB, BC.","giu":"∆ABC ∽ ∆AFE nên ∠AFE = ∠ABC.","noi":"Dùng ∠AFE = ∠ABC trong tam giác vuông AIF (IF = AF.cos B), và để chứng minh K là trung điểm BC.","nhin":"Nếu ∆ABC vuông cân tại A thì hệ thức ở ý c trở thành gì? Kiểm tra lại bằng số.","nhinDap":"Khi ∆ABC vuông cân, ∠B = 45°: cos³B.sin B = 1/4, nên IF = BC/4.","deep":{"huong":[{"ten":"Tính độ dài bằng hệ thức lượng","kq":"dai","y":["∆AEF vuông tại A có đường cao AI ⇒ IF = AF²/EF; AEHF là hình chữ nhật nên EF = AH; AF = AH²/AC. Do đó IF = AH³/AC².","AH = AB.AC/BC ⇒ IF = AB³.AC/BC³ ⇒ IF/BC = (AB/BC)³.(AC/BC) = cos³B.sin B."]},{"ten":"Giữ nguyên góc B qua bốn tam giác vuông","kq":"duoc","y":["IF = AF.cos B (vì ∠AFI = ∠ABC); AF = AH.cos B (∠HAF = ∠ABC); AH = AB.sin B; AB = BC.cos B.","Nhân lại: IF = BC.cos³B.sin B."]}],"binh":["Cả hai hướng đều đúng. Hướng 2 ngắn vì mọi bước đều dùng một góc bằng góc B – đó là lí do chọn kết quả “góc” ở ý b.","Mẹo đếm thừa số trong kết luận (cos³B.sin B có bốn thừa số) cho biết trước số tam giác vuông phải đi qua."]},"loai":"sector","gt":["∆ABC vuông tại A (AB < AC), đường cao AH","HE ⊥ AB, HF ⊥ AC","AI ⊥ EF tại I; AI cắt BC tại K"],"inputs":[{"code":"S1","text":"ý b: ∠AFE = ∠ABC","keep":1,"why":""},{"code":"G7, G6","text":"KA = KB = KC","keep":1,"why":""},{"code":"V3","text":"IF = AF.cos B","keep":1,"why":""},{"code":"G4, V3","text":"AF = AH.cos B","keep":1,"why":""},{"code":"V3","text":"AH = AB.sin B; AB = BC.cos B","keep":1,"why":""},{"code":"V1","text":"ý b: AE.AB = AH²","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∠AFE = ∠ABC","ld":"Ý b: ∆ABC ∽ ∆AFE","codes":["S1"]},{"cm":"∠IAF = 90° − ∠AFI = 90° − ∠ABC = ∠ACB ⇒ KA = KC","ld":"∆AIF vuông tại I; ∆KAC cân tại K","codes":["G7","G6"]},{"cm":"∠KAB = 90° − ∠KAC = 90° − ∠ACB = ∠ABC ⇒ KA = KB","ld":"∠BAC = 90°; ∆KAB cân tại K","codes":["G7","G6"]},{"cm":"KB = KC, K ∈ BC ⇒ K là trung điểm BC","ld":"Từ 2 và 3","codes":["K2"]},{"cm":"IF = AF.cos∠AFI = AF.cos B","ld":"∆AIF vuông tại I; dòng 1","codes":["V3"]},{"cm":"AF = AH.cos∠HAF = AH.cos B","ld":"∆AHF vuông tại F; ∠HAF = ∠ABC (cùng phụ ∠ACB)","codes":["V3","G4"]},{"cm":"AH = AB.sin B; AB = BC.cos B","ld":"∆AHB vuông tại H; ∆ABC vuông tại A","codes":["V3"]},{"cm":"IF = BC.cos³B.sin B ⇒ cos³B.sin B = IF/BC","ld":"Từ 5, 6, 7","codes":["K6"]}]},{"boost":[],"id":"1.4","ch":1,"truong":"Ái Mộ – đề 1","ky":"giữa HKI","de":["Cho tam giác ABC vuông tại A (AB > AC) có AB = 5 cm và đường cao AH = 3 cm.","a) Tính số đo góc B (làm tròn kết quả đến phút) và độ dài cạnh BC (làm tròn đến hàng đơn vị).","b) Gọi D là trung điểm của cạnh BC. Kẻ DE vuông góc với AB (E ∈ AB). Chứng minh 4 điểm A, E, D, H cùng nằm trên một đường tròn, tính bán kính của đường tròn đó.","c) Chứng minh AH² = BH.HC."],"yl":"c","yc":"Chứng minh AH² = BH.HC.","kl":"AH² = BH.HC","hinh":"img/b1.4.png","huong":"AH/CH = BH/AH, tức ∆AHB ∽ ∆CHA.","giu":"Góc vuông tại H (AH ⊥ BC).","noi":"∆AHB và ∆CHA: chung đỉnh H, cùng vuông tại H, ∠BAH = ∠ACH.","nhin":"Hệ thức AH² = BH.HC còn chứng minh được bằng những cách nào khác?","nhinDap":"Dùng hệ thức lượng trong tam giác vuông; hoặc định lí Pythagore: AB² + AC² = BC² với AB² = AH² + BH², AC² = AH² + HC² cho 2AH² = 2BH.HC.","deep":{"huong":[{"ten":"Định lí Pythagore","kq":"duoc","y":["AB² = AH² + BH², AC² = AH² + HC², AB² + AC² = BC² = (BH + HC)².","Cộng hai đẳng thức đầu và so sánh: 2AH² + BH² + HC² = BH² + 2BH.HC + HC² ⇒ AH² = BH.HC."]},{"ten":"Tam giác đồng dạng","kq":"duoc","y":["∠BAH = ∠ACH (cùng phụ với ∠ABC) ⇒ ∆AHB ∽ ∆CHA (g.g) ⇒ AH/CH = BH/AH."]},{"ten":"Dùng hệ thức lượng có sẵn","kq":"dai","y":["Hệ thức h² = b'.c' trong sách giáo khoa chính là kết luận. Nếu đề yêu cầu chứng minh thì không được dùng trực tiếp."]}],"binh":["Bài nền giúp luyện thói quen “đẳng thức tích → đọc tên tam giác” (Chương 0, §3). Hướng Pythagore cũng tốt, nhưng không mở rộng được cho các bài khó hơn."]},"loai":"sector","gt":["∆ABC vuông tại A (AB > AC), AB = 5 cm, đường cao AH = 3 cm","D là trung điểm BC; DE ⊥ AB"],"inputs":[{"code":"G4","text":"∠BAH = ∠ACH","keep":1,"why":""},{"code":"S3","text":"∆AHB ∽ ∆CHA","keep":1,"why":""},{"code":"S2","text":"AH/CH = BH/AH","keep":1,"why":""},{"code":"N1","text":"ý b: A, E, D, H cùng thuộc đường tròn","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∠AHB = ∠CHA = 90°","ld":"AH ⊥ BC (gt)","codes":[]},{"cm":"∠BAH = ∠ACH","ld":"Cùng phụ với ∠ABC","codes":["G4"]},{"cm":"∆AHB ∽ ∆CHA","ld":"Từ 1 và 2 (g.g)","codes":["S3"]},{"cm":"AH/CH = BH/AH ⇒ AH² = BH.HC","ld":"Cạnh tương ứng tỉ lệ","codes":["S1","K6"]}]},{"boost":[],"id":"1.5","ch":1,"truong":"Hà Đông","ky":"cuối HKI","de":["Cho ∆ABC vuông tại A (AB < AC), đường cao AH. Vẽ đường tròn tâm A, bán kính AH. Từ điểm C kẻ tiếp tuyến CM với đường tròn (A; AH) (M là tiếp điểm, M không nằm trên đường thẳng BC).","a) Chứng minh bốn điểm A, M, C và H cùng thuộc một đường tròn.","b) Gọi I là giao điểm của AC và MH. Kẻ đường kính MD của đường tròn (A). Chứng minh BD là tiếp tuyến của đường tròn (A) và BH.HC = AI.AC.","c) Vẽ đường tròn tâm O, đường kính BC cắt đường tròn (A) tại P và Q. Chứng minh PQ // DM."],"yl":"c","yc":"Vẽ đường tròn tâm O, đường kính BC cắt đường tròn (A) tại P và Q. Chứng minh PQ // DM.","kl":"PQ // DM","hinh":"img/b1.5.png","huong":"MD ⊥ AO (vì PQ ⊥ AO).","giu":"CA là đường trung trực của HM nên ∠MAC = ∠HAC; MD là đường kính của (A).","noi":"A nằm trên (O) đường kính BC. Dây chung PQ vuông góc với đường nối tâm AO.","nhin":"Bài này dùng tính chất “dây chung vuông góc với đường nối tâm”. Còn bài nào trong sách dùng tính chất này?","nhinDap":"Tính chất “đường thẳng qua tâm vuông góc với dây” còn gặp ở Bài 3.3, 3.6, 3.7 (trục đối xứng chung của hai dây).","deep":{"huong":[{"ten":"Tìm cặp góc so le","kq":"dai","y":["Thử lấy AO làm cát tuyến chung của PQ và DM. Muốn so sánh góc tạo bởi PQ với AO thì lại phải biết PQ ⊥ AO."]},{"ten":"Cùng vuông góc với AO","kq":"duoc","y":["A thuộc (O) (đường tròn đường kính BC); AP = AQ, OP = OQ ⇒ AO là trung trực của PQ ⇒ PQ ⊥ AO.","∠OAC = ∠ACB (∆OAC cân), ∠MAC = 90° − ∠ACB ⇒ ∠MAO = 90° ⇒ DM ⊥ AO."]}],"binh":["Dây chung của hai đường tròn là dấu hiệu rất mạnh: nó vuông góc với đường nối tâm. Song song khi đó được đổi thành “cùng vuông góc với AO”."]},"loai":"sector","gt":["∆ABC vuông tại A, đường cao AH; đường tròn (A; AH)","CM tiếp xúc (A) tại M; MD là đường kính của (A)","(O) đường kính BC cắt (A) tại P, Q"],"inputs":[{"code":"V2","text":"OA = OB = OC: A ∈ (O)","keep":1,"why":""},{"code":"N5","text":"AO là trung trực của PQ ⇒ PQ ⊥ AO","keep":1,"why":""},{"code":"G6","text":"∠OAC = ∠ACB","keep":1,"why":""},{"code":"T2","text":"∠MAC = ∠HAC = 90° − ∠ACB","keep":1,"why":""},{"code":"K4","text":"PQ // DM ⇐ cùng ⊥ AO","keep":1,"why":""},{"code":"V1","text":"ý b: BH.HC = AI.AC","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"OA = OB = OC ⇒ A thuộc (O)","ld":"∆ABC vuông tại A, O là trung điểm BC","codes":["V2"]},{"cm":"AO là trung trực của PQ ⇒ PQ ⊥ AO","ld":"AP = AQ (bán kính (A)), OP = OQ (bán kính (O))","codes":["N5"]},{"cm":"∠OAC = ∠ACB","ld":"∆OAC cân tại O","codes":["G6"]},{"cm":"∠MAC = ∠HAC = 90° − ∠ACB","ld":"CH, CM là hai tiếp tuyến của (A); ∆AHC vuông tại H","codes":["T2","G7"]},{"cm":"∠MAO = ∠MAC + ∠CAO = 90° ⇒ MD ⊥ AO","ld":"Từ 3 và 4","codes":[]},{"cm":"PQ // DM","ld":"Cùng vuông góc với AO","codes":["P3","K4"]}]},{"boost":[],"id":"1.6","ch":1,"truong":"Hát Môn","ky":"cuối HKII","de":["Cho tam giác ABC vuông tại A. Lấy điểm M bất kì trên đoạn AC, đường tròn đường kính CM cắt hai đường thẳng BM, BC lần lượt tại D, N. Chứng minh rằng:","a) Tứ giác ABCD nội tiếp.","b) BM.BD = BN.BC.","c) Các đường thẳng AB, MN, CD cùng đi qua một điểm."],"yl":"c","yc":"Các đường thẳng AB, MN, CD cùng đi qua một điểm.","kl":"AB, MN, CD đồng quy","hinh":"img/b1.6.png","huong":"S, M, N thẳng hàng (S = AB ∩ CD), tức SM ⊥ BC và MN ⊥ BC.","giu":"Từ ý a: ∠BDC = 90°, tức BD ⊥ CD.","noi":"CA ⊥ SB và BD ⊥ SC nên M là giao điểm của hai đường cao: M là trực tâm của ∆SBC.","nhin":"M “hoá ra” là trực tâm. Tìm ở Chương 4 một bài có điểm cũng hoá ra là trực tâm.","nhinDap":"Bài 4.7 (Nghĩa Tân): I là giao điểm của EB và SO, hoá ra là trực tâm của ∆SJB.","deep":{"huong":[{"ten":"Chứng minh MN đi qua S bằng góc","kq":"tac","y":["Thử tính góc tại N hoặc tại M để có S, M, N thẳng hàng. S nằm ngoài hình, góc tại S không liên hệ trực tiếp với N."]},{"ten":"Trực tâm","kq":"duoc","y":["Trong ∆SBC: CA ⊥ SB, BD ⊥ SC ⇒ M là trực tâm ⇒ SM ⊥ BC.","MN ⊥ BC ⇒ S, M, N thẳng hàng ⇒ ba đường đồng quy tại S."]}],"binh":["Hỏi “M là gì của tam giác SBC?” – M là điểm nhiều vai (vừa nằm trên AC, vừa nằm trên BD). Khi một điểm là giao của hai đường vuông góc với hai cạnh, hãy nghĩ tới trực tâm."]},"loai":"sector","gt":["∆ABC vuông tại A; M ∈ AC","Đường tròn đường kính CM cắt BM tại D, cắt BC tại N"],"inputs":[{"code":"G2","text":"∠MDC = ∠MNC = 90°","keep":1,"why":""},{"code":"K5","text":"gọi S = AB ∩ CD","keep":1,"why":""},{"code":"Q1","text":"M là trực tâm ∆SBC ⇒ SM ⊥ BC","keep":1,"why":""},{"code":"K1","text":"SM ⊥ BC, MN ⊥ BC","keep":1,"why":""},{"code":"S2","text":"ý b: BM.BD = BN.BC","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"CD cắt AB tại S","ld":"Nếu CD // AB thì BD // AC, vô lí vì BD cắt AC tại M","codes":[]},{"cm":"BD ⊥ SC","ld":"∠BDC = ∠MDC = 90° (D thuộc đường tròn đường kính CM)","codes":["G2"]},{"cm":"CA ⊥ SB","ld":"∠BAC = 90° (gt)","codes":[]},{"cm":"M là trực tâm của ∆SBC ⇒ SM ⊥ BC","ld":"Hai đường cao CA, BD cắt nhau tại M","codes":["Q1"]},{"cm":"MN ⊥ BC","ld":"∠MNC = 90°","codes":["G2"]},{"cm":"S, M, N thẳng hàng ⇒ AB, MN, CD cùng đi qua S","ld":"Qua M chỉ có một đường thẳng vuông góc với BC","codes":["K1","K5"]}]},{"boost":[],"id":"2.1","ch":2,"truong":"Ái Mộ – đề 2","ky":"giữa HKI","de":["Cho ∆ABC vuông tại A (AB < AC), đường cao AH.","a) Cho biết AB = 4, 5 cm; AC = 6 cm. Tính BC, ∠B, Ĉ (kết quả góc làm tròn đến phút).","b) Gọi M là trung điểm của BC. Kẻ BE ⊥ AM tại E, BE cắt AH tại D. Chứng minh bốn điểm D, H, M, E cùng thuộc một đường tròn.","c) BE cắt AC tại F. Chứng minh BE.BF = AB² và BE.BF = BH.BC."],"yl":"c","yc":"BE cắt AC tại F. Chứng minh BE.BF = AB² và BE.BF = BH.BC.","kl":"BE.BF = BH.BC","hinh":"img/b2.1.png","huong":"BE.BF = AB² và BH.BC = AB².","giu":"BE ⊥ AM tại E và ∠BAC = 90°.","noi":"∆ABF vuông tại A có đường cao AE; ∆ABC vuông tại A có đường cao AH.","nhin":"Từ BE.BF = BH.BC, em có thể viết ra cặp tam giác đồng dạng nào?","nhinDap":"BE/BC = BH/BF và ∠B chung nên ∆BEH ∽ ∆BCF.","deep":{"huong":[{"ten":"Đọc tên tam giác từ tỉ lệ thức","kq":"duoc","y":["BE/AB = AB/BF ⇒ ∆BEA ∽ ∆BAF (chung ∠B, cùng có góc vuông).","BH/AB = AB/BC ⇒ ∆BHA ∽ ∆BAC."]},{"ten":"Hệ thức lượng","kq":"duoc","y":["Trong ∆ABF vuông tại A, đường cao AE: AB² = BE.BF. Trong ∆ABC: AB² = BH.BC."]}],"binh":["Bài nền của mô hình “tam giác vuông có đường cao”. Điều cần luyện: nhìn ra tam giác vuông ABF có đường cao AE dù đề không nói thẳng."]},"loai":"sector","gt":["∆ABC vuông tại A, đường cao AH","M là trung điểm BC; BE ⊥ AM tại E","BE cắt AH tại D, cắt AC tại F"],"inputs":[{"code":"V1","text":"∆ABF vuông tại A, đường cao AE: AB² = BE.BF","keep":1,"why":""},{"code":"V1","text":"∆ABC vuông tại A, đường cao AH: AB² = BH.BC","keep":1,"why":""},{"code":"N1","text":"ý b: D, H, M, E cùng thuộc đường tròn","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∆ABF ∽ ∆EBA ⇒ AB/EB = BF/BA ⇒ AB² = BE.BF","ld":"∠BAF = ∠BEA = 90°; ∠ABF chung (g.g)","codes":["S3","V1"]},{"cm":"∆HBA ∽ ∆ABC ⇒ HB/AB = AB/BC ⇒ AB² = BH.BC","ld":"∠BHA = ∠BAC = 90°; ∠ABC chung (g.g)","codes":["S3","V1"]},{"cm":"BE.BF = BH.BC","ld":"Từ 1 và 2","codes":["K6"]}]},{"boost":["B6"],"id":"2.2","ch":2,"truong":"Ngô Gia Tự","ky":"giữa HKI","de":["Cho ∆ABC vuông tại A (AB < AC).","a) Cho AB = 6 cm, AC = 8 cm. Tính độ dài BC và số đo ∠B, Ĉ (kết quả số đo góc làm tròn đến độ).","b) Gọi M là trung điểm của AC, I là hình chiếu của A trên BM. Chứng minh ∆AMB đồng dạng ∆IMA. Từ đó suy ra sin²∠ABM = IM/BM.","c) Gọi K là hình chiếu của M trên BC. Tia AI cắt đường thẳng qua C vuông góc với AC tại N. Chứng minh rằng: ba điểm M, K, N thẳng hàng."],"yl":"c","yc":"Gọi K là hình chiếu của M trên BC. Tia AI cắt đường thẳng qua C vuông góc với AC tại N. Chứng minh rằng: ba điểm M, K, N thẳng hàng.","kl":"M, K, N thẳng hàng","hinh":"img/b2.2.png","huong":"MN ⊥ BC (vì MK ⊥ BC và qua M chỉ có một đường vuông góc với BC).","giu":"∆AMB ∽ ∆IMA nên ∠ABM = ∠IAM = ∠CAN.","noi":"Từ ∆ACN ∽ ∆BAM có CN/AM = AC/AB; thay AM = MC được CN/CM = AC/AB, nên ∆NCM ∽ ∆CAB.","nhin":"Đặt bài này cạnh Bài 2.3 (Nguyễn Du). Hai hình giống nhau ở điểm nào?","nhinDap":"Hai bài cùng có M là trung điểm AC, một đường thẳng qua C vuông góc với AC, và cùng “đổi AM thành MC” để được cặp tam giác mới.","deep":{"huong":[{"ten":"Góc bẹt tại K","kq":"tac","y":["Thử chứng minh ∠MKC + ∠CKN = 180°. ∠MKC = 90°, nhưng ∠CKN chưa có gì để tính vì chưa biết N nằm đâu so với K."]},{"ten":"Đổi sang vuông góc, đổi AM thành MC","kq":"duoc","y":["∠CAN = ∠ABM ⇒ ∆ACN ∽ ∆BAM ⇒ CN/AM = AC/AB.","AM = MC ⇒ CN/CM = AC/AB ⇒ ∆NCM ∽ ∆CAB ⇒ ∠CMN = ∠ABC ⇒ MN ⊥ BC."]}],"binh":["Bước “thay AM bằng MC” là dạng đơn giản nhất của bài toán phụ 6: trung điểm cho phép đổi một cạnh của cặp tam giác cũ để được cặp mới. Dấu hiệu: có trung điểm M nằm trên cạnh AC của cặp tam giác vừa có."]},"loai":"sector","gt":["∆ABC vuông tại A (AB < AC)","M là trung điểm AC; AI ⊥ BM","MK ⊥ BC; CN ⊥ AC, N ∈ tia AI"],"inputs":[{"code":"S1","text":"ý b: ∠ABM = ∠CAN","keep":1,"why":""},{"code":"S3","text":"∆ACN ∽ ∆BAM","keep":1,"why":""},{"code":"K6","text":"AM = MC ⇒ CN/CM = AC/AB","keep":1,"why":""},{"code":"S1","text":"∆NCM ∽ ∆CAB","keep":1,"why":""},{"code":"G7","text":"MN ⊥ BC","keep":1,"why":""},{"code":"V3","text":"ý b: sin²∠ABM","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∠ABM = ∠IAM = ∠CAN","ld":"Ý b: ∆AMB ∽ ∆IMA; I ∈ AN, M ∈ AC","codes":[]},{"cm":"∆ACN ∽ ∆BAM ⇒ CN/AM = AC/AB","ld":"∠ACN = ∠BAM = 90°; từ 1 (g.g)","codes":["S3"]},{"cm":"CN/CM = AC/AB ⇒ CN/AC = CM/AB","ld":"AM = CM (M là trung điểm AC)","codes":[]},{"cm":"∆NCM ∽ ∆CAB ⇒ ∠CMN = ∠ABC","ld":"∠NCM = ∠CAB = 90°; từ 3 (c.g.c)","codes":["S1"]},{"cm":"Gọi K' = MN ∩ BC: ∠CMK' + ∠MCK' = ∠ABC + ∠ACB = 90° ⇒ MN ⊥ BC","ld":"Từ 4","codes":["G7"]},{"cm":"M, K, N thẳng hàng","ld":"MK ⊥ BC; qua M chỉ có một đường vuông góc với BC","codes":["K1"]}]},{"boost":["B6"],"id":"2.3","ch":2,"truong":"Nguyễn Du","ky":"giữa HKI","de":["Cho tam giác ABC vuông tại A (AB < AC).","a) Giả sử AB = 6 cm; BC = 10 cm. Tính AC và số đo ∠ACB (góc làm tròn đến độ).","b) Gọi M là trung điểm của đoạn thẳng AC, kẻ AH ⊥ BM tại H. Chứng minh: AM/BM = HM/AM và cos²∠AMB = HM/BM.","c) Kẻ MI ⊥ BC tại I. Qua C kẻ đường thẳng vuông góc với AC, đường thẳng này cắt đường thẳng MI tại K. Chứng minh ba điểm A, H, K thẳng hàng."],"yl":"c","yc":"Kẻ MI ⊥ BC tại I. Qua C kẻ đường thẳng vuông góc với AC, đường thẳng này cắt đường thẳng MI tại K. Chứng minh ba điểm A, H, K thẳng hàng.","kl":"A, H, K thẳng hàng","hinh":"img/b2.3.png","huong":"∠MAH = ∠CAK (hai tia AH, AK trùng nhau).","giu":"∆AMH ∽ ∆BMA nên ∠MAH = ∠MBA.","noi":"∆ABC ∽ ∆CMK; thay CM = AM được ∆ABM ∽ ∆CAK nên ∠CAK = ∠ABM.","nhin":"Đổi “M là trung điểm của AC” thành “AM = 2MC”, kết luận còn đúng không? Vì sao?","nhinDap":"Không còn đúng nói chung: bước ∆ABM ∽ ∆CAK cần AM = CM. Thử trên phần mềm với AM = 2MC sẽ thấy A, H, K không thẳng hàng.","deep":{"huong":[{"ten":"Góc bẹt tại H","kq":"tac","y":["Cần ∠AHM + ∠MHK = 180°. K liên hệ với H qua đâu? Chưa có gì, vì K được xác định từ C và I."]},{"ten":"Hai tia trùng nhau","kq":"duoc","y":["∆ABC ∽ ∆CMK (hai tam giác vuông, ∠ACB = ∠CKM) ⇒ AB/CM = AC/CK; thay CM = AM ⇒ ∆ABM ∽ ∆CAK ⇒ ∠CAK = ∠ABM = ∠MAH."]}],"binh":["Bài 2.2 và 2.3 là cặp “thuận – đảo” trên cùng một hình: một bài đổi thẳng hàng thành vuông góc, một bài đổi thành hai tia trùng nhau. Cả hai đều dùng “thay AM bằng MC”."]},"loai":"sector","gt":["∆ABC vuông tại A (AB < AC)","M là trung điểm AC; AH ⊥ BM","MI ⊥ BC; CK ⊥ AC, K ∈ MI"],"inputs":[{"code":"S1","text":"ý b: ∠MAH = ∠MBA","keep":1,"why":""},{"code":"G4","text":"∠CKM = ∠ACB","keep":1,"why":""},{"code":"S3","text":"∆ABC ∽ ∆CMK","keep":1,"why":""},{"code":"K6","text":"CM = AM ⇒ AB/CA = AM/CK","keep":1,"why":""},{"code":"S1","text":"∆ABM ∽ ∆CAK","keep":1,"why":""},{"code":"V3","text":"ý b: cos²∠AMB","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∠MAH = ∠MBA","ld":"Ý b: ∆AMH ∽ ∆BMA","codes":["S1"]},{"cm":"∠CKM = 90° − ∠CMK = 90° − ∠CMI = ∠ACB","ld":"∆MCK vuông tại C, ∆MIC vuông tại I","codes":["G7","G4"]},{"cm":"∆ABC ∽ ∆CMK ⇒ AB/CM = AC/CK","ld":"∠BAC = ∠MCK = 90°; từ 2 (g.g)","codes":["S3"]},{"cm":"AB/CA = AM/CK","ld":"CM = AM (M là trung điểm AC)","codes":[]},{"cm":"∆ABM ∽ ∆CAK ⇒ ∠ABM = ∠CAK","ld":"∠BAM = ∠ACK = 90°; từ 4 (c.g.c)","codes":["S1"]},{"cm":"∠MAH = ∠CAK ⇒ tia AH trùng tia AK ⇒ A, H, K thẳng hàng","ld":"Từ 1 và 5; H, K cùng phía đối với AC","codes":["K1"]}]},{"boost":[],"id":"2.5","ch":2,"truong":"Ngọc Lâm","ky":"giữa HKI","de":["Cho tam giác ABC vuông tại A, đường cao AH.","a) Biết BC = 5 cm, AC = 4 cm. Tính độ dài cạnh AB và số đo ∠ABC (làm tròn đến độ).","b) Chứng minh rằng các điểm A, B, C cùng thuộc một đường tròn.","c) Chứng minh BC = AB.cos B + AC.cos C.","d) Gọi E là hình chiếu của H trên AB. Gọi I là trung điểm BE. Trên tia HC lấy K sao cho HK = BI. Chứng minh tam giác AIK là tam giác cân."],"yl":"d","yc":"Gọi E là hình chiếu của H trên AB. Gọi I là trung điểm BE. Trên tia HC lấy K sao cho HK = BI. Chứng minh tam giác AIK là tam giác cân.","kl":"∆AIK cân","hinh":"img/b2.5.png","huong":"AI² = AK².","giu":"AE.AB = AH² (∆AEH ∽ ∆AHB).","noi":"AI nằm trên AB, AK nằm trong ∆AHK vuông tại H. AI² = AE.AB + BI² = AH² + BI² = AK².","nhin":"Em đã tính AI², AK² qua những đoạn nào? Cách “so sánh bình phương” còn dùng được ở bài nào khác?","nhinDap":"AI², AK² cùng được viết thành AH² cộng một bình phương bằng nhau (BI² = HK²). Cách “so sánh bình phương” hợp khi hai đoạn nằm trong hai tam giác vuông khác nhau.","deep":{"huong":[{"ten":"Tìm hai tam giác bằng nhau","kq":"tac","y":["Thử ∆AHI và ∆AHK, ∆ABI và ∆A?K… không có cặp nào có đủ yếu tố bằng nhau."]},{"ten":"So sánh bình phương","kq":"duoc","y":["AK² = AH² + BI².","AI² = (AE + BI)² = AE² + AE.BE + BI² = AE.AB + BI² = AH² + BI² ⇒ AI = AK."]}],"binh":["Khi hai đoạn cần bằng nhau nằm trên hai đường khác nhau và không có cặp tam giác bằng nhau, hãy so sánh bình phương qua Pythagore và hệ thức lượng."]},"loai":"sector","gt":["∆ABC vuông tại A, đường cao AH","HE ⊥ AB; I là trung điểm BE","K ∈ tia HC, HK = BI"],"inputs":[{"code":"S3, V1","text":"AE.AB = AH²","keep":1,"why":""},{"code":"V4","text":"AK² = AH² + BI²","keep":1,"why":""},{"code":"K6","text":"AI² = AE.AB + BI²","keep":1,"why":""},{"code":"S4","text":"hai tam giác bằng nhau chứa AI, AK – không có","keep":0,"why":""},{"code":"V3","text":"ý c","keep":0,"why":"Không phục vụ điều đang cần ở ý d."}],"steps":[{"cm":"AE.AB = AH²","ld":"∆AEH ∽ ∆AHB (g.g)","codes":["S3","V1"]},{"cm":"AK² = AH² + HK² = AH² + BI²","ld":"∆AHK vuông tại H; HK = BI (gt)","codes":["V4"]},{"cm":"AI = AE + BI; BE = 2BI","ld":"E nằm giữa A và B; I là trung điểm BE","codes":[]},{"cm":"AI² = AE² + AE.BE + BI² = AE.AB + BI²","ld":"Từ 3","codes":[]},{"cm":"AI² = AH² + BI²","ld":"Từ 1 và 4","codes":[]},{"cm":"AI = AK: ∆AIK cân tại A","ld":"Từ 2 và 5","codes":["K6"]}]},{"boost":["B6"],"id":"2.6","ch":2,"truong":"Mỹ Đình 2","ky":"giữa HKII","de":["Cho ∆ABC vuông tại A. Gọi O là trung điểm của cạnh AC. Đường tròn tâm O đường kính AC cắt cạnh BC tại D (D khác C). Kẻ AE vuông góc với OB tại E.","a) Chứng minh bốn điểm A, B, D, E cùng thuộc một đường tròn.","b) Tiếp tuyến tại C của đường tròn (O) cắt tia AD và tia AE lần lượt ở H và K. Chứng minh ∠EAD = ∠EBD và ∆AHK ∽ ∆BCO.","c) Chứng minh K là trung điểm của đoạn thẳng HC."],"yl":"c","yc":"Chứng minh K là trung điểm của đoạn thẳng HC.","kl":"K là trung điểm HC","hinh":"img/b2.6.png","huong":"∠CAK = ∠CAK' với K' là trung điểm CH (điểm trùng).","giu":"AD ⊥ BC (D thuộc đường tròn đường kính AC) nên ∠CAH = ∠ABC.","noi":"∆BAC ∽ ∆ACH có O là trung điểm cạnh AC; ∠CAK = ∠OAE = ∠ABO.","nhin":"Đổi O thành điểm chia AC theo tỉ số 1 : 2. Khi đó K chia HC theo tỉ số nào?","nhinDap":"CK/CH = 1/3, vì CK/CH = AO/AC.","deep":{"huong":[{"ten":"Tỉ số lượng giác","kq":"duoc","y":["CK = AC.tan∠CAK = AC.tan∠ABO = AC.AO/AB = AC²/(2AB).","CH = AC.tan∠CAH = AC.tan∠ABC = AC²/AB ⇒ CK = CH/2."]},{"ten":"Bài toán phụ 6, chiều đảo dạng 2","kq":"duoc","y":["∆BAC ∽ ∆ACH, O là trung điểm AC; gọi K' là trung điểm CH ⇒ ∆BAO ∽ ∆ACK' ⇒ ∠CAK' = ∠ABO = ∠CAK ⇒ K trùng K'."]}],"binh":["Hướng lượng giác ngắn, nhưng nó dùng đúng hai cặp góc ∠CAK = ∠ABO và ∠CAH = ∠ABC mà bài toán phụ 6 chỉ ra. Bài toán phụ giải thích vì sao các góc ấy “khớp” nhau và giúp nghĩ ra lời giải khi các góc không đặc biệt."]},"loai":"sector","gt":["∆ABC vuông tại A; O là trung điểm AC","(O) đường kính AC cắt BC tại D; AE ⊥ OB tại E","Tiếp tuyến tại C của (O) cắt tia AD, AE tại H, K"],"inputs":[{"code":"G2, G4","text":"∠CAH = ∠ABC","keep":1,"why":""},{"code":"S3","text":"∆BAC ∽ ∆ACH","keep":1,"why":""},{"code":"B6","text":"K' trung điểm CH ⇒ ∠ABO = ∠CAK'","keep":1,"why":""},{"code":"G4","text":"∠CAK = ∠ABO","keep":1,"why":""},{"code":"K2","text":"điểm trùng K ≡ K'","keep":1,"why":""},{"code":"S1","text":"ý b: ∆AHK ∽ ∆BCO","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∠CAH = ∠CAD = 90° − ∠ACB = ∠ABC","ld":"∠ADC = 90° (chắn nửa đường tròn)","codes":["G2","G4"]},{"cm":"∆BAC ∽ ∆ACH (B ↔ A, A ↔ C, C ↔ H)","ld":"∠BAC = ∠ACH = 90° (CH ⊥ AC); từ 1 (g.g)","codes":["S3"]},{"cm":"Gọi K' là trung điểm CH: ∆BAO ∽ ∆ACK' ⇒ ∠ABO = ∠CAK'","ld":"O, K' là trung điểm hai cạnh tương ứng AC, CH","codes":["B6"]},{"cm":"∠CAK = ∠OAE = 90° − ∠AOB = ∠ABO","ld":"∆ABO vuông tại A có đường cao AE","codes":["G7","G4"]},{"cm":"∠CAK = ∠CAK' ⇒ K trùng K' ⇒ K là trung điểm HC","ld":"K, K' cùng nằm trên đoạn CH","codes":["K2"]}]},{"boost":["B7"],"id":"3.1","ch":3,"truong":"Ái Mộ – đề 3","ky":"giữa HKI","de":["Cho ∆ABC có ba góc nhọn, AB > AC, hai đường cao BD và CE cắt nhau tại H.","a) Chứng minh rằng bốn điểm B, E, D, C cùng thuộc một đường tròn. Hãy chỉ rõ tâm O của đường tròn này.","b) Chứng minh: AB.AE = AC.AD.","c) Gọi R là bán kính của đường tròn tâm O. Giả sử ∠DBC = 30°, trên tia đối của tia CB lấy điểm M sao cho CM = R. Chứng minh: DM² = 3R²."],"yl":"c","yc":"Gọi R là bán kính của đường tròn tâm O. Giả sử ∠DBC = 30°, trên tia đối của tia CB lấy điểm M sao cho CM = R. Chứng minh: DM² = 3R².","kl":"DM² = 3R²","hinh":"img/b3.1.png","huong":"DM = DB và DB = R√3.","giu":"B, E, D, C cùng thuộc (O; R), O là trung điểm BC (ý a).","noi":"Ý bổ sung: từ ∆ABD ∽ ∆ACE (chung đỉnh A) suy ra ∆ABC ∽ ∆ADE. Ý c: CD = CM = R nên ∆CDM cân tại C.","nhin":"Giả thiết ∠DBC = 30° được dùng ở những bước nào? Bỏ nó đi thì ý c còn đúng không?","nhinDap":"Giả thiết dùng để có ∠DCB = 60°, CD = R, ∆CDM cân có góc ở đỉnh 120° và ∆DBM cân. Bỏ đi thì ý c không còn đúng nói chung.","deep":{"huong":[{"ten":"Pythagore với chân đường vuông góc","kq":"duoc","y":["Kẻ DK ⊥ BC. ∆DKC vuông tại K có ∠DCK = 60° ⇒ DK = R.sin 60° = R√3/2, KC = R/2.","KM = KC + CM = 3R/2 ⇒ DM² = DK² + KM² = 3R²/4 + 9R²/4 = 3R²."]},{"ten":"Đoán đoạn bằng nhau từ con số","kq":"duoc","y":["CD = R = CM ⇒ ∆CDM cân, ∠DCM = 120° ⇒ ∠CMD = 30° = ∠DBM ⇒ DM = DB = R√3."]}],"binh":["Hai hướng đều tốt. Hướng 2 rèn thói quen “nhìn con số trong kết luận để đoán đoạn bằng nhau”, rất hữu ích ở các ý tính toán."]},"loai":"sector","gt":["∆ABC nhọn (AB > AC), đường cao BD, CE cắt nhau tại H","O là trung điểm BC, R = BC/2; ∠DBC = 30°","M thuộc tia đối của tia CB, CM = R"],"inputs":[{"code":"V3","text":"CD = R; DB = R√3","keep":1,"why":""},{"code":"G7","text":"∠DCM = 120°","keep":1,"why":""},{"code":"G6","text":"∠CDM = ∠CMD = 30°","keep":1,"why":""},{"code":"G6","text":"∆DBM cân tại D","keep":1,"why":""},{"code":"S2","text":"ý b: AB.AE = AC.AD","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"CD = BC.sin∠DBC = 2R.sin 30° = R","ld":"∆BDC vuông tại D, BC = 2R","codes":["V3"]},{"cm":"∠DCB = 90° − 30° = 60° ⇒ ∠DCM = 120°","ld":"; hai góc kề bù","codes":["G7"]},{"cm":"∠CDM = ∠CMD = (180° − 120°)/2 = 30°","ld":"CD = CM = R: ∆CDM cân tại C","codes":["G6"]},{"cm":"∠DBM = ∠DMB = 30° ⇒ DM = DB","ld":"∆DBM cân tại D","codes":["G6"]},{"cm":"DB = BC.cos 30° = R√3","ld":"∆BDC vuông tại D","codes":["V3"]},{"cm":"DM² = DB² = 3R²","ld":"Từ 4 và 5","codes":["K6"]}]},{"boost":["B7"],"id":"3.3","ch":3,"truong":"Cầu Diễn","ky":"giữa HKII","de":["Cho ∆ABC nội tiếp đường tròn (O; R). Cho hai đường cao AD, BE của ∆ABC cắt nhau tại H.","a) Chứng minh tứ giác AEDB nội tiếp.","b) Kẻ đường kính AK của đường tròn (O). Chứng minh ∆ADB ∽ ∆ACK và AB.AC = 2AD.R.","c) Gọi F là hình chiếu của điểm B trên AK, M là trung điểm của BC. Chứng minh DF // CK, từ đó suy ra ba điểm E, F, M thẳng hàng."],"yl":"c","yc":"Gọi F là hình chiếu của điểm B trên AK, M là trung điểm của BC. Chứng minh DF // CK, từ đó suy ra ba điểm E, F, M thẳng hàng.","kl":"DF // CK; E, F, M thẳng hàng","hinh":"img/b3.3.png","huong":"Tia MF trùng tia ME (NM là trục đối xứng chung của hai dây DF, BE).","giu":"∆ADB ∽ ∆ACK; ABDE nội tiếp đường tròn đường kính AB.","noi":"A, B, D, E, F cùng thuộc đường tròn đường kính AB (tâm N là trung điểm AB). NM // AC nên NM vuông góc với cả DF và BE.","nhin":"Đường thẳng nào là trục đối xứng chung? Tìm hai bài khác trong chương dùng cùng ý này.","nhinDap":"NM là trục đối xứng chung của hai dây DF, BE. Cùng ý này: Bài 3.6 (Thăng Long), Bài 3.7 (Đại Áng).","deep":{"huong":[{"ten":"Góc bẹt tại F","kq":"tac","y":["Cần ∠EFA + ∠AFM = 180° hoặc tương tự; ∠AFM không tính được vì M không nằm trên đường tròn nào đi qua F."]},{"ten":"Trục đối xứng chung của hai dây","kq":"duoc","y":["NM ⊥ DF và NM ⊥ BE, N là tâm ⇒ NM là trung trực của DF và của BE.","Do đó NM là tia phân giác của ∠DMF và ∠BME; tia MD trùng tia MB ⇒ ∠NMF = ∠NME ⇒ tia MF trùng tia ME."]}],"binh":["Dấu hiệu: nhiều điểm cùng nằm trên một đường tròn và có hai dây song song (cùng vuông góc với AC) ⇒ đường thẳng qua tâm vuông góc với hai dây là trục đối xứng chung. Đây là kỹ thuật dùng lại ở Bài 3.6, 3.7."]},"loai":"sector","gt":["∆ABC nội tiếp (O; R); đường cao AD, BE cắt nhau tại H","AK là đường kính; BF ⊥ AK","M là trung điểm BC"],"inputs":[{"code":"N1, N3","text":"∠DFK = ∠ABD","keep":1,"why":""},{"code":"G1, G5","text":"DF // CK","keep":1,"why":""},{"code":"G2","text":"DF ⊥ AC; BE ⊥ AC","keep":1,"why":""},{"code":"N1","text":"A, B, D, E, F thuộc đường tròn tâm N","keep":1,"why":""},{"code":"P2","text":"NM // AC","keep":1,"why":""},{"code":"N4","text":"NM là trung trực của DF, BE","keep":1,"why":""},{"code":"S1","text":"ý b: ∆ADB ∽ ∆ACK","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"ABDF nội tiếp ⇒ ∠DFK = ∠ABD","ld":"∠AFB = ∠ADB = 90°; góc ngoài bằng góc trong đối","codes":["N1","N3"]},{"cm":"∠ABD = ∠AKC = ∠FKC ⇒ ∠DFK = ∠FKC ⇒ DF // CK","ld":"Cùng chắn cung AC; so le trong","codes":["G1","G5"]},{"cm":"DF ⊥ AC; BE ⊥ AC","ld":"CK ⊥ AC (∠ACK chắn nửa đường tròn)","codes":["G2"]},{"cm":"A, B, D, E, F cùng thuộc đường tròn tâm N (N là trung điểm AB)","ld":"∠ADB = ∠AEB = ∠AFB = 90°","codes":["N1"]},{"cm":"NM // AC ⇒ NM ⊥ DF, NM ⊥ BE","ld":"NM là đường trung bình của ∆ABC; từ 3","codes":["P2"]},{"cm":"NM là phân giác của ∠DMF và của ∠BME","ld":"Đường qua tâm vuông góc với dây là trung trực của dây","codes":["N4"]},{"cm":"∠NMF = ∠NMD = ∠NMB = ∠NME","ld":"Từ 6; tia MD trùng tia MB (D nằm giữa B và M)","codes":[]},{"cm":"Tia MF trùng tia ME ⇒ E, F, M thẳng hàng","ld":"E, F cùng phía đối với NM","codes":["K1"]}]},{"boost":["B7"],"id":"3.4","ch":3,"truong":"Amsterdam","ky":"giữa HKII","de":["Cho tam giác nhọn ABC (AB < AC), nội tiếp đường tròn (O). Ba đường cao AD, BE, CF của tam giác ABC đồng quy tại H. Gọi M là trung điểm cạnh BC.","a) Chứng minh tứ giác AEHF là tứ giác nội tiếp.","b) Đường tròn ngoại tiếp tứ giác AEHF cắt đường tròn (O) tại điểm thứ hai là G khác A và cắt đường thẳng BG tại T khác G. Chứng minh AE.AC = AH.AD và tính số đo góc AGM.","c) Chứng minh ba điểm T, F, D là ba điểm thẳng hàng."],"yl":"c","yc":"Chứng minh ba điểm T, F, D là ba điểm thẳng hàng.","kl":"T, F, D thẳng hàng","hinh":"img/b3.4.png","huong":"∠BTF = ∠BTD (hai tia TF, TD trùng nhau).","giu":"G, T thuộc đường tròn đường kính AH (ý a, b).","noi":"∆BTF ∽ ∆BAG và ∆BTD ∽ ∆BCG (chung đỉnh B).","nhin":"Kể các cặp tam giác đồng dạng chung đỉnh B mà em đã dùng. Cặp nào ghép “theo cột”?","nhinDap":"∆BTF ∽ ∆BAG, ∆BFD ∽ ∆BCA, ∆BTD ∽ ∆BCG. Cặp ∆BTD ∽ ∆BCG suy ra từ BT.BG = BD.BC.","deep":{"huong":[{"ten":"Hai góc đối đỉnh tại F (theo vị trí trên hình)","kq":"duoc","y":["∠AFT + ∠AGT = 180° (AFTG nội tiếp); ∠AGT = ∠AGB = 180° − ∠ACB (AGBC nội tiếp) ⇒ ∠AFT = ∠ACB.","∠BFD = ∠ACB (AFDC nội tiếp) ⇒ ∠AFT = ∠BFD, hai góc ở vị trí đối đỉnh ⇒ T, F, D thẳng hàng."]},{"ten":"Hai tia trùng nhau, hai cặp tam giác chung đỉnh B","kq":"duoc","y":["∆BTF ∽ ∆BAG ⇒ BF.BA = BT.BG; ∆BFD ∽ ∆BCA ⇒ BF.BA = BD.BC.","BT.BG = BD.BC ⇒ ∆BTD ∽ ∆BCG ⇒ ∠BTD = ∠BCG = ∠BAG = ∠BTF."]}],"binh":["Hướng 1 nhanh nhưng dễ sai khi cộng, trừ góc trên đường tròn (Chương 8). Hướng 2 dùng ý tưởng của bài toán phụ 7: hai cặp tam giác chung đỉnh B được nối với nhau qua tích BF.BA."]},"loai":"sector","gt":["∆ABC nhọn (AB < AC) nội tiếp (O); đường cao AD, BE, CF cắt nhau tại H","Đường tròn ngoại tiếp AEHF cắt (O) tại G, cắt BG tại T","M là trung điểm BC"],"inputs":[{"code":"N3, S1","text":"∆BTF ∽ ∆BAG: BF.BA = BT.BG","keep":1,"why":""},{"code":"N1, S1","text":"∆BFD ∽ ∆BCA: BF.BA = BD.BC","keep":1,"why":""},{"code":"S2, S1","text":"∆BTD ∽ ∆BCG","keep":1,"why":""},{"code":"G1","text":"∠BAG = ∠BCG","keep":1,"why":""},{"code":"V1","text":"ý b: AE.AC = AH.AD; ∠AGM","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∠BTF = ∠BAG ⇒ ∆BTF ∽ ∆BAG ⇒ BF.BA = BT.BG","ld":"AGTF nội tiếp: góc ngoài bằng góc trong đối; ∠B chung","codes":["N3","S1"]},{"cm":"AFDC nội tiếp ⇒ ∆BFD ∽ ∆BCA ⇒ BF.BA = BD.BC","ld":"∠AFC = ∠ADC = 90°","codes":["N1","S1"]},{"cm":"BT.BG = BD.BC ⇒ BT/BC = BD/BG","ld":"Từ 1 và 2","codes":["S2"]},{"cm":"∆BTD ∽ ∆BCG ⇒ ∠BTD = ∠BCG","ld":"∠B chung; từ 3 (c.g.c)","codes":["S1"]},{"cm":"∠BAG = ∠BCG ⇒ ∠BTF = ∠BTD","ld":"Cùng chắn cung BG; từ 1 và 4","codes":["G1"]},{"cm":"Tia TF trùng tia TD ⇒ T, F, D thẳng hàng","ld":"F, D cùng phía đối với BG","codes":["K1"]}]},{"boost":["B7"],"id":"3.5","ch":3,"truong":"Phúc Đồng","ky":"cuối HKII","de":["Cho ∆ABC có ba góc nhọn và đường cao BE. Gọi H, K lần lượt là chân đường vuông góc kẻ từ điểm E đến AB, BC.","a) Chứng minh tứ giác BHEK nội tiếp.","b) Chứng minh BH.BA = BK.BC.","c) Gọi F là chân đường vuông góc kẻ từ điểm C đến đường thẳng AB, I là trung điểm của đoạn thẳng EF. Chứng minh rằng H, I, K thẳng hàng."],"yl":"c","yc":"Gọi F là chân đường vuông góc kẻ từ điểm C đến đường thẳng AB, I là trung điểm của đoạn thẳng EF. Chứng minh rằng H, I, K thẳng hàng.","kl":"H, I, K thẳng hàng","hinh":"img/b3.5.png","huong":"∠BHK = ∠BHI (hai tia HK, HI trùng nhau).","giu":"BHEK nội tiếp nên ∠BHK = ∠BEK; BH.BA = BK.BC.","noi":"Giống Bài 3.2 (Lê Hồng Phong). Có thể đi ngắn: ∠BHK = ∠BEK = ∠ACB và ∠FHI = ∠HFI = ∠ACB.","nhin":"Ý b của hai bài Lê Hồng Phong và Phúc Đồng khác nhau. Ý b nào giúp ý c nhiều hơn?","nhinDap":"Cả hai ý b đều dẫn tới ∠BHK = ∠ACB; ý b của Lê Hồng Phong nói thẳng ∆BAC ∽ ∆BKH nên dùng nhanh hơn.","deep":{"huong":[{"ten":"Bài toán phụ 7 như Bài 3.2","kq":"duoc","y":["∆EHF ∽ ∆EKC ⇒ ∆EHK ∽ ∆EFC ⇒ ∠EHK = ∠EFC = ∠EHI."]},{"ten":"Góc tại H qua tứ giác nội tiếp","kq":"duoc","y":["∠BHK = ∠BEK = ∠ACB; ∠FHI = ∠ACB ⇒ ∠BHK = ∠BHI ⇒ tia HK trùng tia HI."]}],"binh":["Hai đề khác trường cho cùng một hình: nhận ra “bài này giống bài nào” là bước Nhìn lại có giá trị nhất. Khi đã có kinh nghiệm, hướng ngắn tự hiện ra."]},"loai":"sector","gt":["∆ABC nhọn, đường cao BE","EH ⊥ AB, EK ⊥ BC","CF ⊥ AB; I là trung điểm EF"],"inputs":[{"code":"N3, G4","text":"ý a: ∠BHK = ∠BEK = ∠ACB","keep":1,"why":""},{"code":"N1, N3","text":"∠AFE = ∠ACB","keep":1,"why":""},{"code":"V2, G6","text":"∠FHI = ∠HFI = ∠ACB","keep":1,"why":""},{"code":"K1","text":"hai tia HK, HI trùng nhau","keep":1,"why":""},{"code":"S2","text":"ý b: BH.BA = BK.BC","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∠BHK = ∠BEK = ∠ACB","ld":"BHEK nội tiếp (ý a); cùng phụ ∠EBC","codes":["N3","G4"]},{"cm":"∠AFE = ∠ACB","ld":"BFEC nội tiếp (∠BFC = ∠BEC = 90°)","codes":["N1","N3"]},{"cm":"∠HFE = ∠AFE; tia HF trùng tia HB","ld":"H nằm giữa A và F; F nằm giữa H và B","codes":[]},{"cm":"IH = IF ⇒ ∠FHI = ∠HFI = ∠HFE = ∠ACB","ld":"HI là trung tuyến ứng với cạnh huyền của ∆EHF","codes":["V2","G6"]},{"cm":"∠BHK = ∠BHI ⇒ H, I, K thẳng hàng","ld":"Từ 1, 3, 4; K, I cùng phía đối với AB","codes":["K1"]}]},{"boost":[],"id":"3.6","ch":3,"truong":"Thăng Long","ky":"cuối HKII","de":["Cho đường tròn (O; R) và dây BC cố định không đi qua tâm O. Gọi A là một điểm bất kì trên cung lớn BC (A khác B và C) sao cho tam giác ABC nhọn (AB < AC). Kẻ các đường cao AD, BE của tam giác ABC.","a) Chứng minh tứ giác AEDB nội tiếp đường tròn.","b) Kẻ đường kính AK của đường tròn tâm O. Gọi F là hình chiếu của điểm B trên AK. Chứng minh rằng AB.AC = AK.AD và DF vuông góc với AC.","c) Gọi M là trung điểm của BC. Chứng minh E, F, M thẳng hàng."],"yl":"c","yc":"Gọi M là trung điểm của BC. Chứng minh E, F, M thẳng hàng.","kl":"E, F, M thẳng hàng","hinh":"img/b3.6.png","huong":"Tia MF trùng tia ME.","giu":"DF ⊥ AC (ý b); tứ giác AEDB nội tiếp.","noi":"DF ⊥ AC và BE ⊥ AC nên DF // BE: hai dây của đường tròn đường kính AB. NM // AC là trục đối xứng chung của hai dây.","nhin":"Vẽ hình Cầu Diễn (Bài 3.3) bên cạnh. Hai bài khác nhau ở chỗ nào?","nhinDap":"Hai đề gần như trùng nhau: Thăng Long cho sẵn DF ⊥ AC ở ý b; Cầu Diễn yêu cầu chứng minh DF // CK ở ý c.","deep":{"huong":[{"ten":"Góc bẹt tại F","kq":"tac","y":["Như Bài 3.3: M không nằm trên đường tròn nào qua F nên góc tại F khó tính."]},{"ten":"Trục đối xứng chung","kq":"duoc","y":["NM ⊥ DF, NM ⊥ BE ⇒ NM là trung trực của hai dây ⇒ ∠NMF = ∠NMD = ∠NMB = ∠NME ⇒ tia MF trùng tia ME."]}],"binh":["Đề Thăng Long cho sẵn DF ⊥ AC ở ý b; đề Cầu Diễn (Bài 3.3) bắt chứng minh DF // CK trước. Cùng một ý c, mức hỗ trợ khác nhau."]},"loai":"sector","gt":["(O; R), dây BC; A thuộc cung lớn, ∆ABC nhọn (AB < AC)","Đường cao AD, BE; AK là đường kính; BF ⊥ AK","M là trung điểm BC"],"inputs":[{"code":"N1","text":"A, B, D, E, F thuộc đường tròn tâm N","keep":1,"why":""},{"code":"P3","text":"ý b: DF ⊥ AC ⇒ DF // BE","keep":1,"why":""},{"code":"P2","text":"NM // AC","keep":1,"why":""},{"code":"N4","text":"NM là trục đối xứng chung của DF, BE","keep":1,"why":""},{"code":"S2","text":"ý b: AB.AC = AK.AD","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"A, B, D, E, F cùng thuộc đường tròn tâm N","ld":"∠ADB = ∠AEB = ∠AFB = 90°; N là trung điểm AB","codes":["N1"]},{"cm":"NM // AC ⇒ NM ⊥ DF, NM ⊥ BE","ld":"Đường trung bình của ∆ABC; DF ⊥ AC (ý b), BE ⊥ AC","codes":["P2"]},{"cm":"NM là phân giác của ∠DMF và của ∠BME","ld":"Đường qua tâm N vuông góc với dây là trung trực","codes":["N4"]},{"cm":"∠NMF = ∠NMD = ∠NMB = ∠NME","ld":"Từ 3; tia MD trùng tia MB","codes":[]},{"cm":"Tia MF trùng tia ME ⇒ E, F, M thẳng hàng","ld":"E, F cùng phía đối với NM","codes":["K1"]}]},{"boost":[],"id":"3.7","ch":3,"truong":"Đại Áng","ky":"cuối HKII","de":["Cho tam giác ABC nhọn nội tiếp đường tròn (O) (AB < AC). Các đường cao AD, BE, CF của tam giác ABC cắt nhau tại điểm H.","a) Chứng minh tứ giác ABDE nội tiếp.","b) Kẻ đường kính AT của đường tròn (O). Chứng minh rằng AB.AC = AD.AT và ∠DEF = ∠COT.","c) Kẻ CI vuông góc với AT tại I. Gọi M là trung điểm của BC. Chứng minh ba điểm F, I, M thẳng hàng."],"yl":"c","yc":"Kẻ CI vuông góc với AT tại I. Gọi M là trung điểm của BC. Chứng minh ba điểm F, I, M thẳng hàng.","kl":"F, I, M thẳng hàng","hinh":"img/b3.7.png","huong":"∠OIM = ∠AIF (hai tia IM, IF trùng nhau).","giu":"AB.AC = AD.AT; ∠DEF = ∠COT. Ý c dùng thêm các tứ giác nội tiếp.","noi":"Đổi vai B, C thì được Bài 3.3 / 3.6: F (chân đường cao từ C) và I (hình chiếu của C trên AT) đóng vai E và F.","nhin":"Viết lại đề Cầu Diễn rồi đổi tên B ↔ C, D ↔ … Em được đề nào?","nhinDap":"Đổi B ↔ C trong đề Cầu Diễn: chân đường cao từ B thành chân đường cao từ C (F), hình chiếu của B trên AK thành hình chiếu của C trên AK (I). Kết luận “E, F, M thẳng hàng” thành “F, I, M thẳng hàng”.","deep":{"huong":[{"ten":"Đổi vai B, C để về Bài 3.3","kq":"duoc","y":["∠AIC = ∠ADC = ∠AFC = 90° ⇒ A, F, D, I, C cùng thuộc đường tròn tâm N'.","Chứng minh DI ⊥ AB như DF ⊥ AC ở Bài 3.3; N'M // AB ⇒ N'M ⊥ CF, N'M ⊥ DI ⇒ tia MF trùng tia MI."]},{"ten":"Hai tứ giác nội tiếp và một cặp tam giác đồng dạng","kq":"duoc","y":["OMIC nội tiếp ⇒ ∠OIM = ∠OCM; AFIC nội tiếp ⇒ ∠AIF = ∠ACF; ∆OMC ∽ ∆AFC ⇒ ∠OCM = ∠ACF.","⇒ ∠OIM = ∠AIF ⇒ tia IM trùng tia IF."]}],"binh":["Câu hỏi “bài này giống bài nào, đổi vai điểm nào?” cho lời giải gần như có sẵn. Đây là ví dụ rõ nhất cho Bước 4 – Nhìn lại."]},"loai":"sector","gt":["∆ABC nhọn nội tiếp (O) (AB < AC); đường cao AD, BE, CF cắt nhau tại H","AT là đường kính; CI ⊥ AT","M là trung điểm BC"],"inputs":[{"code":"N4, N1","text":"OMIC nội tiếp: ∠OIM = ∠OCM","keep":1,"why":""},{"code":"N1, G1","text":"AFIC nội tiếp: ∠AIF = ∠ACF","keep":1,"why":""},{"code":"G6, G1","text":"∠MOC = ∠BAC","keep":1,"why":""},{"code":"S3","text":"∆OMC ∽ ∆AFC","keep":1,"why":""},{"code":"S2","text":"ý b","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"OM ⊥ BC ⇒ OMIC nội tiếp ⇒ ∠OIM = ∠OCM","ld":"M là trung điểm dây BC; ∠OMC = ∠OIC = 90°; cùng chắn cung OM","codes":["N4","N1","G1"]},{"cm":"AFIC nội tiếp ⇒ ∠AIF = ∠ACF","ld":"∠AFC = ∠AIC = 90°; cùng chắn cung AF","codes":["N1","G1"]},{"cm":"∠MOC = ½∠BOC = ∠BAC","ld":"∆OBC cân, OM là phân giác; góc ở tâm","codes":["G6","G1"]},{"cm":"∆OMC ∽ ∆AFC ⇒ ∠OCM = ∠ACF","ld":"∠OMC = ∠AFC = 90°; từ 3 (g.g)","codes":["S3"]},{"cm":"∠OIM = ∠AIF","ld":"Từ 1, 2, 4","codes":[]},{"cm":"Tia IM trùng tia IF ⇒ F, I, M thẳng hàng","ld":"O nằm giữa A và I nên tia IO trùng tia IA; F, M cùng phía đối với AT","codes":["K1"]}]},{"boost":["B6"],"id":"3.8","ch":3,"truong":"Ngô Gia Tự – đề 2","ky":"cuối HKII","de":["Cho tam giác ABC có ba góc nhọn nội tiếp đường tròn tâm O bán kính R và AH là đường cao của tam giác ABC. Gọi M, N lần lượt là chân đường vuông góc kẻ từ H đến AB và AC.","a) Chứng minh tứ giác AMHN nội tiếp đường tròn.","b) Chứng minh ∠ABC = ∠ANM.","c) Cho biết AH = R√2. Chứng minh M, O, N thẳng hàng."],"yl":"c","yc":"Cho biết AH = R√2. Chứng minh M, O, N thẳng hàng.","kl":"AH = R√2 thì M, O, N thẳng hàng","hinh":"img/b3.8.png","huong":"Khoảng cách từ A đến MN bằng R (= AO) và AO ⊥ MN.","giu":"∠ANM = ∠ABC (ý b), nên ∆AMN ∽ ∆ACB.","noi":"Tỉ số đồng dạng k = AN/AB = AH²/(AB.AC) = AH/(2R). Đường cao từ A của ∆AMN bằng k.AH = AH²/(2R).","nhin":"Nếu AH ≠ R√2 thì M, O, N còn thẳng hàng không? Điều kiện đó dùng ở bước nào?","nhinDap":"Không: khoảng cách từ O đến MN bằng |AH²/(2R) − R|, chỉ bằng 0 khi AH = R√2. Điều kiện dùng ở bước cuối.","deep":{"huong":[{"ten":"Góc bẹt tại O","kq":"tac","y":["Cần ∠MOA + ∠AON = 180°; không có góc nào tại O tính được theo M, N."]},{"ten":"Lượng giác","kq":"duoc","y":["AP = AN.sin∠ANM = AN.sin B; AN = AH²/AC; sin B = AH/AB ⇒ AP = AH³/(AB.AC).","Kẻ đường kính AK: AB.AC = AH.AK = 2R.AH ⇒ AP = AH²/(2R) = R khi AH = R√2."]},{"ten":"Bài toán phụ 6 mở rộng (đường cao tương ứng)","kq":"duoc","y":["Tỉ số đồng dạng k = AN/AB = AH/(2R); đường cao tương ứng AP = k.AH = AH²/(2R) = R."]}],"binh":["Hướng 2 và 3 thực chất là một; bài toán phụ 6 mở rộng cho cách nói gọn: “đường cao tương ứng tỉ lệ với tỉ số đồng dạng”. Điều kiện AH = R√2 là tín hiệu phải tính một độ dài, không phải tìm góc."]},"loai":"sector","gt":["∆ABC nhọn nội tiếp (O; R); đường cao AH","HM ⊥ AB, HN ⊥ AC","AH = R√2"],"inputs":[{"code":"G1, G6","text":"AO ⊥ MN tại P","keep":1,"why":""},{"code":"S1","text":"ý b: ∆ANM ∽ ∆ABC, tỉ số k","keep":1,"why":""},{"code":"V1","text":"k = AH²/(AB.AC)","keep":1,"why":""},{"code":"S3","text":"AB.AC = 2R.AH ⇒ k = AH/(2R)","keep":1,"why":""},{"code":"B6","text":"AP = k.AH = AH²/(2R)","keep":1,"why":""}],"steps":[{"cm":"∠OAC = 90° − ∠ABC","ld":"∆OAC cân tại O, ∠AOC = 2∠ABC","codes":["G6","G1"]},{"cm":"Gọi P = AO ∩ MN: ∠PAN + ∠ANP = (90° − ∠ABC) + ∠ABC = 90° ⇒ AO ⊥ MN tại P","ld":"Ý b: ∠ANM = ∠ABC","codes":["G7"]},{"cm":"∆ANM ∽ ∆ABC, tỉ số k = AN/AB = AH²/(AB.AC)","ld":"Ý b (g.g); AN.AC = AH²","codes":["S1","V1"]},{"cm":"AB.AC = AH.AK = 2R.AH ⇒ k = AH/(2R)","ld":"AK là đường kính: ∆ABH ∽ ∆AKC","codes":["S3"]},{"cm":"AP = k.AH = AH²/(2R)","ld":"AP, AH là hai đường cao tương ứng","codes":["B6"]},{"cm":"AH = R√2 ⇒ AP = R = AO ⇒ P trùng O ⇒ M, O, N thẳng hàng","ld":"P, O cùng nằm trên tia AO","codes":["K1"]}]},{"boost":["B6"],"id":"3.9","ch":3,"truong":"Trưng Vương","ky":"cuối HKII","de":["Cho tam giác ABC nhọn không cân (AB < AC) nội tiếp (O). Đường thẳng qua O vuông góc với BC tại M, cắt cung BC lớn, cung BC nhỏ của đường tròn (O) lần lượt tại S và K. Gọi D là giao điểm của AK và BC.","a) Chứng minh tứ giác ADMS là tứ giác nội tiếp.","b) Tia phân giác của ∠AOC cắt đường thẳng AS tại Q. Chứng minh KB² = KD.KA và tam giác AOQ đồng dạng với tam giác DBA.","c) Gọi T là trung điểm của đoạn thẳng AD. Chứng minh CT vuông góc với QK."],"yl":"c","yc":"Gọi T là trung điểm của đoạn thẳng AD. Chứng minh CT vuông góc với QK.","kl":"CT ⊥ QK","hinh":"img/b3.9.png","huong":"∠DTC = ∠AQK, rồi dùng ∆AQK vuông tại A.","giu":"∆AOQ ∽ ∆DBA nên ∠AQO = ∠DAB = ∠KAC.","noi":"∆ADC ∽ ∆QSO; T là trung điểm AD, O là trung điểm SK: chia đôi AD và nhân đôi SO được ∆DTC ∽ ∆SQK.","nhin":"Xếp bài này vào chuỗi “đổi cạnh nhờ trung điểm”: bài nào đứng trước, bài nào đứng sau?","nhinDap":"Chuỗi “đổi cạnh nhờ trung điểm”: 2.2 → 2.3 → 5.1 → 3.9 → 3.10 → 5.10. Bài đứng trước là 5.1, bài đứng sau là 3.10.","deep":{"huong":[{"ten":"Tính góc giữa CT và QK trực tiếp","kq":"tac","y":["T là trung điểm AD, không có đường tròn hay đường song song nào qua T; góc tại T không tính được trực tiếp."]},{"ten":"Nhân đôi – chia đôi","kq":"duoc","y":["∆ADC ∽ ∆QSO ⇒ DA/DC = SQ/SO.","Chia đôi DA (thành DT), nhân đôi SO (thành SK): DT/DC = SQ/SK ⇒ ∆DTC ∽ ∆SQK ⇒ ∠DTC = ∠SQK = ∠AQK ⇒ CT ⊥ QK."]}],"binh":["Hai trung điểm T (của AD) và O (của SK) nằm ở hai tam giác khác nhau là dấu hiệu rõ của dạng nhân đôi – chia đôi. Không có bài toán phụ 6, khó nghĩ ra cặp ∆DTC, ∆SQK."]},"loai":"sector","gt":["∆ABC nhọn (AB < AC) nội tiếp (O)","OM ⊥ BC tại M, cắt (O) tại S (cung lớn), K (cung nhỏ); D = AK ∩ BC","OQ là phân giác ∠AOC, Q ∈ AS; T là trung điểm AD"],"inputs":[{"code":"S1","text":"ý b: ∠AQO = ∠KAC","keep":1,"why":""},{"code":"G7, G1","text":"∠ADC = ∠ABK","keep":1,"why":""},{"code":"N3","text":"∠ABK = ∠QSO","keep":1,"why":""},{"code":"S1","text":"∆ADC ∽ ∆QSO","keep":1,"why":""},{"code":"B6","text":"chia đôi DA, nhân đôi SO: ∆DTC ∽ ∆SQK","keep":1,"why":""},{"code":"G2","text":"∆AQK vuông tại A","keep":1,"why":""},{"code":"S2","text":"ý b: KB² = KD.KA","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∠SQO = ∠AQO = ∠KAC = ∠DAC","ld":"Ý b: ∆AOQ ∽ ∆DBA; AK là phân giác ∠BAC","codes":[]},{"cm":"∠ADC = ∠ABD + ∠BAD = ∠ABC + ∠CBK = ∠ABK","ld":"Góc ngoài của ∆ABD; ∠BAK = ∠CBK (chắn hai cung bằng nhau)","codes":["G7","G1"]},{"cm":"∠ABK = 180° − ∠ACK = 180° − ∠ASK = ∠QSO","ld":"ABKC nội tiếp; ∠ACK = ∠ASK; S nằm giữa A và Q","codes":["N3","G1"]},{"cm":"∆ADC ∽ ∆QSO ⇒ DA/SQ = DC/SO","ld":"Từ 1, 2, 3 (g.g)","codes":["S1"]},{"cm":"DT/DC = DA/(2DC) = SQ/(2SO) = SQ/SK","ld":"T là trung điểm AD, O là trung điểm SK","codes":[]},{"cm":"∆DTC ∽ ∆SQK ⇒ ∠DTC = ∠SQK = ∠AQK","ld":"∠TDC = ∠QSK; từ 5 (c.g.c)","codes":["S1","B6"]},{"cm":"Gọi X = CT ∩ QK: ∠XTK + ∠TKX = ∠AQK + ∠AKQ = 90° ⇒ CT ⊥ QK","ld":"∆AQK vuông tại A (∠SAK chắn nửa đường tròn)","codes":["G2","G7","K3"]}]},{"boost":[],"id":"4.1","ch":4,"truong":"Ngô Gia Tự","ky":"cuối HKI","de":["Cho đường tròn (O; R). Từ điểm A nằm ngoài đường tròn kẻ các tiếp tuyến AB, AC với đường tròn (B, C là các tiếp điểm). Gọi H là giao điểm của OA và BC.","a) Chứng minh các điểm A, B, C, O cùng thuộc một đường tròn.","b) Chứng minh OA ⊥ BC và OH.OA = R².","c) Gọi I là giao điểm của đoạn thẳng OA với đường tròn (O; R). Chứng minh OA.IH = OB.IA."],"yl":"c","yc":"Gọi I là giao điểm của đoạn thẳng OA với đường tròn (O; R). Chứng minh OA.IH = OB.IA.","kl":"OA.IH = OB.IA","hinh":"img/b4.1.png","huong":"IH/IA = OB/OA.","giu":"OA ⊥ BC tại H; OH.OA = R².","noi":"∆OBI cân tại O cho BI là tia phân giác của ∠ABH.","nhin":"Gọi I' là giao điểm thứ hai của đường thẳng OA với (O). Hệ thức tương tự với I' là gì?","nhinDap":"Với I' là giao điểm còn lại: BI' ⊥ BI nên BI' là phân giác ngoài của ∆ABH, vẫn có I'H/I'A = BH/BA = OB/OA, tức OA.I'H = OB.I'A.","deep":{"huong":[{"ten":"Tính toán bằng OH.OA = R²","kq":"duoc","y":["OH = R²/OA ⇒ IH = R − R²/OA = R(OA − R)/OA; IA = OA − R.","IH/IA = R/OA = OB/OA."]},{"ten":"Tia phân giác","kq":"duoc","y":["∆OBI cân ⇒ ∠ABI = 90° − ∠OBI = 90° − ∠OIB = ∠IBH ⇒ BI là phân giác của ∠ABH ⇒ IH/IA = BH/BA.","∆AHB ∽ ∆ABO ⇒ BH/BA = OB/OA."]}],"binh":["Ở bài này hướng tính toán (dùng ngay OH.OA = R²) ngắn hơn. Không phải lúc nào cũng cần một công cụ “đẹp”; điều quan trọng là đi ngược để biết cần gì (IH, IA theo R và OA) rồi chọn kết quả ý b đúng chỗ."]},"loai":"sector","gt":["(O; R), A nằm ngoài; AB, AC là tiếp tuyến","H = OA ∩ BC","I là giao điểm của đoạn OA với (O)"],"inputs":[{"code":"G6","text":"∠OBI = ∠OIB","keep":1,"why":""},{"code":"G4","text":"BI là phân giác ∠ABH","keep":1,"why":""},{"code":"P5","text":"IH/IA = BH/BA","keep":1,"why":""},{"code":"S3","text":"BH/BA = OB/OA","keep":1,"why":""},{"code":"V1","text":"ý b: OH.OA = R² ⇒ I nằm giữa H và A","keep":1,"why":""}],"steps":[{"cm":"OH = R²/OA < R = OI ⇒ I nằm giữa H và A","ld":"Ý b: OH.OA = R²","codes":["V1"]},{"cm":"∠OBI = ∠OIB","ld":"∆OBI cân tại O","codes":["G6"]},{"cm":"∠ABI = 90° − ∠OBI = 90° − ∠OIB = ∠IBH","ld":"∠ABO = 90°; ∆BHI vuông tại H","codes":["T1","G7","G4"]},{"cm":"IH/IA = BH/BA","ld":"BI là phân giác của ∠ABH","codes":["P5"]},{"cm":"∆AHB ∽ ∆ABO ⇒ BH/BA = OB/OA","ld":"∠AHB = ∠ABO = 90°, ∠BAO chung","codes":["S3"]},{"cm":"IH/IA = OB/OA ⇒ OA.IH = OB.IA","ld":"Từ 4 và 5","codes":["K6"]}]},{"boost":[],"id":"4.2","ch":4,"truong":"Phúc Đồng","ky":"cuối HKI","de":["Cho đường tròn (O; R) và điểm A nằm ngoài đường tròn (O). Từ A vẽ hai tiếp tuyến AB và AC của đường tròn (O) (B, C là hai tiếp điểm). Gọi H là giao điểm của OA và BC. Từ B vẽ đường kính BD của (O), đường thẳng AD cắt (O) tại E (E khác D).","a) Chứng minh bốn điểm A, B, C, O cùng thuộc một đường tròn. Xác định tâm và bán kính của đường tròn đó.","b) Chứng minh rằng OA ⊥ BC tại H và OA // CD.","c) Khi OA = BD, hãy tính theo R diện tích hình quạt giới hạn bởi bán kính OC, OD và cung nhỏ CD."],"yl":"c","yc":"Khi OA = BD, hãy tính theo R diện tích hình quạt giới hạn bởi bán kính OC, OD và cung nhỏ CD.","kl":"Diện tích hình quạt khi OA = BD","hinh":"img/b4.2.png","huong":"Tính ∠COD (số đo cung nhỏ CD) rồi dùng công thức S = πR²n/360.","giu":"OA ⊥ BC và OA // CD; OA là tia phân giác của ∠BOC.","noi":"cos∠AOB = OB/OA = 1/2 nên ∠AOB = 60°.","nhin":"Nếu OA = 3R thay cho OA = 2R thì có tính được ∠COD không? Khi nào được góc đặc biệt?","nhinDap":"cos∠AOB = 1/k nên ∠COD = 180° − 2∠AOB. Góc đặc biệt khi k = 2 (∠COD = 60°) hoặc k = √2 (∠COD = 90°).","deep":{"huong":[{"ten":"Qua góc ∠BOC","kq":"duoc","y":["∠AOB = 60° ⇒ ∠BOC = 120° ⇒ ∠COD = 60°."]},{"ten":"Qua OA // CD","kq":"duoc","y":["∠ODC = ∠AOB = 60° (đồng vị) ⇒ ∆OCD cân có một góc 60° ⇒ đều ⇒ ∠COD = 60°."]}],"binh":["Ý tính toán cũng có “ý trước làm bàn đạp”: kết quả OA // CD của ý b cho ngay một cách tính góc thứ hai."]},"loai":"sector","gt":["(O; R), A nằm ngoài; AB, AC là tiếp tuyến; H = OA ∩ BC","BD là đường kính; AD cắt (O) tại E","OA = BD = 2R"],"inputs":[{"code":"V3","text":"∠AOB = 60°","keep":1,"why":""},{"code":"T2","text":"∠BOC = 120°","keep":1,"why":""},{"code":"G7","text":"∠COD = 60°","keep":1,"why":""},{"code":"K6","text":"công thức diện tích hình quạt","keep":1,"why":""},{"code":"P3","text":"ý b: OA // CD","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"cos∠AOB = OB/OA = R/(2R) = 1/2 ⇒ ∠AOB = 60°","ld":"∆ABO vuông tại B","codes":["T1","V3"]},{"cm":"∠BOC = 2∠AOB = 120°","ld":"OA là phân giác của ∠BOC","codes":["T2"]},{"cm":"∠COD = 180° − 120° = 60°","ld":"Hai góc kề bù (B, O, D thẳng hàng)","codes":[]},{"cm":"S = πR² . 60/360 = πR²/6","ld":"Công thức diện tích hình quạt","codes":[]}]},{"boost":[],"id":"4.3","ch":4,"truong":"Giang Biên","ky":"cuối HKI","de":["Cho đường tròn (O) và điểm A nằm ngoài đường tròn. Vẽ các tiếp tuyến AB, AC với đường tròn (O) (B, C là các tiếp điểm). Gọi H là giao điểm của OA và BC.","a) Chứng minh bốn điểm A, B, C, O cùng thuộc một đường tròn.","b) Chứng minh OA là trung trực của BC và OH.OA = R².","c) Lấy điểm D trên (O) sao cho BD = BC. Trên tia BA, lấy điểm E sao cho BE = DC. Chứng minh OA, BC và DE đồng quy."],"yl":"c","yc":"Lấy điểm D trên (O) sao cho BD = BC. Trên tia BA, lấy điểm E sao cho BE = DC. Chứng minh OA, BC và DE đồng quy.","kl":"OA, BC, DE đồng quy","hinh":"img/b4.3.png","huong":"DE đi qua H (H = OA ∩ BC).","giu":"OA là đường trung trực của BC; H là trung điểm BC.","noi":"DE cần đi qua H. BECD là hình bình hành (BE // DC, BE = DC) nên DE đi qua trung điểm H của BC.","nhin":"Tứ giác BECD là hình gì? Em đã dùng tính chất đường chéo nào?","nhinDap":"BECD là hình bình hành; dùng tính chất hai đường chéo cắt nhau tại trung điểm mỗi đường.","deep":{"huong":[{"ten":"Chứng minh D, H, E thẳng hàng bằng góc","kq":"tac","y":["Cần ∠DHB + ∠BHE = 180°; E chỉ được cho bằng độ dài BE = DC, không có góc nào tại E."]},{"ten":"Hình bình hành","kq":"duoc","y":["∆OBD = ∆OBC ⇒ BO là phân giác của ∠DBC ⇒ BO ⊥ DC ⇒ AB // DC.","BE // DC, BE = DC ⇒ BECD là hình bình hành ⇒ DE đi qua trung điểm H của BC."]}],"binh":["Đồng quy được đổi thành “đi qua một điểm đã biết” (điểm trùng), rồi lại đổi thành “trung điểm” (đường chéo hình bình hành). Hai lần đổi kết luận đưa bài khó về bài quen (Chương 0, §6)."]},"loai":"sector","gt":["(O), A nằm ngoài; AB, AC là tiếp tuyến; H = OA ∩ BC","D ∈ (O), BD = BC","E ∈ tia BA, BE = DC"],"inputs":[{"code":"S4","text":"∆OBD = ∆OBC","keep":1,"why":""},{"code":"G6","text":"BO ⊥ DC","keep":1,"why":""},{"code":"T1, P3","text":"AB // DC","keep":1,"why":""},{"code":"P4","text":"BECD là hình bình hành","keep":1,"why":""},{"code":"T2","text":"ý b: H là trung điểm BC","keep":1,"why":""},{"code":"K5","text":"DE đi qua H","keep":1,"why":""}],"steps":[{"cm":"∆OBD = ∆OBC ⇒ ∠OBD = ∠OBC","ld":"OD = OC, BD = BC, OB chung (c.c.c)","codes":["S4"]},{"cm":"BO ⊥ DC","ld":"∆BDC cân tại B, BO là phân giác","codes":["G6"]},{"cm":"AB // DC","ld":"AB ⊥ BO (tiếp tuyến)","codes":["T1","P3"]},{"cm":"BECD là hình bình hành","ld":"BE // DC, BE = DC","codes":["P4"]},{"cm":"DE đi qua trung điểm H của BC","ld":"Hai đường chéo cắt nhau tại trung điểm mỗi đường; ý b","codes":["P4","T2"]},{"cm":"OA, BC, DE cùng đi qua H","ld":"","codes":["K5"]}]},{"boost":["B7"],"id":"4.6","ch":4,"truong":"Đức Giang","ky":"cuối HKI","de":["Cho đường tròn tâm O, đường kính AB = 2R. Trên tia đối của tia AB lấy điểm H (H khác A), kẻ đường thẳng d vuông góc với AB tại H; trên d lấy điểm E sao cho HE > R; vẽ tiếp tuyến EM, EN với (O) tại M, N (N, H ở cùng một nửa mặt phẳng bờ là đường thẳng OA), dây MN cắt OH, OE thứ tự ở K, I.","a) Chứng minh năm điểm E, H, N, M, O cùng nằm trên một đường tròn.","b) Chứng minh OE ⊥ MN và OI.OE = OK.OH.","c) Chứng minh MN² = 4.OI.IE và tìm vị trí của điểm E trên đường thẳng d để diện tích của tam giác OIK đạt giá trị lớn nhất."],"yl":"c","yc":"Chứng minh MN² = 4.OI.IE và tìm vị trí của điểm E trên đường thẳng d để diện tích của tam giác OIK đạt giá trị lớn nhất.","kl":"MN² = 4.OI.IE; S(OIK) lớn nhất","hinh":"img/b4.6.png","huong":"S(OIK) = OI.IK/2 ≤ OK²/4.","giu":"OE ⊥ MN; OI.OE = OK.OH.","noi":"K cố định vì OK.OH = R² không đổi.","nhin":"Đo trên hình: khi E chạy, điểm nào đứng yên? Điều đó gợi ý gì cho bài cực trị?","nhinDap":"K đứng yên (OK = R²/OH). Gợi ý: ∆OIK vuông tại I có cạnh huyền OK cố định nên I chạy trên đường tròn đường kính OK.","deep":{"huong":[{"ten":"Bất đẳng thức đại số","kq":"duoc","y":["S = OI.IK/2 ≤ (OI² + IK²)/4 = OK²/4; dấu “=” khi OI = IK."]},{"ten":"Hình học: I nằm trên đường tròn đường kính OK","kq":"duoc","y":["∠OIK = 90° ⇒ I thuộc đường tròn đường kính OK. Khoảng cách từ I đến OK không vượt quá bán kính OK/2 ⇒ S ≤ OK.(OK/2)/2 = OK²/4.","Dấu “=” khi I là điểm chính giữa cung, tức ∆OIK vuông cân ⇒ HE = OH."]}],"binh":["Bài cực trị cần trả lời trước câu hỏi “cái gì cố định?”. Kết quả ý b chính là câu trả lời: OK.OH = R² cho K cố định. Ý bổ sung (bài toán phụ 7: ∆OIH ∽ ∆OKE) là một cách khác để có các góc bằng nhau trong hình."]},"loai":"sector","gt":["(O) đường kính AB = 2R; H ∈ tia đối tia AB; d ⊥ AB tại H","E ∈ d, HE > R; EM, EN là tiếp tuyến","MN cắt OH, OE tại K, I"],"inputs":[{"code":"N4","text":"I là trung điểm MN","keep":1,"why":""},{"code":"V1","text":"MI² = OI.IE; OI.OE = R²","keep":1,"why":""},{"code":"S2","text":"ý b: OK.OH = R² ⇒ K cố định","keep":1,"why":""},{"code":"V4","text":"S = OI.IK/2 ≤ OK²/4","keep":1,"why":""},{"code":"B7","text":"ý bổ sung","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"I là trung điểm MN ⇒ MN² = 4MI²","ld":"OE là trung trực của MN","codes":["T2","N4"]},{"cm":"MI² = OI.IE ⇒ MN² = 4.OI.IE","ld":"∆OME vuông tại M, đường cao MI","codes":["V1"]},{"cm":"OI.OE = R² = OK.OH ⇒ OK = R²/OH không đổi","ld":"Hệ thức lượng; ý b","codes":["V1","S2"]},{"cm":"S(OIK) = OI.IK/2 ≤ (OI² + IK²)/4 = OK²/4","ld":"∆OIK vuông tại I; (OI − IK)² ≥ 0","codes":["V4"]},{"cm":"Dấu “=” ⇔ OI = IK ⇔ ∠EOH = 45° ⇔ HE = OH","ld":"∆OIK, ∆OHE vuông cân","codes":[]},{"cm":"S(OIK) lớn nhất bằng R⁴/(4OH²) khi HE = OH","ld":"Từ 3, 4, 5","codes":[]}]},{"boost":[],"id":"4.7","ch":4,"truong":"Nghĩa Tân","ky":"giữa HKII","de":["Cho đường tròn (O; R) và một điểm S nằm ngoài đường tròn sao cho SO < 2R. Từ điểm S, vẽ hai tiếp tuyến SA và SB với đường tròn (O) (A, B là các tiếp điểm). Vẽ đường kính BD của đường tròn (O). Gọi E và J lần lượt là giao điểm của đoạn thẳng SD với đường tròn (O) và AB.","a) Chứng minh SAOB là tứ giác nội tiếp.","b) Gọi T là trung điểm của EB. Đường thẳng OT cắt AB tại điểm Q. Chứng minh OT // ED và Q là trung điểm của JB.","c) Qua J vẽ đường thẳng vuông góc với ED cắt BD tại điểm M. Gọi I là giao điểm của EB và SO. Chứng minh I, Q, M thẳng hàng."],"yl":"c","yc":"Qua J vẽ đường thẳng vuông góc với ED cắt BD tại điểm M. Gọi I là giao điểm của EB và SO. Chứng minh I, Q, M thẳng hàng.","kl":"I, Q, M thẳng hàng","hinh":"img/b4.7.png","huong":"IM đi qua trung điểm Q của JB.","giu":"OT // ED; Q là trung điểm của JB (ý b).","noi":"I là trực tâm của ∆SJB. IJMB là hình bình hành.","nhin":"I là trực tâm. So sánh với Hát Môn (Bài 1.6).","nhinDap":"Cả hai bài: một điểm sinh ra từ giao của hai đường hoá ra là trực tâm (∆SJB ở Nghĩa Tân, ∆SBC ở Hát Môn).","deep":{"huong":[{"ten":"Góc bẹt tại Q","kq":"tac","y":["Q chỉ là trung điểm, không có góc nào tại Q liên hệ với I và M."]},{"ten":"Trực tâm rồi hình bình hành","kq":"duoc","y":["BE ⊥ SJ, SO ⊥ JB ⇒ I là trực tâm ∆SJB ⇒ JI ⊥ SB ⇒ JI // BM; JM // BI.","IJMB là hình bình hành ⇒ IM đi qua trung điểm Q của JB."]}],"binh":["I là điểm nhiều vai: giao của EB với SO, đồng thời là trực tâm của ∆SJB. Hỏi “I là gì của tam giác nào?” mở ra lời giải."]},"loai":"sector","gt":["(O; R), S ngoài, SO < 2R; SA, SB là tiếp tuyến; BD là đường kính","E = SD ∩ (O), J = SD ∩ AB; T là trung điểm EB, Q = OT ∩ AB","JM ⊥ ED, M ∈ BD; I = EB ∩ SO"],"inputs":[{"code":"G2","text":"BE ⊥ SJ","keep":1,"why":""},{"code":"T2","text":"SO ⊥ JB","keep":1,"why":""},{"code":"Q1","text":"I là trực tâm ∆SJB","keep":1,"why":""},{"code":"T1, P3","text":"JI // BM; JM // BI","keep":1,"why":""},{"code":"P4","text":"IJMB là hình bình hành","keep":1,"why":""},{"code":"K1","text":"ý b: Q là trung điểm JB","keep":1,"why":""}],"steps":[{"cm":"BE ⊥ SJ","ld":"∠BED = 90° (chắn nửa đường tròn); E, J ∈ SD","codes":["G2"]},{"cm":"SO ⊥ JB","ld":"SO là trung trực của AB","codes":["T2"]},{"cm":"I là trực tâm ∆SJB ⇒ JI ⊥ SB","ld":"Hai đường cao BE, SO cắt nhau tại I","codes":["Q1"]},{"cm":"JI // BM","ld":"BD ⊥ SB (tiếp tuyến)","codes":["T1","P3"]},{"cm":"JM // BI","ld":"JM ⊥ ED, BE ⊥ ED","codes":["P3"]},{"cm":"IJMB là hình bình hành ⇒ IM đi qua trung điểm của JB","ld":"Từ 4 và 5","codes":["P4"]},{"cm":"Q là trung điểm JB ⇒ I, Q, M thẳng hàng","ld":"Ý b","codes":["K1"]}]},{"boost":["B7"],"id":"4.8","ch":4,"truong":"Mai Dịch","ky":"cuối HKII","de":["Cho (O; R) và điểm H cố định nằm ngoài đường tròn. Qua H kẻ một đường thẳng d vuông góc với OH. Từ điểm M nằm trên đường thẳng d (M ≠ H), kẻ tiếp tuyến MA, MB với (O) (A, B là tiếp điểm). Gọi I, K lần lượt là giao điểm của AB với OM, OH.","a) Chứng minh: 4 điểm M, H, O, A cùng thuộc một đường tròn.","b) Chứng minh: ∆OIA ∽ ∆OAM và OH.OK = R².","c) Vẽ đường thẳng đi qua điểm O, vuông góc với OM, cắt MA, MB lần lượt tại P, Q. Tìm vị trí điểm M để diện tích tam giác MPQ nhỏ nhất."],"yl":"c","yc":"Vẽ đường thẳng đi qua điểm O, vuông góc với OM, cắt MA, MB lần lượt tại P, Q. Tìm vị trí điểm M để diện tích tam giác MPQ nhỏ nhất.","kl":"Vị trí M để S(MPQ) nhỏ nhất","hinh":"img/b4.8.png","huong":"Tìm giá trị nhỏ nhất của MA + AP khi MA.AP = R² không đổi.","giu":"OI.OM = R² (∆OIA ∽ ∆OAM); OH.OK = R².","noi":"S(MPQ) = 2S(MOP) = OA.MP = R.MP = R(MA + AP), và MA.AP = OA² = R².","nhin":"So sánh với Đức Giang (Bài 4.6): yếu tố cố định trong hai bài là gì?","nhinDap":"Đức Giang: điểm K cố định (OK.OH = R²). Mai Dịch: tích MA.AP = R² không đổi. Cả hai dùng một đại lượng không đổi rồi đánh giá bằng bất đẳng thức.","deep":{"huong":[{"ten":"Tính S theo OM","kq":"dai","y":["S = OM.OP; OP liên hệ với OM qua tam giác vuông MOP ⇒ S biểu diễn bằng một phân thức chứa căn của OM, khó tìm giá trị nhỏ nhất ở lớp 9."]},{"ten":"Tổng có tích không đổi","kq":"duoc","y":["MP = MA + AP ≥ 2√(MA.AP) = 2R ⇒ S ≥ 2R²; dấu “=” khi MA = AP = R ⇔ OM = R√2."]}],"binh":["Câu hỏi then chốt của bài cực trị: “tổng nào có tích không đổi?” – hệ thức lượng trong tam giác vuông (MA.AP = OA²) trả lời câu hỏi đó."]},"loai":"sector","gt":["(O; R), H cố định ngoài (O); d ⊥ OH tại H; M ∈ d","MA, MB là tiếp tuyến; I = AB ∩ OM, K = AB ∩ OH","PQ ⊥ OM tại O; P ∈ MA, Q ∈ MB"],"inputs":[{"code":"T2, G6","text":"O là trung điểm PQ","keep":1,"why":""},{"code":"T1","text":"S(MPQ) = R.MP","keep":1,"why":""},{"code":"V1","text":"MA.AP = R²","keep":1,"why":""},{"code":"K6","text":"MP ≥ 2R (Cô-si)","keep":1,"why":""},{"code":"S2","text":"ý b: OH.OK = R²","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∆MPQ cân tại M, O là trung điểm PQ","ld":"MO là phân giác ∠AMB và MO ⊥ PQ","codes":["T2","G6"]},{"cm":"S(MPQ) = 2S(MOP) = OA.MP = R.MP","ld":"OA ⊥ MP","codes":["T1"]},{"cm":"MA.AP = OA² = R²","ld":"∆MOP vuông tại O, đường cao OA","codes":["V1"]},{"cm":"MP = MA + AP ≥ 2√(MA.AP) = 2R ⇒ S(MPQ) ≥ 2R²","ld":"Bất đẳng thức Cô-si; từ 2 và 3","codes":[]},{"cm":"Dấu “=” ⇔ MA = AP = R ⇔ OM = R√2","ld":"∆MOP vuông cân tại O","codes":[]},{"cm":"S nhỏ nhất bằng 2R² khi HM = √(2R² − OH²)","ld":"M là giao điểm của d với (O; R√2) (cần OH < R√2)","codes":[]}]},{"boost":["B6"],"id":"5.1","ch":5,"truong":"Trưng Vương","ky":"cuối HKI","de":["Cho đường tròn (O; R) đường kính AB. Từ A kẻ tiếp tuyến Ax với đường tròn (O). Trên tia Ax lấy điểm M sao cho MA > R. Từ M kẻ tiếp tuyến MC với đường tròn (O) (C là tiếp điểm).","1) Chứng minh bốn điểm A, O, C, M cùng thuộc một đường tròn.","2) Gọi E là giao điểm của MB với đường tròn tâm O. Chứng minh OM song song với BC và ∠BMO = ∠CAE.","3) Từ B kẻ tiếp tuyến By với đường tròn (O). Đường thẳng qua O và song song với AC, cắt By tại D. Gọi I là trung điểm của OB. Chứng minh MB vuông góc với ID."],"yl":"3","yc":"Từ B kẻ tiếp tuyến By với đường tròn (O). Đường thẳng qua O và song song với AC, cắt By tại D. Gọi I là trung điểm của OB. Chứng minh MB vuông góc với ID.","kl":"MB ⊥ ID","hinh":"img/b5.1.png","huong":"∠BID + ∠ABM = 90°.","giu":"OM // BC; ý c dùng OM ⊥ AC.","noi":"∠BOD = ∠AMO (cùng phụ ∠AOM) nên ∆OBD ∽ ∆MAO; thay OB = 2IB, AO = AB/2 được ∆IBD ∽ ∆MAB.","nhin":"Nếu I là điểm chia OB theo tỉ số khác thì MB còn vuông góc với ID không? Vì sao?","nhinDap":"Không còn đúng nói chung: cặp ∆IBD ∽ ∆MAB cần IB = OB/2. Thử trên phần mềm với I khác trung điểm sẽ thấy MB không vuông góc với ID.","deep":{"huong":[{"ten":"Tỉ số lượng giác","kq":"duoc","y":["∠BOD = ∠AMO ⇒ BD = OB.tan∠BOD = R.AO/MA = R²/MA.","tan∠BID = BD/IB = (R²/MA)/(R/2) = 2R/MA = AB/MA = tan∠AMB ⇒ ∠BID = ∠AMB."]},{"ten":"Nhân đôi – chia đôi","kq":"duoc","y":["∆OBD ∽ ∆MAO ⇒ BD/AO = OB/MA; thay OB = 2IB, AO = AB/2 ⇒ IB/MA = BD/AB ⇒ ∆IBD ∽ ∆MAB ⇒ ∠BID = ∠AMB."]}],"binh":["Hai hướng là một ý tưởng viết bằng hai ngôn ngữ (tỉ số lượng giác và tam giác đồng dạng). Dấu hiệu nhận ra: trung điểm I của OB và trung điểm O của AB – một cạnh bị chia đôi, cạnh tương ứng bị nhân đôi."]},"loai":"sector","gt":["(O; R) đường kính AB; Ax là tiếp tuyến; M ∈ Ax, MA > R; MC là tiếp tuyến","By là tiếp tuyến; OD // AC, D ∈ By","I là trung điểm OB"],"inputs":[{"code":"T2","text":"OD ⊥ OM","keep":1,"why":""},{"code":"G4","text":"∠BOD = ∠AMO","keep":1,"why":""},{"code":"S3","text":"∆OBD ∽ ∆MAO","keep":1,"why":""},{"code":"B6","text":"nhân đôi – chia đôi: ∆IBD ∽ ∆MAB","keep":1,"why":""},{"code":"G7","text":"∠BID + ∠ABM = 90°","keep":1,"why":""},{"code":"S1","text":"ý b","keep":0,"why":"Không phục vụ điều đang cần ở ý 3."}],"steps":[{"cm":"OD ⊥ OM ⇒ ∠AOM + ∠BOD = 90°","ld":"OM ⊥ AC (OM là trung trực của AC); OD // AC","codes":["T2"]},{"cm":"∠BOD = ∠AMO","ld":"Cùng phụ ∠AOM","codes":["G4"]},{"cm":"∆OBD ∽ ∆MAO ⇒ BD/AO = OB/MA","ld":"∠OBD = ∠MAO = 90°; từ 2 (g.g)","codes":["S3"]},{"cm":"IB/MA = BD/AB","ld":"OB = 2IB, AO = AB/2","codes":["B6"]},{"cm":"∆IBD ∽ ∆MAB ⇒ ∠BID = ∠AMB","ld":"∠IBD = ∠MAB = 90°; từ 4 (c.g.c)","codes":["S1"]},{"cm":"Gọi J = MB ∩ ID: ∠JIB + ∠JBI = ∠AMB + ∠ABM = 90° ⇒ MB ⊥ ID","ld":"","codes":["G7","K3"]}]},{"boost":[],"id":"5.2","ch":5,"truong":"Ái Mộ – Hát Môn","ky":"cuối HKI","de":["Cho đường tròn (O; R), đường kính AB. Lấy điểm C thuộc (O; R) sao cho AC > BC. Kẻ đường cao CH của ∆ABC (H ∈ AB), kéo dài CH cắt (O; R) tại điểm D (D ≠ C). Tiếp tuyến tại điểm A và tiếp tuyến tại điểm C của đường tròn (O; R) cắt nhau tại điểm M. Gọi I là giao điểm của OM và AC. Hai đường thẳng MC và AB cắt nhau tại F.","a) Chứng minh 4 điểm A, C, M, O cùng thuộc một đường tròn.","b) Chứng minh DF là tiếp tuyến của (O; R).","c) Chứng minh BC = 2.IO và AF.BH = BF.AH."],"yl":"c","yc":"Chứng minh BC = 2.IO và AF.BH = BF.AH.","kl":"AF.BH = BF.AH","hinh":"img/b5.2.png","huong":"FB/FA = HB/HA.","giu":"DF là tiếp tuyến; BC = 2.IO.","noi":"Cần AF/BF = AH/BH. ∆FCB ∽ ∆FAC cho FB/FA = (CB/CA)²; hệ thức lượng cho BH/AH = (BC/AC)².","nhin":"FB/FA và HB/HA cùng bằng biểu thức nào? Còn tỉ số nào khác bằng chúng?","nhinDap":"Cả hai bằng (CB/CA)². Tỉ số này cũng bằng FC²/FA² (vì FB.FA = FC²).","deep":{"huong":[{"ten":"Phân giác trong và phân giác ngoài","kq":"duoc","y":["∠FCB = ∠CAB = ∠BCH ⇒ CB là phân giác của ∠FCH ⇒ BF/BH = CF/CH.","CA ⊥ CB nên CA là phân giác ngoài tại C của ∆FCH ⇒ AF/AH = CF/CH ⇒ AF/AH = BF/BH."]},{"ten":"Bình phương tỉ số","kq":"duoc","y":["∆FCB ∽ ∆FAC ⇒ FB/FA = (CB/AC)²; hệ thức lượng: BH/AH = (BC/AC)² ⇒ FB/FA = BH/AH."]}],"binh":["Hướng 2 dùng mẹo “tỉ số trung gian là bình phương”: khi hai tỉ số không có đoạn chung, hãy xem chúng có cùng bằng (BC/AC)² không (Chương 0, §2)."]},"loai":"sector","gt":["(O; R) đường kính AB; C ∈ (O), AC > BC; CH ⊥ AB, CH cắt (O) tại D","Tiếp tuyến tại A, C cắt nhau tại M; I = OM ∩ AC","F = MC ∩ AB"],"inputs":[{"code":"T2, P2","text":"BC = 2.IO","keep":1,"why":""},{"code":"G3","text":"∠FCB = ∠FAC","keep":1,"why":""},{"code":"S1","text":"FB/FA = (CB/CA)²","keep":1,"why":""},{"code":"V1","text":"BH/AH = (BC/AC)²","keep":1,"why":""},{"code":"T1","text":"ý b: DF là tiếp tuyến","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"I là trung điểm AC ⇒ OI là đường trung bình ⇒ BC = 2.IO","ld":"MA = MC, OA = OC: OM là trung trực của AC","codes":["T2","P2"]},{"cm":"∠FCB = 90° − ∠OCB = 90° − ∠ABC = ∠CAB","ld":"∠OCF = 90°; ∆OBC cân; ∠ACB = 90°","codes":["T1","G6"]},{"cm":"∆FCB ∽ ∆FAC ⇒ FB/FC = FC/FA = CB/AC","ld":"∠F chung; từ 2 (g.g)","codes":["S1"]},{"cm":"FB/FA = (FB/FC).(FC/FA) = (CB/AC)²","ld":"Từ 3","codes":[]},{"cm":"BH/AH = (BC/AC)²","ld":"BC² = BH.AB, AC² = AH.AB","codes":["V1"]},{"cm":"FB/FA = BH/AH ⇒ AF.BH = BF.AH","ld":"Từ 4 và 5","codes":["K6"]}]},{"boost":["B6"],"id":"5.3","ch":5,"truong":"Lý Sơn","ky":"cuối HKI","de":["Cho đường tròn (O), đường kính AB. Kẻ tiếp tuyến Ax với đường tròn (O). Lấy điểm C thuộc đường tròn (O) (AC < CB). Kẻ tiếp tuyến tại C của đường tròn (O) cắt Ax tại điểm M.","a) Chứng minh bốn điểm M, A, C, O cùng thuộc một đường tròn.","b) Qua điểm O kẻ đường thẳng vuông góc với BC tại H, cắt đường thẳng MC tại K. Đường thẳng AH cắt đường tròn (O) tại N (N khác A), đường thẳng BN cắt OK tại điểm I. Chứng minh KB là tiếp tuyến của đường tròn (O) và ∠IBK = ∠HAB.","c) Chứng minh BC.KI = BH.KH."],"yl":"c","yc":"Chứng minh BC.KI = BH.KH.","kl":"BC.KI = BH.KH","hinh":"img/b5.3.png","huong":"I là trung điểm của KH.","giu":"KB là tiếp tuyến; ∠IBK = ∠HAB.","noi":"BC = 2BH nên hệ thức là KI = KH/2: I là trung điểm KH. ∆KHB ∽ ∆BCA có KH ứng với BC.","nhin":"Cặp tam giác nào cho KI, cặp nào cho KH? Chúng có chung tỉ số nào?","nhinDap":"∆KBI ∽ ∆BAH cho KI/BH = KB/BA; ∆KHB ∽ ∆BCA cho KH/BC = KB/BA. Chung tỉ số KB/BA.","deep":{"huong":[{"ten":"Tỉ số trung gian","kq":"duoc","y":["∆KBI ∽ ∆BAH ⇒ KI/BH = KB/BA; ∆KHB ∽ ∆BCA ⇒ KH/BC = KB/BA ⇒ KI/BH = KH/BC."]},{"ten":"Bài toán phụ 6, đảo dạng 2","kq":"duoc","y":["∆KHB ∽ ∆BCA (KH ↔ BC). H là trung điểm BC; gọi I' là trung điểm KH ⇒ ∆KBI' ∽ ∆BAH ⇒ ∠KBI' = ∠BAH = ∠KBI ⇒ I' trùng I."]}],"binh":["Nhận ra BC = 2BH biến một đẳng thức tích thành một kết luận trung điểm – rõ ràng hơn và gợi ra bài toán phụ 6."]},"loai":"sector","gt":["(O) đường kính AB; Ax là tiếp tuyến; C ∈ (O), AC < CB; tiếp tuyến tại C cắt Ax tại M","OH ⊥ BC tại H, OH cắt MC tại K","AH cắt (O) tại N; BN cắt OK tại I"],"inputs":[{"code":"G4","text":"∠BKH = ∠ABC","keep":1,"why":""},{"code":"S1","text":"ý b: ∆KBI ∽ ∆BAH","keep":1,"why":""},{"code":"S3","text":"∆KHB ∽ ∆BCA","keep":1,"why":""},{"code":"K6","text":"KI/BH = KH/BC","keep":1,"why":""},{"code":"B6","text":"nhận xét: I là trung điểm KH","keep":1,"why":""}],"steps":[{"cm":"∠BKH = 90° − ∠BOK = ∠OBH = ∠ABC","ld":"∆OBK vuông tại B, BH ⊥ OK","codes":["G4"]},{"cm":"∆KBI ∽ ∆BAH ⇒ KI/BH = KB/BA","ld":"∠KBI = ∠BAH (ý b); ∠BKI = ∠ABH (dòng 1) (g.g)","codes":["S1"]},{"cm":"∆KHB ∽ ∆BCA ⇒ KH/BC = KB/BA","ld":"∠KHB = ∠BCA = 90°; ∠HKB = ∠CBA (g.g)","codes":["S3"]},{"cm":"KI/BH = KH/BC ⇒ BC.KI = BH.KH","ld":"Từ 2 và 3","codes":["K6"]},{"cm":"Nhận xét: BC = 2BH nên KI = KH/2, I là trung điểm KH","ld":"OH ⊥ BC ⇒ H là trung điểm BC","codes":["N4","B6"]}]},{"boost":["B1","B4"],"id":"5.4","ch":5,"truong":"Cầu Diễn","ky":"cuối HKI","de":["Cho đường tròn (O; R), đường kính AB. Trên đường tròn (O) lấy điểm M (MA < MB). Tiếp tuyến tại M cắt tiếp tuyến tại A và B lần lượt là C và D.","a) Chứng minh: CD = AC + BD.","b) Vẽ đường thẳng BM cắt tia AC tại E và vẽ MH ⊥ AB. Chứng minh: OC // MB và ME.MB = AH.AB.","c) Chứng minh: HM là tia phân giác của ∠CHD."],"yl":"c","yc":"Chứng minh: HM là tia phân giác của ∠CHD.","kl":"HM là tia phân giác ∠CHD","hinh":"img/b5.4.png","huong":"∠CHA = ∠DHB (∆CAH ∽ ∆DBH).","giu":"OC // MB; ME.MB = AH.AB; CD = AC + BD.","noi":"AH/HB = CM/MD = CA/DB (ba đường song song chắn hai cát tuyến, CM = CA, DM = DB).","nhin":"Giải lại ý c bằng bài toán phụ 4. Cách nào ngắn hơn?","nhinDap":"Bài toán phụ 4 cho BC, AD, MH đồng quy tại trung điểm I của MH; từ đó vẫn phải chứng minh thêm. Cách dùng tỉ số (∆CAH ∽ ∆DBH) ngắn hơn.","deep":{"huong":[{"ten":"Tính góc trực tiếp","kq":"dai","y":["∠CHM = ∠ACH (so le, AC // MH); cần ∠ACH = ∠BDH – lại quy về so sánh hai tam giác CAH và DBH."]},{"ten":"Ba đường song song (bổ đề hình thang)","kq":"duoc","y":["G = AD ∩ MH: AH/AB = AG/AD = CM/CD ⇒ AH/HB = CM/MD = CA/DB.","∆CAH ∽ ∆DBH (c.g.c) ⇒ ∠CHA = ∠DHB ⇒ ∠CHM = ∠DHM."]}],"binh":["Hình thang ACDB với MH song song hai đáy: tỉ số trên hai cạnh bên bằng nhau – đúng tinh thần của bổ đề hình thang (bài toán phụ 1). Bài toán phụ 4 cũng có trong hình: AD đi qua trung điểm G của MH."]},"loai":"sector","gt":["(O; R) đường kính AB; M ∈ (O), MA < MB","Tiếp tuyến tại M cắt tiếp tuyến tại A, B ở C, D","MH ⊥ AB"],"inputs":[{"code":"T3, P3","text":"AC // MH // BD","keep":1,"why":""},{"code":"P1","text":"AH/HB = CM/MD","keep":1,"why":""},{"code":"T2","text":"CA/DB = AH/BH","keep":1,"why":""},{"code":"S1","text":"∆CAH ∽ ∆DBH","keep":1,"why":""},{"code":"G4","text":"∠CHM = ∠DHM","keep":1,"why":""},{"code":"B4","text":"BC, AD qua trung điểm MH","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"AC // MH // BD","ld":"Cùng vuông góc với AB","codes":["T3","P3"]},{"cm":"Gọi G = AD ∩ MH: AH/AB = AG/AD = CM/CD ⇒ AH/HB = CM/MD","ld":"Hệ quả định lí Thales trong ∆ABD, ∆DAC","codes":["P1"]},{"cm":"AH/HB = CA/DB","ld":"CM = CA, MD = DB","codes":["T2"]},{"cm":"∆CAH ∽ ∆DBH ⇒ ∠CHA = ∠DHB","ld":"∠CAH = ∠DBH = 90°; từ 3 (c.g.c)","codes":["S1"]},{"cm":"∠CHM = 90° − ∠CHA = 90° − ∠DHB = ∠DHM","ld":"Phụ với hai góc bằng nhau","codes":["G4"]}]},{"boost":["B4","B2","B6"],"id":"5.6","ch":5,"truong":"Nguyễn Bỉnh Khiêm","ky":"cuối HKI","de":["Cho nửa đường tròn (O; R) đường kính BC. Trên nửa đường tròn (O) vẽ tiếp tuyến Bx của đường tròn (O), A là điểm bất kì thuộc nửa đường tròn sao cho AB < AC (A khác B, A khác C). Tiếp tuyến tại A của nửa đường tròn (O) cắt tia Bx tại D.","a) Chứng minh 4 điểm A, D, B, O cùng thuộc một đường tròn.","b) Tia CA cắt Bx tại E. Chứng minh rằng OD ⊥ AB và CA.CE = 4R².","c) Gọi H là hình chiếu của A trên BC và I là trung điểm của AC, OD cắt AB tại điểm K. Chứng minh ba đường thẳng AH, KI, CD đồng quy."],"yl":"c","yc":"Gọi H là hình chiếu của A trên BC và I là trung điểm của AC, OD cắt AB tại điểm K. Chứng minh ba đường thẳng AH, KI, CD đồng quy.","kl":"AH, KI, CD đồng quy","hinh":"img/b5.6.png","huong":"AH, KI, CD cùng đi qua trung điểm J của AH.","giu":"OD ⊥ AB tại K (K là trung điểm AB); CA.CE = 4R².","noi":"D là trung điểm của BE (giống bài toán phụ 4); AH // BE (cùng ⊥ BC).","nhin":"Nếu chưa biết bài toán phụ, em phải vẽ thêm điểm nào để giải?","nhinDap":"Phải gọi E = CA ∩ Bx rồi tự chứng minh D là trung điểm BE (DA = DB = DE), sau đó dùng Thales trong ∆CBE.","deep":{"huong":[{"ten":"Gọi J là giao điểm của AH và CD, chứng minh KI đi qua J bằng góc","kq":"tac","y":["Không có góc nào tại J tính được."]},{"ten":"Trung điểm chung","kq":"duoc","y":["DA = DB ⇒ DE = DA ⇒ D là trung điểm BE; AH // BE ⇒ CD đi qua trung điểm J của AH.","KI là đường trung bình của ∆ABC ⇒ KI // BC ⇒ KI đi qua trung điểm của AH."]}],"binh":["Ba đường đồng quy được đổi thành “cùng đi qua một trung điểm”. Dự đoán điểm đồng quy (bằng hình vẽ chính xác hoặc GeoGebra) là bước quan trọng."]},"loai":"sector","gt":["Nửa (O; R) đường kính BC; Bx là tiếp tuyến; A thuộc nửa đường tròn (AB < AC)","Tiếp tuyến tại A cắt Bx tại D; E = CA ∩ Bx","AH ⊥ BC; I là trung điểm AC; K = OD ∩ AB"],"inputs":[{"code":"T2, G6","text":"DA = DB","keep":1,"why":""},{"code":"G2, G7","text":"DE = DA: D là trung điểm BE","keep":1,"why":""},{"code":"P3","text":"AH // BE","keep":1,"why":""},{"code":"B2","text":"CD chia đôi AH tại J","keep":1,"why":""},{"code":"P2","text":"KI // BC qua trung điểm AH","keep":1,"why":""},{"code":"V1","text":"ý b: CA.CE = 4R²","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"DA = DB ⇒ ∠DBA = ∠DAB","ld":"Hai tiếp tuyến cắt nhau","codes":["T2","G6"]},{"cm":"∠DEA = 90° − ∠DBA = 90° − ∠DAB = ∠DAE ⇒ DE = DA","ld":"∠BAE = 90° (∠BAC chắn nửa đường tròn)","codes":["G2","G7"]},{"cm":"DB = DE: D là trung điểm BE","ld":"Từ 1 và 2","codes":[]},{"cm":"AH // BE","ld":"AH ⊥ BC, BE ⊥ BC","codes":["P3"]},{"cm":"Gọi J = CD ∩ AH: HJ/BD = CJ/CD = JA/DE ⇒ HJ = JA","ld":"Thales trong ∆CBD, ∆CDE; từ 3","codes":["P1","B2"]},{"cm":"KI // BC và KI đi qua trung điểm J của AH","ld":"K, I là trung điểm AB, AC","codes":["P2"]},{"cm":"AH, KI, CD đồng quy tại J","ld":"","codes":["K5"]}]},{"boost":["B6"],"id":"5.7","ch":5,"truong":"Nam Từ Liêm","ky":"giữa HKII","de":["Cho đường tròn tâm (O) và một điểm A nằm ngoài đường tròn. Từ điểm A kẻ tiếp tuyến AB với đường tròn (O) (B là tiếp điểm) và kẻ đường kính BC. Trên đoạn thẳng CO lấy điểm I (I khác O, I khác C). Đường thẳng IA cắt (O) tại hai điểm D và E (D nằm giữa A và E). Gọi H là trung điểm của đoạn thẳng DE.","a) Chứng minh tứ giác ABOH nội tiếp.","b) Từ điểm E kẻ đường thẳng song song với AO và cắt BC tại điểm K. Chứng minh IB.IK = IH.IE.","c) Tia CD cắt AO tại điểm P, tia EO cắt BP tại điểm F. Chứng minh ∆EHB ∽ ∆COP và điểm F nằm trên đường tròn (O)."],"yl":"c","yc":"Tia CD cắt AO tại điểm P, tia EO cắt BP tại điểm F. Chứng minh ∆EHB ∽ ∆COP và điểm F nằm trên đường tròn (O).","kl":"∆EHB ∽ ∆COP; F nằm trên (O)","hinh":"img/b5.7.png","huong":"∠EBP = 90°, rồi suy ra OF = OB.","giu":"ABOH nội tiếp; IB.IK = IH.IE.","noi":"H là trung điểm ED (cạnh của ∆BED), O là trung điểm CB (cạnh của ∆PCB); ∆EHB ∽ ∆COP với hai trung tuyến BH, PO.","nhin":"F nằm trên (O) suy ra từ góc nào bằng 90°?","nhinDap":"Từ ∠EBF = 90° và OB = OE (O nằm trên EF) suy ra OF = OB = R.","deep":{"huong":[{"ten":"Chứng minh OF = R trực tiếp","kq":"tac","y":["F là giao của EO với BP; độ dài OF không tính được từ các dữ kiện."]},{"ten":"Bài toán phụ 6, chiều đảo dạng 1","kq":"duoc","y":["∆EHB ∽ ∆COP; BH, PO là hai trung tuyến tương ứng ⇒ ∆BED ∽ ∆PCB ⇒ ∠BDE = ∠PBC.","∠EBP = ∠EDC + ∠BDE = ∠BDC = 90° ⇒ OF = OB."]}],"binh":["Chiều đảo dạng 1 của bài toán phụ 6 ít gặp nhưng rất mạnh: từ cặp “nửa tam giác” (chứa trung tuyến) suy ra cặp tam giác lớn."]},"loai":"sector","gt":["(O), A ngoài; AB là tiếp tuyến; BC là đường kính; I ∈ CO","IA cắt (O) tại D, E (D nằm giữa A, E); H là trung điểm DE","EK // AO, K ∈ BC; tia CD cắt AO tại P; tia EO cắt BP tại F"],"inputs":[{"code":"G1","text":"∠HEB = ∠OCP","keep":1,"why":""},{"code":"N3","text":"∠EHB = ∠COP","keep":1,"why":""},{"code":"S1","text":"∆EHB ∽ ∆COP","keep":1,"why":""},{"code":"B6","text":"đảo dạng 1: ∠BDE = ∠PBC","keep":1,"why":""},{"code":"G2","text":"∠EBP = 90°","keep":1,"why":""},{"code":"G6","text":"OF = OB","keep":1,"why":""},{"code":"S2","text":"ý b","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∠HEB = ∠DEB = ∠DCB = ∠PCO","ld":"Cùng chắn cung DB; P ∈ tia CD","codes":["G1"]},{"cm":"∠EHB = 180° − ∠AHB = 180° − ∠AOB = ∠COP","ld":"ABOH nội tiếp (ý a)","codes":["N3"]},{"cm":"∆EHB ∽ ∆COP","ld":"Từ 1 và 2 (g.g)","codes":["S1"]},{"cm":"∆BED ∽ ∆PCB ⇒ ∠BDE = ∠PBC","ld":"BH, PO là trung tuyến tương ứng (H, O là trung điểm ED, CB) – chiều đảo dạng 1","codes":["B6"]},{"cm":"∠EBP = ∠EBC + ∠CBP = ∠EDC + ∠BDE = ∠BDC = 90°","ld":"Cùng chắn cung EC; ∠BDC chắn nửa đường tròn","codes":["G1","G2"]},{"cm":"∠OBF = 90° − ∠OBE = 90° − ∠OEB = ∠OFB ⇒ OF = OB: F ∈ (O)","ld":"∆EBF vuông tại B; OB = OE","codes":["G6","G7"]}]},{"boost":[],"id":"5.8","ch":5,"truong":"Đức Giang","ky":"giữa HKII","de":["Cho (O) đường kính AB, gọi I là trung điểm của OA, dây CD vuông góc với AB tại I. Lấy K tùy ý trên cung BC nhỏ, AK cắt CD tại H.","a) Chứng minh tứ giác BIHK là tứ giác nội tiếp.","b) Chứng minh AH.AK = R².","c) Kẻ DN vuông góc với CB tại N, DM vuông góc với AC tại M. Chứng minh các đường thẳng MN, AB, CD đồng quy."],"yl":"c","yc":"Kẻ DN vuông góc với CB tại N, DM vuông góc với AC tại M. Chứng minh các đường thẳng MN, AB, CD đồng quy.","kl":"MN, AB, CD đồng quy","hinh":"img/b5.8.png","huong":"MN đi qua I.","giu":"AH.AK = R². Ý c chỉ cần CD ⊥ AB tại I.","noi":"I là trung điểm CD. MCND là hình chữ nhật (∠MCN = ∠CMD = ∠CND = 90°).","nhin":"I là tâm của hình nào? Điểm “nhiều vai” này giống bài nào ở Chương 4?","nhinDap":"I là tâm của hình chữ nhật MCND. Giống Bài 4.7 (Nghĩa Tân: hình bình hành IJMB) và Bài 4.3 (hình bình hành BECD).","deep":{"huong":[{"ten":"Gọi I' = MN ∩ CD, chứng minh I' nằm trên AB","kq":"dai","y":["Cần góc hoặc tỉ số tại I'; vòng vèo."]},{"ten":"Hình chữ nhật MCND","kq":"duoc","y":["∠MCN = ∠CMD = ∠CND = 90° ⇒ MCND là hình chữ nhật ⇒ MN đi qua trung điểm I của CD."]}],"binh":["“Đồng quy với hai đường đã cắt nhau” luôn được đổi thành “đi qua giao điểm đã biết”. Ở đây giao điểm đó lại là trung điểm – rất thuận lợi."]},"loai":"sector","gt":["(O) đường kính AB; I là trung điểm OA; dây CD ⊥ AB tại I","K ∈ cung BC nhỏ; H = AK ∩ CD","DN ⊥ CB, DM ⊥ AC"],"inputs":[{"code":"G2","text":"∠MCN = 90°","keep":1,"why":""},{"code":"V5","text":"MCND là hình chữ nhật","keep":1,"why":""},{"code":"N4","text":"I là trung điểm CD","keep":1,"why":""},{"code":"K5","text":"MN đi qua I","keep":1,"why":""},{"code":"S2","text":"ý b: AH.AK = R²","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∠MCN = 90°","ld":"∠ACB chắn nửa đường tròn","codes":["G2"]},{"cm":"MCND là hình chữ nhật ⇒ MN, CD cắt nhau tại trung điểm mỗi đường","ld":"∠MCN = ∠CMD = ∠CND = 90°","codes":["V5"]},{"cm":"I là trung điểm CD","ld":"Đường kính AB vuông góc với dây CD tại I","codes":["N4"]},{"cm":"MN đi qua I ⇒ MN, AB, CD đồng quy tại I","ld":"Từ 2 và 3","codes":["K5"]}]},{"boost":[],"id":"5.9","ch":5,"truong":"Ngô Gia Tự – đề 1","ky":"cuối HKII","de":["Cho nửa đường tròn (O), đường kính AB. Lấy điểm D thuộc nửa đường tròn, điểm C thuộc cung AD; AC cắt BD tại E, AD cắt BC tại H.","a) Chứng minh tứ giác CHDE nội tiếp.","b) Chứng minh ∠DAB = ∠DEH.","c) Vẽ tiếp tuyến của (O) tại D, cắt EH tại I. Chứng minh I là trung điểm của EH."],"yl":"c","yc":"Vẽ tiếp tuyến của (O) tại D, cắt EH tại I. Chứng minh I là trung điểm của EH.","kl":"I là trung điểm EH","hinh":"img/b5.9.png","huong":"ID = IE và ID = IH.","giu":"∠DAB = ∠DEH (ý b); CHDE nội tiếp.","noi":"H là trực tâm của ∆ABE (AD, BC là hai đường cao). EH là đường kính của đường tròn qua C, D; I có thể là tâm đường tròn đó.","nhin":"Đường tròn nào có tâm I? Từ đó còn suy ra được tiếp tuyến nào khác?","nhinDap":"Đường tròn tâm I đường kính EH đi qua C, D. Tương tự, tiếp tuyến tại C của (O) cũng đi qua I.","deep":{"huong":[{"ten":"Điểm trùng","kq":"duoc","y":["Gọi I' là trung điểm EH ⇒ I'D = I'E (∆EDH vuông tại D) ⇒ ∠I'DE = ∠I'ED = ∠DAB = ∠ODA.","Suy ra ∠I'DO = ∠I'DE + ∠EDO = ∠ODA + ∠EDO = ∠EDA = 90° ⇒ I'D là tiếp tuyến ⇒ I' trùng I."]},{"ten":"Hai tam giác cân","kq":"duoc","y":["∠IDE = ∠HDO = ∠DAB = ∠IED ⇒ IE = ID; ∠IDH = ∠IHD ⇒ ID = IH."]}],"binh":["Hai hướng đi ngược chiều nhau: một hướng đi từ I (giao điểm) tới trung điểm, một hướng đi từ trung điểm tới tiếp tuyến. Kỹ thuật điểm trùng thường cho lời giải gọn khi điểm cần chứng minh được cho bằng giao điểm."]},"loai":"sector","gt":["Nửa (O) đường kính AB; D ∈ nửa đường tròn, C ∈ cung AD","E = AC ∩ BD, H = AD ∩ BC","Tiếp tuyến tại D cắt EH tại I"],"inputs":[{"code":"T1, G4","text":"∠IDE = ∠HDO","keep":1,"why":""},{"code":"G6","text":"∠HDO = ∠OAD","keep":1,"why":""},{"code":"S1","text":"ý b: ∠DAB = ∠DEH ⇒ IE = ID","keep":1,"why":""},{"code":"G7, G6","text":"ID = IH","keep":1,"why":""},{"code":"K2","text":"IE = ID = IH","keep":1,"why":""},{"code":"Q1","text":"H là trực tâm ∆ABE","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"∠IDE = ∠HDO","ld":"∠IDO = 90° (tiếp tuyến), ∠EDH = 90°","codes":["T1","G2","G4"]},{"cm":"∠HDO = ∠OAD = ∠DAB = ∠DEH ⇒ ∠IDE = ∠IED ⇒ IE = ID","ld":"∆OAD cân tại O; ý b","codes":["G6","G6"]},{"cm":"∠IDH = 90° − ∠IDE = 90° − ∠IED = ∠IHD ⇒ ID = IH","ld":"∆EDH vuông tại D","codes":["G7","G6"]},{"cm":"IE = IH, I ∈ EH ⇒ I là trung điểm EH","ld":"Từ 2 và 3","codes":["K2"]}]},{"boost":["B6"],"id":"5.10","ch":5,"truong":"Nguyễn Du","ky":"cuối HKII","de":["Cho đường tròn tâm O đường kính AB. Lấy điểm C thuộc (O) sao cho AC < BC. Kẻ đường thẳng d là tiếp tuyến của (O) tại A. Tiếp tuyến của (O) tại C cắt đường thẳng d tại D.","a) Chứng minh tứ giác ADCO nội tiếp.","b) Kẻ đường kính CF của (O). Gọi E là giao của DF với (O) (E khác F). Gọi H là giao điểm của DO và AC. Chứng minh DE.DF = DC² và ∠HEF = ∠DOC.","c) Gọi M là trung điểm của DH; gọi K là giao của CM và FH. Chứng minh K thuộc (O)."],"yl":"c","yc":"Gọi M là trung điểm của DH; gọi K là giao của CM và FH. Chứng minh K thuộc (O).","kl":"K thuộc (O)","hinh":"img/b5.10.png","huong":"∠CKF = 90°.","giu":"DE.DF = DC²; ∠HEF = ∠DOC; DO ⊥ AC tại H.","noi":"∆OCD ∽ ∆CHD; nhân đôi OC thành CF, chia đôi HD thành DM được ∆CDM ∽ ∆FCH (c.g.c).","nhin":"Đặt bài cạnh Trưng Vương cuối HKI (Bài 5.1): cách “nhân đôi – chia đôi” cạnh giống nhau ra sao?","nhinDap":"Cả hai đi từ một cặp tam giác vuông đồng dạng, nhân đôi một cạnh và chia đôi cạnh kề còn lại ở tam giác kia (bài toán phụ 6, dạng nhân đôi – chia đôi) để có cặp mới.","deep":{"huong":[{"ten":"Chứng minh OK = R","kq":"tac","y":["K là giao của CM và FH; không tính được OK."]},{"ten":"Nhân đôi – chia đôi","kq":"duoc","y":["∆OCD ∽ ∆CHD ⇒ CD/CF = DM/CH và ∠CDM = ∠FCH ⇒ ∆CDM ∽ ∆FCH ⇒ ∠DCK = ∠CFK ⇒ ∠CKF = 90°."]}],"binh":["Bài 5.1, 5.10 và 3.9, 3.10 cùng một ý tưởng. Gom chúng lại thành chuỗi “nhân đôi – chia đôi” để ôn trước kì thi."]},"loai":"sector","gt":["(O) đường kính AB; C ∈ (O), AC < BC; d là tiếp tuyến tại A; tiếp tuyến tại C cắt d tại D","CF là đường kính; E = DF ∩ (O); H = DO ∩ AC","M là trung điểm DH; K = CM ∩ FH"],"inputs":[{"code":"T2","text":"DO ⊥ AC tại H","keep":1,"why":""},{"code":"S3","text":"∆OCD ∽ ∆CHD","keep":1,"why":""},{"code":"B6","text":"nhân đôi OC, chia đôi HD: ∆CDM ∽ ∆FCH","keep":1,"why":""},{"code":"G7","text":"∠CKF = 90°","keep":1,"why":""},{"code":"N1","text":"K nhìn đường kính CF dưới góc vuông","keep":1,"why":""},{"code":"S2","text":"ý b","keep":0,"why":"Không phục vụ điều đang cần ở ý c."}],"steps":[{"cm":"DO ⊥ AC tại H","ld":"DA = DC, OA = OC","codes":["T2"]},{"cm":"∆OCD ∽ ∆CHD ⇒ OC/CH = CD/HD; ∠ODC = ∠OCH","ld":"∠OCD = ∠CHD = 90°, ∠ODC chung","codes":["S3"]},{"cm":"CD/CF = CD/(2OC) = HD/(2CH) = DM/CH","ld":"CF = 2OC, DM = HD/2; từ 2","codes":["B6"]},{"cm":"∠CDM = ∠ODC = ∠OCH = ∠FCH","ld":"M ∈ DO; F ∈ tia CO; từ 2","codes":[]},{"cm":"∆CDM ∽ ∆FCH ⇒ ∠DCM = ∠CFH","ld":"Từ 3 và 4 (c.g.c)","codes":["S1"]},{"cm":"∠CFK + ∠KCF = ∠DCK + ∠KCF = 90° ⇒ ∠CKF = 90°","ld":"DC ⊥ CF (tiếp tuyến)","codes":["T1","G7"]},{"cm":"K thuộc (O)","ld":"K nhìn đường kính CF dưới góc vuông","codes":["N1"]}]}],"sectors":[{"so":1,"ten":"Tam giác vuông có đường cao và hai hình chiếu","mota":"∆ABC vuông tại A, đường cao AH; M, N là hình chiếu của H trên AB, AC.","y":["AMHN là hình chữ nhật; trung điểm của AH cũng là trung điểm của MN.","AM.AB = AN.AC = AH², do đó ∆AMN ∽ ∆ACB.","Với E là trung điểm của BC: EA = EB = EC và MN ⊥ AE.","HN = AB.sin²B; HM = AC.sin²C."],"bai":["1.1","1.2","1.3","1.4","1.5","1.6","1.7"]},{"so":2,"ten":"Tam giác vuông có trung điểm, trung tuyến","mota":"∆ABC vuông tại A, M là trung điểm của BC hoặc của một cạnh góc vuông; có đường vuông góc hạ xuống trung tuyến.","y":["Trung tuyến AM ứng với cạnh huyền: MA = MB = MC, các tam giác MAB, MAC cân tại M.","Hạ BI ⊥ AM: ∆BIM và ∆AHM là hai tam giác vuông có chung góc M nên đồng dạng.","Khi M là trung điểm của cạnh góc vuông AC và AI ⊥ BM: AM² = MI.MB, mà MA = MC nên MC² = MI.MB, suy ra ∆MIC ∽ ∆MCB.","Cặp tam giác đồng dạng có trung điểm ở hai cạnh tương ứng thì dùng bài toán phụ 6."],"bai":["2.1","2.2","2.3","2.4","2.5","2.6"]},{"so":3,"ten":"Tam giác nhọn nội tiếp đường tròn và các đường cao","mota":"∆ABC nhọn nội tiếp (O); các đường cao AD, BE, CF cắt nhau tại H; AK là đường kính; M là trung điểm của BC.","y":["B, C, E, F cùng thuộc đường tròn đường kính BC; A, E, H, F cùng thuộc đường tròn đường kính AH.","∆AEF ∽ ∆ABC; ∆ABD ∽ ∆AKC nên AB.AC = AD.AK = 2R.AD.","BHCK là hình bình hành nên H, M, K thẳng hàng và AH = 2OM.","AO ⊥ EF."],"bai":["3.1","3.2","3.3","3.4","3.5","3.6","3.7","3.8","3.9","3.10"]},{"so":4,"ten":"Hai tiếp tuyến cắt nhau","mota":"Từ A nằm ngoài (O) kẻ hai tiếp tuyến AB, AC; H là giao điểm của OA và BC; BD là đường kính.","y":["AB = AC; OA là đường trung trực của BC, OA ⊥ BC tại trung điểm H của BC.","OH.OA = R²; AB² = AH.AO; BH² = AH.OH.","CD // OA và CD = 2OH.","Đường thẳng DC cắt BA tại P thì A là trung điểm của BP (bài toán phụ 5)."],"bai":["4.1","4.2","4.3","4.4","4.5","4.6","4.7","4.8","4.9"]},{"so":5,"ten":"Đường kính, tiếp tuyến và dây vuông góc với đường kính","mota":"Đường tròn (O) đường kính AB; tiếp tuyến tại M cắt các tiếp tuyến tại A, B ở C, D; MH ⊥ AB.","y":["CD = AC + BD; ∠COD = 90°; OC // MB, OD // MA.","BM cắt AC tại E thì C là trung điểm của AE.","BC, AD, MH đồng quy tại trung điểm của MH (bài toán phụ 4).","Dây CD vuông góc với đường kính AB tại I thì I là trung điểm của CD; AB là trục đối xứng của hình."],"bai":["5.1","5.2","5.3","5.4","5.5","5.6","5.7","5.8","5.9","5.10"]}],"vdOrder":["4.9","1.2","4.5","5.5","4.4","3.10","1.7","3.2"]};
